    // Each service owns a state domain. The existing state object is a live
    // compatibility facade so UI, timers and saved-page behavior stay intact.
    // Binding preserves existing values, key order and initialization timing.
    function bindFlowStateDomain(runtime, keys) {
        const domain = {};
        for (const key of keys) {
            if (!Object.hasOwn(runtime, key)) throw new Error('Missing flow state: ' + key);
            domain[key] = runtime[key];
            Object.defineProperty(runtime, key, {
                enumerable: true, configurable: true,
                get: () => domain[key], set: value => { domain[key] = value; },
            });
        }
        return domain;
    }

    function createFlowStateDomains(runtime) {
        return {
            task: bindFlowStateDomain(runtime, ['detail', 'session']),
            scan: bindFlowStateDomain(runtime, [
                'scanBuffer', 'scanAt', 'scanBufferTimer', 'scanTerminatorHeld', 'scanSuffixUntil',
                'scanQueue', 'scanFeedback', 'scanProcessing', 'scanWorkerPromise', 'scanSequence',
                'scanDebug', 'scanFinalizeTimer', 'lastScanReceivedAt', 'scanInputCandidate',
                'scanOnly', 'scanAlert', 'quantityInputBurst', 'quantityBeforeInput',
            ]),
            save: bindFlowStateDomain(runtime, [
                'mutationQueue', 'queuedMutations', 'pendingQuantityOps', 'quantitySaveEpoch',
                'outboxSequence', 'outboxOrigin', 'offlineBlockedOrders', 'mutationSyncing',
                'offlineFlushing', 'saveError', 'lastSavedAt', 'quantityDrafts',
            ]),
        };
    }

