function normalizeDashboardPreferences(record) {
    if (!record || record.schema !== 1 || !record.values || Array.isArray(record.values)) return {};
    const value=record.values,result={};
    const allowed={
        orderSource:["pos","sale"],tab:["pending","picking","ready","exception","done","cancelled"],
        sort:["oldest","latest"],days:[0,1,7,30]
    };
    for(const [key,values] of Object.entries(allowed)) if(values.includes(value[key])) result[key]=value[key];
    if(value.salesperson==="all" || /^[1-9]\d*$/.test(String(value.salesperson))) result.salesperson=String(value.salesperson);
    return result;
}

    const DASHBOARD_PREF_KEY = "pb-suite:fulfillment-filters:v1:" + MODE;
    const restoredDashboardPreferences = normalizeDashboardPreferences(loadJson(DASHBOARD_PREF_KEY, null));
    function saveDashboardPreferences() {
        const values = {};
        for (const key of ["orderSource","tab","sort","days","salesperson"]) values[key]=state[key];
        const payload=JSON.stringify({schema:1,values});
        try {
            localStorage.setItem(DASHBOARD_PREF_KEY,payload);
            if(localStorage.getItem(DASHBOARD_PREF_KEY)!==payload) throw new Error("Preference readback failed");
        } catch(error) {
            console.error("[Playbox] Filter preference was not saved",error);
            toast(state.lang === "es" ? "No se guardaron los filtros. Se conservarán solo en esta página." : "筛选设置保存失败，当前页面仍可使用，刷新后可能重置。","warn",5000);
        }
    }
