    function sourceTabs() {
        const color=isColorWorkspaceView(),review=!color&&state.postpaidMode;
        return `<nav class="pbful-source-tabs" aria-label="${t('orderType')}">${['pos','sale'].map(kind=>`<button data-source="${kind}" aria-pressed="${!color&&!review&&state.orderSource===kind}" class="${!color&&!review&&state.orderSource===kind?'active':''}">${t(kind==='sale'?'salesOrders':'posOrders')}</button>`).join('')}<button data-workspace="color-split" aria-pressed="${color}" class="${color?'active':''}">${state.lang==='es'?'Separar colores':'批量拆色'}</button><button data-postpaid-open aria-pressed="${review}" class="${review?'active':''}">${state.lang==='es'?'Después del pago':'付款后补开'}</button></nav>`;
    }
    // One integration for both hosts. The existing module owns color inventory rules.
    class ColorWorkspaceAdapter {
        constructor(runtime, getRoot, getApi, version) {
            this.runtime=runtime;this.getRoot=getRoot;this.getApi=getApi;this.version=version;
            this.current=null;
        }
        async mount() {
            const state=this.runtime;
            if (state.view!=="dashboard" || state.workspacePage!=="color-split") return;
            const container=this.getRoot()?.getElementById("pbful-color-split-mount");
            if (!container) return;
            const api=this.getApi(),lang=state.lang;
            if (typeof api?.mountTo!=="function") {
                // POS opens the same workspace; do not copy the external stock writer.
                if (container.dataset.pbColorFallback===lang) return;
                container.dataset.pbColorFallback=lang;
                container.textContent=lang==='es'
                    ? 'El módulo de colores no está cargado en esta página. Abra el espacio compartido.'
                    : '此页面未加载拆色模块，请打开共用拆色工作台。';
                const button=document.createElement('button');
                button.type='button';button.className='pbful-primary';
                button.textContent=lang==='es'?'Abrir espacio de colores':'打开共用拆色工作台';
                button.addEventListener('click',()=>window.open('/odoo/sales?pbful-page=color-split','_blank','noopener'));
                container.appendChild(button);
                return;
            }
            delete container.dataset.pbColorFallback;
            if (!['1.0.17',this.version].includes(api.version)) {
                container.textContent=lang==='es'
                    ? 'Las versiones del módulo de colores y del surtido no coinciden. Actualice ambos y vuelva a abrir la página.'
                    : '拆色模块与配货工作台版本不一致，请更新为同一套版本后重新打开页面。';
                return;
            }
            if (this.current?.container===container && this.current.api===api && this.current.lang===lang) return this.current.promise;
            const current={container,api,lang,promise:null};this.current=current;
            current.promise=Promise.resolve().then(()=>api.mountTo(container,{lang})).catch(error=>{
                console.error('[Playbox] Color module failed',error);
                if (container.isConnected && this.current===current) container.textContent=lang==='es'
                    ? 'No se pudo abrir el módulo de colores. Vuelva a abrir esta sección.'
                    : '拆色模块打开失败，请重新打开此栏目。';
                if (this.current===current) this.current=null;
            });
            return current.promise;
        }
    }
