    function replacePickerInputRange(input, replacement, start, end) {
        const value = String(input?.value || "");
        const safeStart = Math.max(0, Math.min(Number(start) || 0, value.length));
        const safeEnd = Math.max(safeStart, Math.min(Number(end) || safeStart, value.length));
        input.value = `${value.slice(0, safeStart)}${replacement}${value.slice(safeEnd)}`;
        const caret = safeStart + replacement.length;
        input.setSelectionRange?.(caret, caret);
        state.pickerDraft = input.value;
    }

    function handlePickerInputEvent(event, input) {
        const terminator = isScanTerminator(event);
        const editsText = event.key?.length === 1 || event.key === "Backspace" || event.key === "Delete";
        if (event.type !== "keydown") {
            if (terminator || editsText) stopScannerEvent(event);
            return terminator || editsText;
        }
        if (event.isComposing || event.ctrlKey || event.altKey || event.metaKey) return false;
        if (terminator) {
            stopScannerEvent(event);
            state.pickerDraft = String(input.value || "");
            claim(false).catch(handleMutationError);
            return true;
        }
        if (!editsText) return false;

        stopScannerEvent(event);
        const value = String(input.value || "");
        let start = Number.isInteger(input.selectionStart) ? input.selectionStart : value.length;
        let end = Number.isInteger(input.selectionEnd) ? input.selectionEnd : start;
        if (event.key === "Backspace" && start === end && start > 0) start -= 1;
        else if (event.key === "Delete" && start === end && end < value.length) end += 1;
        const replacement = event.key === "Backspace" || event.key === "Delete" ? "" : event.key;
        replacePickerInputRange(input, replacement, start, end);
        return true;
    }

