    function emptyScanInputCandidate() {
        return { chars: "", startedAt: 0, lastAt: 0, fast: false, timer: null, input: null, startValue: "", start: 0, end: 0 };
    }

    function resetScanInputCandidate(flushManual = false) {
        const candidate = state.scanInputCandidate;
        clearTimeout(candidate?.timer);
        void flushManual;
        state.scanInputCandidate = emptyScanInputCandidate();
    }

    function writeProductInputCharacter(input, character) {
        const value = String(input?.value || "");
        const start = Number.isInteger(input?.selectionStart) ? input.selectionStart : value.length;
        const end = Number.isInteger(input?.selectionEnd) ? input.selectionEnd : start;
        input.value = `${value.slice(0, start)}${character}${value.slice(end)}`;
        const caret = start + character.length;
        input.setSelectionRange?.(caret, caret);
        scheduleProductSearch(input.value);
    }

    function armScanInputCandidateTimer(delay) {
        clearTimeout(state.scanInputCandidate.timer);
        state.scanInputCandidate.timer = setTimeout(() => resetScanInputCandidate(true), delay);
    }

    function isScanTerminator(event) {
        if (event?.key === "Tab" && !event.shiftKey && !event.isComposing && !event.ctrlKey && !event.altKey && !event.metaKey &&
            !state.activePrompt && (state.scanInputCandidate?.fast || quantityBurstIsScan(state.quantityInputBurst) ||
            state.scanBuffer?.length >= 3 || state.scanOnlyInput?.text?.length >= 3)) return true;
        return ["Enter", "Return", "\r", "\n"].includes(event?.key) ||
            ["Enter", "NumpadEnter"].includes(event?.code) || event?.keyCode === 13 || event?.which === 13 ||
            (["beforeinput", "input"].includes(event?.type) && ["insertLineBreak", "insertParagraph"].includes(event?.inputType));
    }

    function acceptScanTerminator(event) {
        // One physical Enter may emit keydown, keypress, beforeinput and keyup.
        // Some keyboard wedges expose only a later phase. Count the press once.
        const held = state.scanTerminatorHeld;
        state.scanTerminatorHeld = event.type !== "keyup";
        return !held && !event.repeat && !event.isComposing && event.keyCode !== 229 &&
            !event.ctrlKey && !event.altKey && !event.metaKey;
    }

    function submitProductInputTerminator(event, input) {
        if (!isScanTerminator(event)) return false;
        const accepted = acceptScanTerminator(event);
        if (event.isComposing || event.keyCode === 229) { event.stopImmediatePropagation(); return true; }
        stopScannerEvent(event);
        if (!accepted || !state.open || state.view !== "detail" || state.activePrompt || state.imagePreview || isReadOnlyDetail()) return true;
        if (performance.now() < state.scanSuffixUntil) return true;
        const candidate = state.scanInputCandidate;
        if (candidate.chars && candidate.fast) {
            const code = candidate.chars;
            resetScanInputCandidate(false);
            // A CR+LF suffix belongs to the same scanner frame.
            state.scanSuffixUntil = performance.now() + HID_MANUAL_FLUSH_MS;
            enqueueCompletedScan(code, "hid");
        } else {
            resetScanInputCandidate(false);
            if (String(input?.value || state.productQuery || "").trim()) commitProductInput(input);
        }
        return true;
    }

    function handleProductInputKeydown(event, input) {
        if (submitProductInputTerminator(event, input)) return true;
        if (event.isComposing || event.ctrlKey || event.altKey || event.metaKey) {
            resetScanInputCandidate(true);
            return false;
        }
        const candidate = state.scanInputCandidate;
        if (event.key?.length !== 1) {
            resetScanInputCandidate(true);
            return false;
        }

        const stamp = event.timeStamp;
        const now = Number.isFinite(stamp) && stamp > 0 ? stamp : performance.now();
        state.scanTerminatorHeld = false;
        state.scanSuffixUntil = 0;
        if (candidate.chars && now - candidate.lastAt > (candidate.fast ? HID_INCOMPLETE_RESET_MS : HID_MANUAL_FLUSH_MS)) resetScanInputCandidate(true);
        const active = state.scanInputCandidate;
        stopScannerEvent(event);
        cancelScanFinalization();
        if (!active.chars) {
            const value = String(input.value || "");
            const start = Number.isInteger(input.selectionStart) ? input.selectionStart : value.length;
            const end = Number.isInteger(input.selectionEnd) ? input.selectionEnd : start;
            Object.assign(active, { chars: event.key, startedAt: now, lastAt: now, fast: false, input, startValue: value, start, end });
            writeProductInputCharacter(input, event.key);
        } else {
            active.chars += event.key;
            active.lastAt = now;
            const averageGap = (active.lastAt - active.startedAt) / Math.max(1, active.chars.length - 1);
            active.fast = active.fast || (active.chars.length >= HID_DETECT_MIN_CHARS && averageGap <= HID_FAST_GAP_MS);
            writeProductInputCharacter(input, event.key);
        }
        armScanInputCandidateTimer(active.fast ? HID_INCOMPLETE_RESET_MS : HID_MANUAL_FLUSH_MS);
        return true;
    }

    function installProductSearchInput() {
        if (!host || productSearchInputElement()) return productSearchInputElement();
        const input = document.createElement("input");
        input.id = "pbful-code";
        input.slot = "pbful-product-input";
        input.type = "text";
        input.autocomplete = "off";
        input.inputMode = "text";
        input.enterKeyHint = "done";
        input.spellcheck = false;
        input.setAttribute("autocapitalize", "none");
        input.setAttribute("role", "combobox");
        input.setAttribute("aria-autocomplete", "list");
        input.setAttribute("aria-controls", "pbful-product-results");
        input.addEventListener("pointerdown", () => { state.productInputFocused = true; state.scanSuffixUntil = 0; });
        input.addEventListener("focus", () => { state.productInputFocused = true; });
        input.addEventListener("blur", () => {
            setTimeout(() => { state.productInputFocused = document.activeElement === input; }, 0);
        });
        input.addEventListener("input", (event) => {
            if (submitProductInputTerminator(event, input)) return;
            state.scanTerminatorHeld = false;
            state.scanSuffixUntil = 0;
            event.stopPropagation();
            if (state.scanInputCandidate?.chars) resetScanInputCandidate(false);
            state.productInputFocused = true;
            scheduleProductSearch(input.value);
        });
        for (const eventName of ["beforeinput", "compositionstart", "compositionupdate", "compositionend", "paste"]) {
            input.addEventListener(eventName, (event) => {
                if (eventName === "beforeinput" && submitProductInputTerminator(event, input)) return;
                if (state.scanInputCandidate?.chars) resetScanInputCandidate(true);
                state.productInputFocused = true;
                event.stopPropagation();
            });
        }
        input.addEventListener("keydown", (event) => {
            state.productInputFocused = true;
            if (event.isComposing) { event.stopPropagation(); return; }
            if (handleProductInputKeydown(event, input)) return;
            if (event.key === "Escape") {
                event.preventDefault(); event.stopImmediatePropagation();
                if (state.productSearching || state.productResults.length || state.productSearchError || String(state.productQuery || "").trim()) clearProductSearch(true);
                else closeOverlay();
                return;
            }
            if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                if (moveProductSearchSelection(event.key === "ArrowDown" ? 1 : -1)) event.preventDefault();
                event.stopImmediatePropagation();
                return;
            }
            if (event.key === "Enter") {
                event.preventDefault(); event.stopImmediatePropagation();
                commitProductInput(input);
                return;
            }
            event.stopPropagation();
        });
        for (const eventName of ["keypress", "keyup"]) input.addEventListener(eventName, (event) => {
            if (!submitProductInputTerminator(event, input)) event.stopPropagation();
        });
        host.appendChild(input);
        productSearchInput = input;
        syncProductSearchInput();
        return input;
    }

