    function esc(value) {
        return String(value ?? "").replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
    }
    function loadJson(key, fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch (_e) { return fallback; } }
    function saveJson(key, value) { localStorage.setItem(key, JSON.stringify(value)); }
    function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }
    function isNetworkError(error) {
        if (error?.odoo) return false;
        return Boolean(error?.retryable || !navigator.onLine || /fetch|network|offline|Failed to fetch/i.test(String(error?.message || error)));
    }
    function apiError(payload) {
        const message = payload?.data?.message || payload?.message || "Odoo RPC error";
        const error = new Error(message);
        error.odoo = payload;
        return error;
    }

    // Shared transport guard: a review context or virtual review ID can never
    // reach a stock mutation endpoint. Preserve the established policy exactly.
    function assertStockMutationAllowed(model, method, args, runtime) {
        if (['stock.picking','stock.move','stock.move.line'].includes(model) && ['write','create','unlink','button_validate','action_cancel'].includes(method) && (runtime?.detail?.review || (args[0] || []).some?.(isReviewId)))
            throw new Error('REVIEW_STOCK_WRITE_BLOCKED');
    }

    async function rpc(model, method, args = [], kwargs = {}, readOptions) {
        // Defense in depth: virtual review IDs can never reach a stock mutation API.
        assertStockMutationAllowed(model, method, args, state);
        // Only reads have a deadline. Writes/validation keep the original request
        // and unknown-result handling; a timer can never cancel a stock write.
        const readOnly = ["fields_get", "search_read", "read", "search_count", "formatted_read_group"].includes(method);
        const controller = readOnly && typeof window !== "undefined" && typeof window.AbortController === "function" ? new window.AbortController() : null;
        const cancelRead = () => controller?.abort();
        if (readOnly) {
            if (readOptions) throwIfReadCancelled(readOptions);
            readOptions?.signal?.addEventListener('abort', cancelRead, {once:true});
        }
        let readTimer;
        if (controller) readTimer = setTimeout(() => controller.abort(), 30000);
        try {
            const response = await fetch(`/web/dataset/call_kw/${encodeURIComponent(model)}/${encodeURIComponent(method)}`, {
                method: "POST", credentials: "include", headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { model, method, args, kwargs }, id: Date.now() }),
                ...(controller ? { signal: controller.signal } : {}),
            });
            if (!response.ok) throw Object.assign(new Error(`HTTP ${response.status}`), {httpStatus:response.status, retryable:response.status >= 500 || [408,429].includes(response.status)});
            let json;
            try { json = await response.json(); }
            catch (error) { throw Object.assign(new Error('RPC response could not be verified'), {code:'RPC_RESPONSE_INVALID', retryable:true, cause:error}); }
            if (!json || (!json.error && !Object.hasOwn(json, 'result'))) throw Object.assign(new Error('RPC result is missing'), {code:'RPC_RESPONSE_INVALID', retryable:true});
            if (json.error) throw apiError(json.error);
            if (readOnly && readOptions) throwIfReadCancelled(readOptions);
            return json.result;
        } catch (error) {
            if (readOnly && (readOptions?.cancelled || readOptions?.signal?.aborted)) throw Object.assign(new Error('Dashboard read cancelled'), {code:'RPC_READ_CANCELLED', cause:error});
            if (controller?.signal.aborted) throw Object.assign(new Error(pbUiText("读取数据超时，请稍后重试；没有自动重试写入。", "La lectura agotó el tiempo. Reintente; no se repitió ninguna escritura.")), { code: "RPC_READ_TIMEOUT", retryable: true, cause: error });
            throw error;
        } finally {
            if (readTimer != null) clearTimeout(readTimer);
            if (readOnly) readOptions?.signal?.removeEventListener('abort', cancelRead);
        }
    }

    function nextDeviceEventSequence() {
        const next = Math.max(0, Number(localStorage.getItem(LS.eventSequence) || 0)) + 1;
        localStorage.setItem(LS.eventSequence, String(next));
        return next;
    }

    function sharedStateFingerprint(tech) {
        return JSON.stringify({
            validation: tech?.validation || null,
            quantityRevision: Core.quantityRevision(tech),
            counts: tech?.counts || {},
            extraCounts: tech?.extraCounts || {},
            unknownScans: tech?.unknownScans || [],
            exception: tech?.exception || null,
            picker: tech?.picker || "",
            startedAt: tech?.startedAt || null,
            readyAt: tech?.readyAt || null,
            status: tech?.status || "",
            nativeFilled: Boolean(tech?.audit?.some((item) => item.event === "native_quantities_filled")),
            eventCount: Number(tech?.eventSync?.eventCount || 0),
            lastEventId: Number(tech?.eventSync?.lastEventId || 0),
            rejectedEvents: tech?.eventSync?.rejectedEvents || [],
        });
    }

    function eventValuesForOperation(op, detail, session) {
        if(isSale(detail) && !["sales_review","sales_cancel_ack"].includes(op.scope))op={...op,salesBaseline:op.salesBaseline || Core.quantityBaseline(baselineMoves(detail.tech))};
        const move = detail?.moves?.find((item) => Number(item.id) === Number(op.moveId));
        const moveProductId = Array.isArray(move?.product_id) ? move.product_id[0] : move?.product_id;
        const productId = Number(op.productId || moveProductId || 0) || false;
        const amount = Number(op.amount || 1);
        const quantity = op.type === "inc" ? amount : op.type === "dec" ? -amount : 0;
        const at = new Date().toISOString();
        const picker = String(session?.picker || detail?.tech?.picker || currentPicker() || "").trim();
        return {
            x_name: String(op.id),
            x_pb_picking_id: detail?.request ? false : Number(detail.picking.id),
            x_pb_request_id: detail?.request ? Number(detail.request.id) : false,
            x_pb_product_id: productId,
            x_pb_move_id: detail?.request ? false : (Number(op.moveId || 0) || false),
            x_pb_barcode: Core.normalizeCode(op.code) || false,
            x_pb_operation: `${op.scope || "order"}:${op.type || "event"}`,
            x_pb_quantity: Number.isFinite(quantity) ? quantity : 0,
            x_pb_target_quantity: op.type === "set" ? Number(op.value || 0) : 0,
            x_pb_is_extra: op.scope === "extra",
            x_pb_source: String(op.source || op.scope || "manual"),
            x_pb_picker: picker || false,
            x_pb_device_id: deviceId,
            x_pb_client_time: Core.odooDateTime(at),
            x_pb_parent_operation_id: String(op.parentOperationId || op.recordId || "") || false,
            x_pb_status: "done",
            x_pb_error: false,
            x_pb_payload: JSON.stringify({ op, picker, deviceId, deviceType: currentDeviceType(), at, version: VERSION }),
            x_pb_device_sequence: nextDeviceEventSequence(),
        };
    }

    async function loadSharedEvents(pickingId, requestId = null) {
        if (isReviewId(pickingId)) return readReviewEvents(pickingId);
        const domain = requestId ? [["x_pb_request_id", "=", Number(requestId)]] : [["x_pb_picking_id", "=", Number(pickingId)]];
        domain.push(["x_pb_operation", "not in", ["order_note:set", SALES_QUEUE_OPERATION]]);
        const records = await searchRead(SHARED_EVENT_MODEL, domain, [
            "id", "x_name", "x_pb_picking_id", "x_pb_request_id", "x_pb_product_id", "x_pb_move_id", "x_pb_barcode", "x_pb_operation",
            "x_pb_quantity", "x_pb_target_quantity", "x_pb_is_extra", "x_pb_source", "x_pb_picker", "x_pb_device_id",
            "x_pb_client_time", "x_pb_parent_operation_id", "x_pb_status", "x_pb_error", "x_pb_payload", "x_pb_device_sequence", "create_date",
        ], { order: "id asc", limit: 10000 });
        if (records.length >= 10000) throw Object.assign(new Error("本单操作记录过多，请联系管理员检查；未继续修改或验收"), { code: "EVENT_LOG_LIMIT" });
        return records.filter(record => !["order_note", "sales_queue"].includes(Core.normalizeSharedEvent(record).op.scope));
    }

    function verifyExistingOperation(record, op) {
        const stored = Core.safeParse(record.x_pb_payload)?.op;
        const canonical = value => {
            if (Array.isArray(value)) return value.map(canonical);
            if (value && typeof value === "object") return Object.fromEntries(Object.keys(value).sort().map(k => [k, canonical(value[k])]));
            return value;
        };
        const transport = new Set(["queuedAt","queuedOrigin","queuedOrder"]);
        const matches = stored && Core.quantityIntent(stored)===Core.quantityIntent(op) && Object.keys(op).filter(key => !transport.has(key)).every(key =>
            JSON.stringify(canonical(stored[key])) === JSON.stringify(canonical(op[key])));
        if (!matches) throw Object.assign(new Error(pbUiText("操作编号相同，但原记录内容无法核对，请保留待同步记录并检查。","El identificador ya existe con datos distintos o ilegibles. Revise el registro pendiente.")), {code:"OPERATION_ID_CONFLICT"});
        return { ...record, duplicate:true };
    }

    async function createSharedEvent(op, detail, session, knownEvents = null) {
        await assertTaskListed(detail?.row);
        if (detail?.review) return createReviewEvent(op, detail, session, knownEvents);
        const domain = detail?.request
            ? [["x_pb_request_id", "=", Number(detail.request.id)], ["x_name", "=", String(op.id)]]
            : [["x_pb_picking_id", "=", Number(detail.picking.id)], ["x_name", "=", String(op.id)]];
        // A mutation has just read this order's authoritative event log. Reuse
        // it for idempotency instead of sending the same lookup again.
        const existing = Array.isArray(knownEvents)
            ? knownEvents.filter(event => String(event.x_name || event.name || "") === String(op.id))
            : await searchRead(SHARED_EVENT_MODEL, domain, ["id", "x_name", "x_pb_status", "x_pb_error", "x_pb_payload"], { limit: 1 });
        if (existing.length) return verifyExistingOperation(existing[0],op);
        const values = eventValuesForOperation(op, detail, session);
        try {
            const id = await rpc(SHARED_EVENT_MODEL, "create", [values]);
            return { id, ...values };
        } catch (error) {
            const retry = await searchRead(SHARED_EVENT_MODEL, domain, ["id", "x_name", "x_pb_status", "x_pb_error", "x_pb_payload"], { limit: 1 });
            if (retry.length) return verifyExistingOperation(retry[0],op);
            throw error;
        }
    }

    async function withDeviceMutationLock(pickingId, task) {
        const lockApi = globalThis.navigator?.locks;
        if (!lockApi?.request || pickingId == null) return task();
        return lockApi.request(`pbful:${location.hostname}:picking:${Number(pickingId)}`, { mode: "exclusive" }, task);
    }

    async function fieldsOf(model, readOptions) {
        throwIfReadCancelled(readOptions);
        if (!state.modelFields.has(model)) {
            const reads=state.modelFieldReads ||= new Map();
            let pending=reads.get(model);
            if(!pending||pending.owner!==readOptions){
                pending={owner:readOptions,promise:rpc(model,"fields_get",[],{attributes:["string","type","selection","readonly","relation"]},readOptions)};
                reads.set(model,pending);
            }
            try{const defs=await pending.promise;throwIfReadCancelled(readOptions);state.modelFields.set(model,defs);}
            finally{if(reads.get(model)===pending)reads.delete(model);}
        }
        return state.modelFields.get(model);
    }
    async function availableFields(model, wanted, readOptions) {
        const defs = await fieldsOf(model, readOptions);
        return wanted.filter((name) => defs[name]);
    }
    async function searchRead(model, domain, wanted, kwargs = {}, readOptions) {
        const fields = await availableFields(model, wanted, readOptions);
        return rpc(model, "search_read", [domain], { fields, ...kwargs }, readOptions);
    }
    async function readOne(model, id, wanted, readOptions) {
        const fields = await availableFields(model, wanted, readOptions);
        const rows = await rpc(model, "read", [[Number(id)]], { fields }, readOptions);
        return rows[0] || null;
    }

    const PREPICK_FIELDS = [
        "id", "x_name", "x_pb_order_uuid", "x_pb_pos_order_id", "x_pb_picking_id", "x_pb_config_id", "x_pb_session_id",
        "x_pb_state", "x_pb_version", "x_pb_lines", "x_pb_previous_lines", "x_pb_tech", "x_pb_change_pending", "x_pb_change_summary",
        "x_pb_customer", "x_pb_amount", "x_pb_requested_by", "x_pb_requested_at", "x_pb_synced_at", "x_pb_cancelled_at",
        "x_pb_cancel_ack", "x_pb_payload", "create_date", "write_date",
    ];

    function m2oId(value) { return Array.isArray(value) ? Number(value[0] || 0) : Number(value?.id || value || 0); }

    // Task identity is independent of the current dashboard filter. Keep the
    // existing keys, negative IDs and event protocol; no stored data migration.
    const REVIEW_OFFSET = 1000000000;
    const isReviewId = id => Number.isSafeInteger(Number(id)) && Number(id) < -REVIEW_OFFSET;
    const reviewNativeId = id => -Number(id) - REVIEW_OFFSET;
    const reviewId = id => -REVIEW_OFFSET - Number(id);
    const reviewOperation = id => 'postpaid_review:v2:picking:' + reviewNativeId(id);

    function deliveryTaskKey(kind, pickingId, orderId) {
        return kind === 'sale' ? `s:${pickingId}` : `o:${orderId}:p:${pickingId || 0}`;
    }
    function prepickTaskKey(requestId) { return `r:${requestId}`; }
    function reviewTaskKey(nativePickingId) { return `review:${nativePickingId}`; }
    function taskType(value) {
        const row = value?.row || value;
        if (value?.review || row?.review) return 'review';
        return row?.kind === 'request' ? 'prepick' : 'delivery';
    }
    function taskSource(value) { return (value?.row || value)?.kind === 'sale' ? 'sale' : 'pos'; }
    function taskIdentity(value) {
        const row = value?.row || value || {};
        const picking = value?.picking || row.picking;
        const request = value?.request || row.request;
        const type = taskType(value);
        const source = taskSource(value);
        const taskId = m2oId(picking?.id);
        const sourcePickingId = type === 'delivery' ? taskId : 0;
        const nativePickingId = type === 'review' ? reviewNativeId(taskId)
            : type === 'prepick' ? m2oId(request?.x_pb_picking_id)
            : m2oId(value?.bridge?.paid ? value.bridge.target?.id : picking?.nativePickingId || taskId);
        const requestId = type === 'prepick' ? m2oId(request?.id) : 0;
        return {
            type, source, taskId, sourcePickingId, nativePickingId, requestId,
            key: type === 'review' ? reviewTaskKey(nativePickingId)
                : type === 'prepick' ? prepickTaskKey(request?.id)
                : deliveryTaskKey(row.kind, picking?.id, row.order?.id),
            eventPickingId: type === 'delivery' ? taskId : false,
            eventRequestId: type === 'prepick' ? requestId : false,
        };
    }

    function reviewError(code, zh, es) {
        return Object.assign(new Error(state.lang === 'es' ? es : zh), {code});
    }
    // Pure policy. Multiple actual deliveries are supported; refunds/returns
    // never silently turn the original delivered amount into a new demand.
    function assertReviewPolicy(data, nativeId) {
        const {order, lines, pickings, returns} = data;
        if (!order?.uuid || !posPaymentConfirmed(order)) throw reviewError('PAYMENT_UNCONFIRMED','付款状态尚未核实，请同步后重试。','El pago no está confirmado. Sincronice.');
        if (order.is_refund || lines.some(l => Number(l.qty) < 0 || Number(l.refunded_qty) > 0 || m2oId(l.refunded_orderline_id) || l.refund_orderline_ids?.length))
            throw reviewError('REFUND_REVIEW','此单涉及退款，请先核对退款和剩余商品，未继续补开。','Este pedido tiene reembolsos. Revise los productos restantes.');
        if (returns.length) throw reviewError('RETURN_REVIEW','此单已有退货记录，请先核对，未继续补开。','Hay devoluciones. Revise el pedido antes de continuar.');
        const picking = pickings.find(p => Number(p.id) === Number(nativeId));
        if (!picking || picking.state !== 'done' || picking.picking_type_code !== 'outgoing' ||
            (m2oId(picking.pos_order_id) !== Number(order.id) && !(order.picking_ids || []).map(m2oId).includes(Number(nativeId))))
            throw reviewError('REVIEW_DELIVERY_CHANGED','交货单关联或状态已变化，补开已暂停。','Cambió el vínculo o estado de la entrega.');
        if (!m2oId(order.company_id) || m2oId(picking.company_id) !== m2oId(order.company_id))
            throw reviewError('COMPANY_REVIEW','订单与交货单公司不一致，请核对原单。','No coincide la compañía del pedido y la entrega.');
        return picking;
    }
    async function readReviewPolicyData(row, nativeId,readOptions) {
        const order = await readOne('pos.order', Number(row.order.id), ['id','uuid','name','pos_reference','state','company_id','picking_ids','is_refund'],readOptions);
        if (!order || !posPaymentConfirmed(order)) throw reviewError('PAYMENT_UNCONFIRMED','服务器尚未确认付款，未继续补开。','El servidor no confirma el pago.');
        const [lines, pickings] = await Promise.all([
            readAll('pos.order.line', [['order_id','=',order.id]], ['id','product_id','qty','refunded_qty','refunded_orderline_id','refund_orderline_ids'], 1000,readOptions),
            readAll('stock.picking', ['|',['pos_order_id','=',order.id],['id','in',(order.picking_ids || []).map(m2oId)]], ['id','name','state','picking_type_code','pos_order_id','company_id'], 1000,readOptions),
        ]);
        const returns = pickings.length ? await searchRead('stock.picking', [['return_id','in',pickings.map(p=>p.id)],['state','!=','cancel']], ['id'], {limit:1},readOptions) : [];
        const data = {order, lines, pickings, returns};
        assertReviewPolicy(data, nativeId);
        return data;
    }
    function reviewSearchText(options) { return String(options?.reviewSearch ?? state.search ?? '').trim(); }
    async function reviewOrderQuery(options) {
        const q = reviewSearchText(options), domain = [['state','in',['paid','done','invoiced']]];
        const fields = ['id','uuid','name','pos_reference','date_order','shipping_date','partner_id','amount_total','state','config_id','picking_ids','company_id'];
        const defs = await fieldsOf('pos.order', options);
        if (defs.tracking_number) fields.push('tracking_number');
        if (q) {
            const parts = [['name','ilike',q],['pos_reference','ilike',q]];
            if(defs.partner_id?.relation==='res.partner')parts.push(['partner_id.name','ilike',q]);
            if(defs.picking_ids?.relation==='stock.picking')parts.push(['picking_ids.name','ilike',q]);
            if (/^\d+$/.test(q) && Number.isSafeInteger(Number(q))) parts.push(['id','=',Number(q)]);
            if (defs.tracking_number) parts.push(['tracking_number','ilike',q]);
            domain.push(...Array(parts.length-1).fill('|'), ...parts);
        }
        return {domain,fields};
    }
    // Original v1 fingerprint/replay preserved; stored records are never rewritten.
function legacyReviewFingerprint(value) {
        return JSON.stringify([Number(value.order.id),value.order.uuid,Number(value.companyId),Number(value.picking.id),value.picking.state,
            value.lines.map(l=>[l.productId,l.quantity,l.uomId]).sort((a,b)=>a[0]-b[0])]);
    }
function legacyReviewReplay(events, snapshot) {
        const baseline=legacyReviewFingerprint(snapshot),counts={},seen=new Set(),accepted=new Map(),rejected=[];
        let registered=false,complete=false;
        for (const row of [...events].sort((a,b)=>Number(a.id)-Number(b.id))) {
            let e;try {e=typeof row.x_pb_payload==='string'?JSON.parse(row.x_pb_payload):row.x_pb_payload;}catch(_){throw new Error('EVENT_CORRUPT');}
            if (!e || e.schema!==1 || e.kind!=='postpaid_review' || e.baseline!==baseline || e.orderId!==snapshot.order.id || e.uuid!==snapshot.order.uuid || e.companyId!==snapshot.companyId || !e.action?.id) throw new Error('TASK_CHANGED');
            const a=e.action;if(seen.has(a.id))continue;seen.add(a.id);
            if(a.type==='task'){registered=true;continue;}
            if(!registered)throw new Error('EVENT_CORRUPT');
            const line=snapshot.lines.find(l=>l.productId===Number(a.productId)),current=Number(counts[a.productId]||0),amount=Number(a.amount);
            if(complete){rejected.push({id:a.id,reason:'COMPLETED'});continue;}
            if(a.type==='inc'&&line&&Number.isFinite(amount)&&amount>0&&current+amount<=line.quantity+1e-6){counts[a.productId]=Math.min(line.quantity,current+amount);accepted.set(a.id,a);}
            else if(a.type==='undo'&&accepted.has(a.targetId)&&!accepted.get(a.targetId).undone){const prior=accepted.get(a.targetId);counts[prior.productId]=Math.max(0,Number(counts[prior.productId]||0)-prior.amount);prior.undone=true;}
            else if(a.type==='complete'&&snapshot.lines.every(l=>Math.abs(Number(counts[l.productId]||0)-l.quantity)<1e-6)){complete=true;}
            else rejected.push({id:a.id,reason:a.type==='inc'?'OVER_OR_WRONG_PRODUCT':'NOT_READY'});
        }
        return {counts,complete,registered,accepted:[...accepted.values()],rejected};
    }

    function legacyReviewStorePrefix() { return 'pbful_postpaid_outbox_v1:'; }
    function legacyReviewAckPrefix() { return 'pbful_postpaid_outbox_ack_v1:'; }
    function legacyReviewOperation(order) { return 'postpaid_review:v1:' + m2oId(order.company_id) + ':' + order.uuid; }
    function legacyReviewPayload(record) {
        const p = Core.safeParse(record.x_pb_payload);
        if (!p || p.schema !== 1 || p.kind !== 'postpaid_review' || !p.action?.id || !Number.isSafeInteger(p.orderId) ||
            !Number.isSafeInteger(p.companyId) || !Number.isSafeInteger(p.pickingId) || p.pickingId <= 0 || !p.uuid || !p.baseline)
            throw reviewError('LEGACY_REVIEW_INVALID','旧补开记录无法核实，数据已保留，请先检查原记录。','No se puede verificar la revisión anterior. Los datos se conservaron.');
        return p;
    }
    function inspectLegacyReviewPending(storage) {
        const operations = [], errors = [];
        for (let i=0; i<storage.length; i++) {
            const key = storage.key(i);
            if (!key?.startsWith(legacyReviewStorePrefix())) continue;
            try {
                const raw = storage.getItem(key), entry = JSON.parse(raw), baseline = JSON.parse(entry.baseline);
                const action = entry.action, nativeId = Number(baseline[3]);
                if (!action?.id || key !== legacyReviewStorePrefix() + action.id || !Number.isSafeInteger(nativeId) || nativeId <= 0 ||
                    baseline.length !== 6 || !Number.isSafeInteger(baseline[0]) || !baseline[1] || !Number.isSafeInteger(baseline[2]) ||
                    entry.key !== 'postpaid_review:v1:' + baseline[2] + ':' + baseline[1] || !Array.isArray(baseline[5]) || !Number.isFinite(entry.at)) throw Error('Invalid v1 pending entry');
                const ack = Core.safeParse(storage.getItem(legacyReviewAckPrefix() + action.id));
                if (ack?.raw === raw && Number.isSafeInteger(ack.serverId) && ack.serverId > 0) continue;
                operations.push({id:action.id,pickingId:-1000000000-nativeId,scope:'legacy_postpaid',type:'legacy',legacyPostpaid:true,
                    legacyKey:key,legacyRaw:raw,legacyEntry:entry,queuedAt:entry.at,queuedOrder:0,queuedOrigin:'legacy-v1'});
            } catch (_) { errors.push(key); }
        }
        operations.sort((a,b)=>a.queuedAt-b.queuedAt || a.id.localeCompare(b.id));
        return {operations,errors};
    }
    function legacySnapshotForMoves(order, nativeId, moves, events) {
        if (!events.length) return null;
        const first = legacyReviewPayload(events[0]);
        const baseline = JSON.parse(first.baseline), lines = baseline[5]?.map(l=>({productId:l[0],quantity:l[1],uomId:l[2]}));
        if (!lines?.length || baseline[0] !== Number(order.id) || baseline[1] !== order.uuid || baseline[2] !== m2oId(order.company_id) ||
            baseline[3] !== Number(nativeId) || baseline[4] !== 'done' || first.orderId !== Number(order.id) || first.uuid !== order.uuid ||
            first.companyId !== m2oId(order.company_id) || first.pickingId !== Number(nativeId)) throw Error('LEGACY_REVIEW_IDENTITY_CHANGED');
        const actual = new Map();
        for (const move of moves.filter(m=>m.state==='done' && Number(m.quantity)>0)) {
            const productId=m2oId(move.product_id), uomId=m2oId(move.product_uom), key=productId+':'+uomId;
            actual.set(key,(actual.get(key)||0)+Number(move.quantity));
        }
        if (actual.size !== lines.length || lines.some(l=>!Number.isSafeInteger(l.productId)||l.quantity<=0||actual.get(l.productId+':'+l.uomId)!==l.quantity)) throw Error('LEGACY_REVIEW_BASELINE_CHANGED');
        const snapshot={order,companyId:m2oId(order.company_id),picking:{id:Number(nativeId),state:'done'},lines};
        if (legacyReviewFingerprint(snapshot)!==first.baseline) throw Error('LEGACY_REVIEW_BASELINE_CHANGED');
        for (const record of events) {const p=legacyReviewPayload(record);if(p.pickingId!==Number(nativeId))throw Error('LEGACY_REVIEW_IDENTITY_CHANGED');}
        return snapshot;
    }
    async function legacyReviewRevision(events) {
        if (!events.length) return '';
        // Bind the immutable v1 base without repeating its entire event log in
        // every new event. SHA-256 is computed asynchronously by the browser.
        const data=JSON.stringify([...events].sort((a,b)=>Number(a.id)-Number(b.id)).map(e=>[e.id,e.x_name,e.x_pb_payload]));
        const hash=await PAGE_WINDOW.crypto.subtle.digest('SHA-256',new PAGE_WINDOW.TextEncoder().encode(data));
        return 'sha256:'+Array.from(new PAGE_WINDOW.Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');
    }
    function seedLegacyReview(order, nativeId, nativeMoves, events, moves, revision) {
        const snapshot=legacySnapshotForMoves(order,nativeId,nativeMoves,events);
        if (!snapshot) return null;
        const replay=legacyReviewReplay(events,snapshot), tech=Core.createTech(moves), remaining={...replay.counts};
        for (const move of [...moves].sort((a,b)=>a.id-b.id)) {
            const productId=m2oId(move.product_id), amount=Math.min(Number(move.product_uom_qty),Number(remaining[productId]||0));
            tech.counts[String(move.id)]=amount;remaining[productId]=Math.max(0,Number(remaining[productId]||0)-amount);
        }
        if (Object.values(remaining).some(n=>n!==0)) throw Error('LEGACY_REVIEW_BASELINE_CHANGED');
        tech.picker=[...events].reverse().map(e=>legacyReviewPayload(e).action.picker).find(Boolean)||'';
        if (replay.complete) tech.reviewCompleted='legacy-v1-complete';
        if (!revision) throw Error('LEGACY_REVIEW_REVISION_MISSING');
        return {tech,revision,snapshot,replay};
    }
    async function readLegacyReviewIndex(readOptions) {
        const groups=await rpc(SHARED_EVENT_MODEL,'formatted_read_group',[],{
            domain:[['x_pb_operation','=like','postpaid_review:v1:%']],groupby:['x_pb_operation'],aggregates:['id:min'],limit:600,order:'id:min DESC'},readOptions);
        const ids=groups.map(g=>Number(g['id:min'] ?? g.id)).filter(id=>Number.isSafeInteger(id)&&id>0);
        if(ids.length!==groups.length)throw Error('LEGACY_REVIEW_INDEX_UNVERIFIED');
        const records=ids.length?await searchRead(SHARED_EVENT_MODEL,[['id','in',ids]],['id','x_name','x_pb_operation','x_pb_payload'],{limit:ids.length},readOptions):[];
        const index=[];
        for(const record of records){const p=legacyReviewPayload(record);if(record.x_pb_operation!=='postpaid_review:v1:'+p.companyId+':'+p.uuid)throw Error('LEGACY_REVIEW_IDENTITY_CHANGED');index.push({id:p.pickingId,operation:record.x_pb_operation,orderId:p.orderId});}
        const pending=inspectLegacyReviewPending(localStorage);
        for(const op of pending.operations){const b=JSON.parse(op.legacyEntry.baseline);index.push({id:reviewNativeId(op.pickingId),operation:op.legacyEntry.key,orderId:b[0]});}
        return [...new Map(index.map(r=>[r.id+':'+r.operation,r])).values()];
    }
    async function readLegacyReviewEvents(order, readOptions) {
        return readAll(SHARED_EVENT_MODEL,[['x_pb_operation','=',legacyReviewOperation(order)]],
            ['id','x_name','x_pb_operation','x_pb_payload','x_pb_status','x_pb_picker','x_pb_device_id','x_pb_client_time'],1000,readOptions);
    }
    async function applyLegacyReviewPending(op) {
        if (!op.legacyPostpaid || !state.detail?.review || Number(state.detail.picking.id)!==Number(op.pickingId)) throw Error('STALE_CONTEXT');
        const fresh=await readReviewTaskDetail(state.detail.row), nativeId=fresh.nativePicking.id;
        if (fresh.sharedEvents.length) throw reviewError('LEGACY_REVIEW_MIXED_PENDING','旧补开尚有待上传数据，且已有新记录；数据已保留，请先核对，未自动合并。','Hay pendientes antiguos y eventos nuevos. Se conservaron; revise antes de combinar.');
        const raw=localStorage.getItem(op.legacyKey);
        if (raw!==op.legacyRaw) throw Error('LEGACY_REVIEW_PENDING_CHANGED');
        const entry=op.legacyEntry, snapshot=fresh.legacyReview?.snapshot;
        if (!snapshot || legacyReviewFingerprint(snapshot)!==entry.baseline || entry.key!==legacyReviewOperation(fresh.row.order)) throw Error('LEGACY_REVIEW_BASELINE_CHANGED');
        let records=fresh.legacyEvents;
        const verify=()=>{const replay=legacyReviewReplay(records,snapshot);const event=records.find(e=>e.x_name===entry.action.id);if(!event || replay.rejected.some(r=>r.id===entry.action.id))throw Error('LEGACY_REVIEW_EVENT_REJECTED');const p=legacyReviewPayload(event);if(p.baseline!==entry.baseline||JSON.stringify(p.action)!==JSON.stringify(entry.action))throw Error('LEGACY_REVIEW_OPERATION_COLLISION');return event;};
        if (!records.some(e=>e.x_name===entry.action.id)) {
            const payload={schema:1,kind:'postpaid_review',orderId:snapshot.order.id,uuid:snapshot.order.uuid,companyId:snapshot.companyId,baseline:entry.baseline,pickingId:nativeId,action:entry.action};
            const prospective={id:Math.max(0,...records.map(r=>Number(r.id)))+1,x_name:entry.action.id,x_pb_payload:JSON.stringify(payload)};
            if(!['task','inc','undo','complete'].includes(entry.action.type)||legacyReviewReplay([...records,prospective],snapshot).rejected.some(r=>r.id===entry.action.id))throw Error('LEGACY_REVIEW_EVENT_REJECTED');
            const values={x_name:entry.action.id,x_pb_operation:entry.key,x_pb_status:'done',x_pb_source:'postpaid_review',x_pb_payload:JSON.stringify(payload),
                x_pb_picker:entry.action.picker||false,x_pb_device_id:deviceId,x_pb_client_time:Core.odooDateTime(new Date().toISOString()),x_pb_picking_id:false,x_pb_request_id:false};
            let failure;try {await rpc(SHARED_EVENT_MODEL,'create',[values]);}catch(error){failure=error;}
            records=await readLegacyReviewEvents(fresh.row.order);
            if (!records.some(e=>e.x_name===entry.action.id) && failure) throw failure;
        }
        const saved=verify();
        if (localStorage.getItem(op.legacyKey)!==raw) throw Error('LEGACY_REVIEW_PENDING_CHANGED');
        const ack=JSON.stringify({raw,serverId:Number(saved.id),at:new Date().toISOString()});
        localStorage.setItem(legacyReviewAckPrefix()+op.id,ack);
        if(localStorage.getItem(legacyReviewAckPrefix()+op.id)!==ack)throw Error('LOCAL_ACK_FAILED');
        // The exact old pending bytes stay in their original key for recovery.
        return {contextActive:Number(state.detail?.picking.id)===Number(op.pickingId),legacy:true};
    }
    async function resumeLegacyReviewPending(detail) {
        if (!detail?.review) return detail;
        const pending=inspectLegacyReviewPending(localStorage), relevant=pending.operations.filter(o=>Number(o.pickingId)===Number(detail.picking.id));
        if (pending.errors.length) throw Error('LEGACY_REVIEW_PENDING_INVALID');
        if (!relevant.length) return detail;
        return withDeviceMutationLock(detail.picking.id,async()=>{
            const prior=state.detail;
            try {
                state.detail=detail;
                for(const op of relevant)await applyLegacyReviewPending(op);
                return await readReviewTaskDetail(detail.row);
            } finally {if(state.detail===detail)state.detail=prior;}
        });
    }
    function orderNoteKey(row) {
        if(isSale(row))return `pbful-note:sale:${Number(row.order.id)}`;
        const uuid = String(row?.request?.x_pb_order_uuid || row?.order?.uuid || "").trim();
        if (uuid) return `pbful-note:pos:${uuid}`;
        if (row?.request?.id) return `pbful-note:request:${Number(row.request.id)}`;
        const id = Number(row?.order?.id || 0);
        return id > 0 ? `pbful-note:order:${id}` : "";
    }

    function orderNote(row) { return state.orderNotes.get(orderNoteKey(row))?.text || ""; }
    function orderTitle(row) { return orderNote(row) || row?.order?.pos_reference || row?.order?.name || ""; }
    function normalizeOrderNote(value) { return String(value || "").replace(/\s+/g, " ").trim(); }

    // Notes use their own immutable records in the existing event model. The POS
    // UUID survives payment/linking, so no quantity aggregate or migration copies
    // are needed. Clearing a note is a new empty value, not a record deletion.
    async function refreshOrderNotes(rows, readOptions) {
        const keys = [...new Set(rows.map(orderNoteKey).filter(Boolean))];
        if (!keys.length) return;
        const remaining = new Set(keys), found = new Map();
        try {
            while (remaining.size) {
                const limit = Math.max(100, remaining.size);
                const records = await searchRead(SHARED_EVENT_MODEL, [
                    ["x_pb_operation", "=", "order_note:set"],
                    ["x_pb_parent_operation_id", "in", [...remaining]],
                    ["x_pb_status", "=", "done"],
                ], ["id", "x_name", "x_pb_parent_operation_id", "x_pb_payload"], { order: "id desc", limit }, readOptions);
                let resolved = 0;
                for (const record of records) {
                    const key = String(record.x_pb_parent_operation_id || "");
                    if (!remaining.has(key)) continue;
                    const op = Core.safeParse(record.x_pb_payload)?.op;
                    if (op?.scope !== "order_note" || op.type !== "set" || op.parentOperationId !== key || typeof op.note !== "string") throw new Error(t("orderNoteInvalid"));
                    found.set(key, { id: Number(record.id), name: record.x_name, text: normalizeOrderNote(op.note) });
                    remaining.delete(key); resolved++;
                }
                if (records.length < limit) break;
                if (!resolved) throw new Error(t("orderNoteInvalid"));
                // Exclude already resolved orders: one order's long edit history
                // must not hide the latest note belonging to another order.
            }
            for (const key of keys) {
                const next = found.get(key) || { id: 0, name: "", text: "" };
                const previous = state.orderNotes.get(key);
                if (!previous || next.id >= previous.id) state.orderNotes.set(key, next);
                state.orderNoteErrors.delete(key);
            }
        } catch (error) {
            throwIfReadCancelled(readOptions);
            for (const key of keys) state.orderNoteErrors.set(key, error.message || String(error));
            throw error;
        } finally { if (!readOptions?.cancelled && !(readOptions && state.detailRequest === readOptions && state.view === "dashboard")) updateOrderNoteDisplay(); }
    }

    function updateOrderNoteDisplay() {
        if (!root || !state.open) return;
        if (state.view === "dashboard") { updateDashboardSearchResults(); return; }
        const row = state.detail?.row;
        if (!row) return;
        const title = root.querySelector("[data-order-note-title]");
        if (title) { title.textContent = orderTitle(row); title.title = orderTitle(row); }
        const reference = root.querySelector("[data-order-note-reference]");
        if (reference) {
            reference.textContent = `${row.order.pos_reference || row.order.name} · `;
            reference.hidden = !orderNote(row);
        }
        const button = root.querySelector('[data-act="order-note"]');
        if (button) {
            const failed = state.orderNoteErrors.has(orderNoteKey(row));
            button.textContent = t("note");
            button.title = t(failed ? "orderNoteSyncFailed" : "orderNoteTitle");
            button.setAttribute('aria-label', button.title);
            button.classList.toggle("pbful-note-error", failed);
        }
    }

    async function autoPullOrderNotes() {
        if (!state.open || state.view !== "detail" || !state.detail || document.visibilityState !== "visible" || !navigator.onLine || state.orderNotePulling || state.mutationSyncing || state.scanProcessing || state.scanQueue.length) return;
        state.orderNotePulling = true;
        try { await refreshOrderNotes([state.detail.row]); }
        catch (_error) { /* Keep the last known label; the note button shows the sync error. */ }
        finally { state.orderNotePulling = false; }
    }

    function noteConflict(latest) {
        return Object.assign(new Error(`${t("orderNoteConflict")}\n${latest.text || t("orderNoteEmpty")}`), { code: "ORDER_NOTE_CONFLICT", latest });
    }

    function saveOrderNote(row, value, expectedId, operationId = Core.makeId("note")) {
        const key = orderNoteKey(row), text = normalizeOrderNote(value);
        if (!key || (!row?.request && !row?.picking)) return Promise.reject(new Error(t("orderNoteUnavailable")));
        if (text.length > 200) return Promise.reject(new Error(t("orderNoteTooLong")));
        if (state.orderNoteSaves.has(key)) return state.orderNoteSaves.get(key);
        const task = (async () => {
            if (!navigator.onLine) throw new Error(t("orderNoteOffline"));
            await refreshOrderNotes([row]);
            let latest = state.orderNotes.get(key);
            if (latest.name === operationId || latest.text === text) return latest;
            if (latest.id !== Number(expectedId || 0)) throw noteConflict(latest);
            const op = { id: operationId, scope: "order_note", type: "set", note: text, parentOperationId: key, source: "order_note" };
            const saved = await createSharedEvent(op, row, null);
            // Do not label a local draft as saved. Read the authoritative note back,
            // including edits that arrived from another device during this save.
            await refreshOrderNotes([row]);
            latest = state.orderNotes.get(key);
            if (latest.name !== saved.x_name) {
                if (latest.id > Number(saved.id)) throw noteConflict(latest);
                throw new Error(t("orderNoteVerifyFailed"));
            }
            return latest;
        })();
        state.orderNoteSaves.set(key, task);
        return task.finally(() => { if (state.orderNoteSaves.get(key) === task) state.orderNoteSaves.delete(key); });
    }

    async function editOrderNote(row) {
        if (!row || state.activePrompt || state.orderNoteEditorOpening) return;
        const view = state.view, detailKey = orderNoteKey(state.detail?.row);
        state.orderNoteEditorOpening = true;
        try {
            await refreshOrderNotes([row]);
            if (!state.open || state.view !== view || (view === "detail" && orderNoteKey(state.detail?.row) !== detailKey)) return;
            const key = orderNoteKey(row), current = state.orderNotes.get(key) || { id: 0, text: "" };
            let draft = current.text, expectedId = current.id, operationId = Core.makeId("note");
            return await showPrompt(`${row.order.pos_reference || row.order.name}\n${t("orderNoteHelp")}`, "confirm", {
                title: t("orderNoteTitle"), keepOpenOnError: true, fitNoteViewport: true,
                textInput: { value: draft, placeholder: t("orderNotePlaceholder"), maxLength: 200, onInput(value) { draft = value; operationId = Core.makeId("note"); } },
                actions: [
                    { label: t("orderNoteCancel"), value: false },
                    { label: t("orderNoteSave"), primary: true, waitForAction: true, onClick: async () => {
                        try {
                            await saveOrderNote(row, draft, expectedId, operationId);
                            toast(t("orderNoteSaved"), "ok", 1800);
                        } catch (error) {
                            if (error.code === "ORDER_NOTE_CONFLICT") { expectedId = error.latest.id; operationId = Core.makeId("note"); }
                            throw error;
                        }
                    } },
                ],
            });
        } finally { state.orderNoteEditorOpening = false; }
    }
    // List membership only. No order/payment/stock write and no event deletion.
    function taskMembershipOperation(key) {return 'task_membership:v1:'+key;}
    function membershipPayload(event) {
        const value=Core.safeParse(event?.x_pb_payload);
        if(value?.schema!==1||!['withdraw','restore'].includes(value.action)||!value.key||event.x_pb_operation!==taskMembershipOperation(value.key))throw new Error('TASK_MEMBERSHIP_UNVERIFIED');
        return value;
    }
    async function latestTaskMembership(key,readOptions) {
        const rows=await searchRead(SHARED_EVENT_MODEL,[['x_pb_operation','=',taskMembershipOperation(key)]],['id','x_name','x_pb_operation','x_pb_payload'],{order:'id desc',limit:1},readOptions);
        return rows.length?{...membershipPayload(rows[0]),eventId:rows[0].id}:null;
    }
    async function assertTaskListed(row,readOptions) {
        if(!row?.review&&!isSale(row))return;
        if((await latestTaskMembership(row.key,readOptions))?.action==='withdraw')throw Object.assign(new Error(pbUiText('此任务已从配货待办移出；记录已保留，请从已移出任务中恢复。','La tarea fue retirada; restaure desde el historial.')),{code:'TASK_WITHDRAWN'});
    }
    async function loadTaskMembershipIndex(readOptions) {
        const groups=await rpc(SHARED_EVENT_MODEL,'formatted_read_group',[],{domain:[['x_pb_operation','=like','task_membership:v1:%']],groupby:['x_pb_operation'],aggregates:['id:max'],limit:5001},readOptions);
        if(groups.length>5000)throw new Error('TASK_MEMBERSHIP_LIMIT');
        const ids=groups.map(g=>Number(g['id:max']??g.id));
        if(ids.some(id=>!Number.isSafeInteger(id)||id<=0))throw new Error('TASK_MEMBERSHIP_UNVERIFIED');
        const records=ids.length?await readAll(SHARED_EVENT_MODEL,[['id','in',ids]],['id','x_name','x_pb_operation','x_pb_payload'],1000,readOptions):[];
        if(records.length!==ids.length)throw new Error('TASK_MEMBERSHIP_UNVERIFIED');
        return new Map(records.map(r=>{const p=membershipPayload(r);return[p.key,{...p,eventId:r.id}];}));
    }
    function hiddenSalePickingIds() {
        return [...(state.taskMembership||new Map())].filter(([key,p])=>/^s:\d+$/.test(key)&&p.action==='withdraw').map(([key])=>Number(key.slice(2)));
    }
    function taskMembershipFingerprint(detail) {
        return JSON.stringify([detail.picking.state,detail.request?.x_pb_state,detail.tech?.reviewCompleted||'',detail.tech?.validation||null,detail.tech?.counts||{},detail.tech?.extraCounts||{},detail.sharedEventCount,detail.tech?.rev]);
    }
    function assertNoTaskPending(row) {
        assertOfflineQueueHealthy();
        const id=Number(row.picking.id);
        if(offlineQueue().some(o=>Number(o.pickingId)===id)||[...(state.pendingQuantityOps||new Map()).values()].some(o=>Number(o.pickingId||o.op?.pickingId)===id)||Number(state.detail?.picking.id)===id&&(state.queuedMutations||state.mutationSyncing||state.bulkAction||state.validationAction))
            throw new Error(pbUiText('本机仍有待同步操作，请先同步；没有丢弃或移出这些记录。','Sincronice primero las operaciones pendientes; se conservaron.'));
    }
    async function appendTaskMembership(row,action,detail,expectedEventId) {
        const prior=await latestTaskMembership(row.key);
        if(prior?.action===action)return prior;
        if(Number(prior?.eventId||0)!==Number(expectedEventId||0))throw new Error(pbUiText('任务状态已被另一端修改，请刷新后重试。','Otra pantalla cambió la tarea; actualice.'));
        const id=Core.makeId('task-'+action),payload={schema:1,key:row.key,action,at:new Date().toISOString(),picker:currentPicker(),version:VERSION,
            order:row.order.pos_reference||row.order.name,picking:detail?.nativePicking?.name||row.picking.name,status:detail?Core.statusFor(detail.tech,detail.moves,detail.picking.state,row.order.state):row.status,progress:detail?Core.progress(detail.tech,detail.moves):row.progress};
        const values={x_name:id,x_pb_operation:taskMembershipOperation(row.key),x_pb_status:'done',x_pb_source:'task_membership',x_pb_payload:JSON.stringify(payload),x_pb_picker:currentPicker()||false,x_pb_device_id:deviceId,x_pb_client_time:Core.odooDateTime(payload.at),x_pb_picking_id:false,x_pb_request_id:false};
        const domain=[['x_name','=',id],['x_pb_operation','=',values.x_pb_operation]];
        try{await rpc(SHARED_EVENT_MODEL,'create',[values]);}
        catch(error){if(!(await searchRead(SHARED_EVENT_MODEL,domain,['id'],{limit:1})).length)throw error;}
        const verified=await latestTaskMembership(row.key);
        if(verified?.action!==action)throw new Error('TASK_MEMBERSHIP_RESULT_UNCONFIRMED');
        state.taskMembership ||= new Map();state.taskMembership.set(row.key,verified);invalidateDashboardIndex();return verified;
    }
    async function readWithdrawalState(row) {
        if (row.review) return readReviewTaskDetail(row, {membershipOnly:true});
        const snapshot = await readDeliveryTaskSnapshot(row);
        return {...snapshot, sharedEventCount:snapshot.sharedEvents.length};
    }

    function showVerifiedWithdrawal(row, membership) {
        state.taskMembership ||= new Map();
        state.taskMembership.set(row.key, membership);
        state.rows = state.rows.filter(item => item.key !== row.key);
        if (state.open && state.view === "dashboard") {
            updateDashboardSearchResults();
            setTimeout(() => {
                if (state.open && state.view === "dashboard" && !state.detailRequest) refresh(true);
            }, 0);
        }
    }

    async function withdrawTaskFromList(key) {
        const row=state.rows.find(r=>r.key===key);
        if(!row||!row.review&&!isSale(row))throw new Error('TASK_WITHDRAWAL_NOT_SUPPORTED');
        assertNoTaskPending(row);
        const prior=await latestTaskMembership(key);
        if(prior?.action==='withdraw'){invalidateDashboardIndex();showVerifiedWithdrawal(row,prior);return;}
        const detail=await readWithdrawalState(row);
        if(isReadOnlyDetail(detail)||detail.tech.validation)throw new Error(pbUiText('任务已完成或正在验收，不能移出待办。','La tarea está terminada o validándose.'));
        const baseline=taskMembershipFingerprint(detail),es=state.lang==='es';
        const p=Core.progress(detail.tech,detail.moves);
        await showPrompt(`${row.order.pos_reference||row.order.name}\n${detail.nativePicking?.name||detail.picking.name}\n${statusLabel(row.status)} · ${p.scanned}/${p.demand}\n`+(es?'¿Retirar solo esta tarea? Se conservan pedido, pago, entrega, inventario y escaneos. Puede restaurarla desde el historial.':'确认仅移出这次配货任务？原订单、付款、交货、库存和扫码记录全部保留，可在“已移出任务”恢复。'),'confirm',{
            title:es?'Retirar tarea':'移出配货待办',keepOpenOnError:true,actions:[{label:es?'Volver':'返回',value:false},{label:es?'Confirmar retiro':'确认移出',primary:true,waitForAction:true,onClick:()=>withDeviceMutationLock(row.picking.id,async()=>{
                assertNoTaskPending(row);
                const fresh=await readWithdrawalState(row);
                assertNoTaskPending(row);
                if(isReadOnlyDetail(fresh)||fresh.tech.validation||taskMembershipFingerprint(fresh)!==baseline)throw new Error(pbUiText('另一端的扫码或状态已变化，请返回重新核对后再移出。','Cambió el escaneo o estado; vuelva a revisar.'));
                const verified = await appendTaskMembership(row,'withdraw',fresh,prior?.eventId);
                showVerifiedWithdrawal(row,verified);
                return true;
            })}]
        });
    }
    async function showTaskMembershipHistory() {
        const index=await loadTaskMembershipIndex();state.taskMembership=index;
        const removed=[...index.values()].filter(p=>p.action==='withdraw').sort((a,b)=>b.eventId-a.eventId).slice(0,30),es=state.lang==='es';
        await showPrompt(removed.length?(es?'Últimas 30 tareas retiradas. Los escaneos se conservan.':'最近 30 项已移出任务，恢复后保留原扫码数量。'):(es?'No hay tareas retiradas.':'没有已移出任务。'),'info',{title:es?'Tareas retiradas':'已移出任务',actions:[{label:es?'Volver':'返回',value:false},...removed.map(p=>({label:`${p.order} · ${p.picking} · ${p.progress?.scanned??'—'}/${p.progress?.demand??'—'} · ${p.picker||'-'} · ${shortDate(p.at)} · ${es?'Restaurar':'恢复'}`,waitForAction:true,onClick:async()=>{
            const prior=await latestTaskMembership(p.key);
            if(prior?.action==='restore')return true;
            if(prior?.eventId!==p.eventId)throw new Error('TASK_MEMBERSHIP_CHANGED');
            await appendTaskMembership({key:p.key,order:{name:p.order},picking:{name:p.picking},status:p.status,progress:p.progress},'restore',null,p.eventId);
            await refresh(true);return true;
        }}))]});
    }
    function prepickLines(request) { return Core.normalizeDraftLines(Core.safeParse(request?.x_pb_lines) || []); }
    function prepickMoves(request) { return Core.draftMoves(prepickLines(request)); }
    function prepickTech(request, moves) { return Core.hydrateTech(request?.x_pb_tech, moves || prepickMoves(request)); }

    function prepickStateFingerprint(request) {
        return JSON.stringify([
            Number(request?.x_pb_version || 0), request?.x_pb_state || "",
            Boolean(request?.x_pb_change_pending), request?.x_pb_change_summary || "",
            Boolean(request?.x_pb_cancel_ack), m2oId(request?.x_pb_picking_id), request?._posPayment || "unknown",
            Core.draftLineFingerprint(prepickLines(request)),
        ]);
    }

    function canPullDetail(detail = state.detail) {
        // Watching a POS request does not require joining the picking session.
        return Boolean(detail && (detail.request || isSale(detail) || Core.isSharedMode(detail.tech)));
    }

    // Payment is a server fact; an unlinked fulfillment request does not imply unpaid.
    function requestPaymentLabel(request) {
        const es = state.lang === 'es';
        if (request?._posPayment === 'paid') return es ? 'Pagado · entrega por vincular' : '已付款 · 待关联交货单';
        if (request?._posPayment === 'unpaid') return t('waitingPayment');
        if (request?._posPayment === 'cancelled') return es ? 'Pedido POS cancelado · revisar' : 'POS 订单已取消 · 待核对';
        if (request?._posPayment === 'missing') return es ? 'Pedido POS no encontrado' : '未找到对应 POS 订单';
        return es ? 'Pago por verificar' : '付款状态待核对';
    }

    async function refreshRequestPayments(requests, force = false, readOptions) {
        const cache = state.requestPaymentCache ||= new Map();
        const uuids = [...new Set(requests.map(r => String(r?.x_pb_order_uuid || '')).filter(Boolean))];
        const missing = uuids.filter(uuid => force || !cache.has(uuid) || Date.now() - cache.get(uuid).at >= 15000);
        for (let offset = 0; offset < missing.length; offset += 100) {
            const batch = missing.slice(offset, offset + 100), at = Date.now();
            let orders = [], lookupSucceeded = false;
            try {
                orders = await searchRead('pos.order', [['uuid', 'in', batch]],
                    ['id', 'uuid', 'state', 'name', 'pos_reference', 'shipping_date'], { limit: batch.length * 2 }, readOptions);
                lookupSucceeded = true;
            } catch (_error) { throwIfReadCancelled(readOptions); /* A failed lookup remains unknown, never unpaid. */ }
            for (const uuid of batch) {
                const matches = orders.filter(order => order.uuid === uuid), order = matches.length === 1 ? matches[0] : null;
                const payment = posPaymentConfirmed(order) ? 'paid' : order?.state === 'draft' ? 'unpaid' : order?.state === 'cancel' ? 'cancelled' : lookupSucceeded && matches.length === 0 ? 'missing' : 'unknown';
                if (!cache.has(uuid) || cache.get(uuid).at <= at) cache.set(uuid, { at, payment });
            }
        }
        for (const request of requests) request._posPayment = cache.get(String(request.x_pb_order_uuid || ''))?.payment || 'unknown';
        while (cache.size > 1200) cache.delete(cache.keys().next().value);
        return requests;
    }

    function prepickRow(request) {
        const moves = prepickMoves(request);
        const tech = prepickTech(request, moves);
        const cancelled = request.x_pb_state === "cancelled";
        const status = cancelled ? Core.STATUS.CANCELLED : Core.statusFor(tech, moves, "assigned", "draft");
        const configName = Array.isArray(request.x_pb_config_id) ? request.x_pb_config_id[1] : "POS";
        return {
            key: prepickTaskKey(request.id),
            kind: "request",
            request,
            order: {
                id: -Number(request.id), uuid: request.x_pb_order_uuid, name: request.x_name || `PRE-${request.id}`, pos_reference: request.x_name || `PRE-${request.id}`,
                date_order: request.x_pb_requested_at || request.create_date, shipping_date: false,
                partner_id: request.x_pb_customer ? [0, request.x_pb_customer] : false,
                amount_total: Number(request.x_pb_amount || 0), state: cancelled ? "cancel" : "draft", payment_ids: [], config_id: request.x_pb_config_id,
            },
            picking: { id: -Number(request.id), name: `${request._posPayment === "paid" ? (state.lang === "es" ? "Entrega por vincular" : "交货单待关联") : t("draftOrder")} · ${configName}`, state: cancelled ? "cancel" : "assigned", scheduled_date: request.x_pb_requested_at || request.create_date, date_done: cancelled ? (request.x_pb_cancelled_at || request.write_date) : false, location_id: false },
            moves, tech, status, progress: Core.progress(tech, moves), paymentNames: [],
            responsible: { name: tech.picker || "", source: tech.picker ? "script" : "none" },
        };
    }

    async function loadPrepickRows() {
        try {
            let requests = await searchRead(PREPICK_MODEL, [["x_pb_state", "in", ["draft", "cancelled", "linked"]]], PREPICK_FIELDS, { order: "id desc", limit: 600 });
            const candidates = requests.filter((request) => request.x_pb_state === "draft" && !m2oId(request.x_pb_picking_id)).slice(0, 12);
            if (candidates.length && !state.prepickReconciling) {
                state.prepickReconciling = true;
                try {
                    const results = await Promise.allSettled(candidates.map((request) => reconcilePrepickOrder(request.x_pb_order_uuid)));
                    if (results.some((item) => item.status === "fulfilled" && (item.value?.linked || item.value?.needsConfirmation))) {
                        requests = await searchRead(PREPICK_MODEL, [["x_pb_state", "in", ["draft", "cancelled", "linked"]]], PREPICK_FIELDS, { order: "id desc", limit: 600 });
                    }
                } finally {
                    state.prepickReconciling = false;
                }
            }
            await refreshRequestPayments(requests, true);
            for (const request of requests) {
                const linkedPickingId = m2oId(request.x_pb_picking_id);
                const sessions = getSessions();
                const draftSession = sessions[String(-Number(request.id))];
                if (linkedPickingId && draftSession && !sessions[String(linkedPickingId)]) {
                    setSession(linkedPickingId, { ...draftSession, shared: true });
                    setSession(-Number(request.id), null);
                }
            }
            const visible = requests.filter((request) => !m2oId(request.x_pb_picking_id) || request.x_pb_change_pending || request.x_pb_state === "cancelled");
            const configIds = [...new Set(visible.map((request) => m2oId(request.x_pb_config_id)).filter(Boolean))];
            const configs = configIds.length ? await searchRead("pos.config", [["id", "in", configIds]], ["id", "picking_type_id"], { limit: 500 }) : [];
            const configById = new Map(configs.map((config) => [config.id, config]));
            return visible.map((request) => {
                const row = prepickRow(request);
                row.picking.picking_type_id = configById.get(m2oId(request.x_pb_config_id))?.picking_type_id || false;
                return row;
            });
        } catch (error) {
            if (/does not exist|not found|unknown model/i.test(String(error?.message || error))) return [];
            throw error;
        }
    }

    async function loadPrepickDetail(row) {
        return readPrepickTaskDetail(row);
    }

    async function readScanCatalog(productIds) {
        const fields = await discoverProductCodeFields();
        const products = await readProductsByIds(productIds, fields);
        return {products, systemCodes: await collectSystemCodes(products, fields)};
    }

    async function readPrepickStock(productIds, configId) {
        let locationId = 0;
        if (configId) {
            const config = await readOne("pos.config", configId, ["picking_type_id"]);
            const pickingTypeId = m2oId(config?.picking_type_id);
            if (pickingTypeId) {
                const pickingType = await readOne("stock.picking.type", pickingTypeId, ["default_location_src_id"]);
                locationId = m2oId(pickingType?.default_location_src_id);
            }
        }
        const quants = productIds.length && locationId ? await readAll("stock.quant", [
            ["product_id", "in", productIds], ["location_id", "child_of", locationId],
        ], ["id", "product_id", "quantity", "reserved_quantity"], 1000) : [];
        const stock = new Map();
        for (const quant of quants) {
            const id = m2oId(quant.product_id);
            stock.set(id, (stock.get(id) || 0) + Number(quant.quantity || 0));
        }
        return {stock, locationId};
    }

    async function readPrepickTaskDetail(row) {
        const request = await readOne(PREPICK_MODEL, row.request.id, PREPICK_FIELDS);
        if (!request) throw Object.assign(new Error(pbUiText("预配货任务不存在或已删除","La tarea de presurtido no existe o fue eliminada.")), { code: "PREPICK_NOT_FOUND" });
        if (request.x_pb_state === 'linked' && !request.x_pb_change_pending && m2oId(request.x_pb_picking_id) && m2oId(request.x_pb_pos_order_id)) {
            const [linkedPicking, linkedOrder] = await Promise.all([
                readOne('stock.picking', m2oId(request.x_pb_picking_id), pickingIndexFields()),
                readOne('pos.order', m2oId(request.x_pb_pos_order_id), ['id', 'uuid', 'name', 'pos_reference', 'state', 'partner_id', 'amount_total', 'date_order', 'shipping_date']),
            ]);
            if (linkedPicking?.state === 'done' && linkedOrder?.uuid === request.x_pb_order_uuid &&
                (!m2oId(linkedPicking.pos_order_id) || m2oId(linkedPicking.pos_order_id) === linkedOrder.id))
                return readDeliveryTaskDetail(pickingSummaryRow(linkedPicking, linkedOrder, 'order'));
        }
        const [, sharedEvents] = await Promise.all([
            refreshRequestPayments([request], true),
            request.x_pb_change_pending ? [] : loadSharedEvents(null, request.id),
        ]);
        const freshRow = prepickRow(request);
        const moves = freshRow.moves;
        const storedTech = prepickTech(request, moves);
        const tech = request.x_pb_change_pending ? storedTech : Core.isSharedMode(storedTech) ? Core.replaySharedEvents(storedTech, moves, sharedEvents) : storedTech;
        const orderProductIds = [...new Set(moves.map((move) => Number(move.product_id[0])))];
        const productIds = [...new Set([...orderProductIds, ...Object.entries(tech.extraCounts || {}).filter(([, qty]) => Number(qty) > 0).map(([id]) => Number(id))])];
        const [{products, systemCodes}, {stock, locationId}] = await Promise.all([
            readScanCatalog(productIds),
            readPrepickStock(productIds, m2oId(request.x_pb_config_id)),
        ]);
        const odooCodeCount = new Set(systemCodes.flatMap((item) => Core.parseCodeList(item.code))).size;
        const boxCodeCount = new Set(state.boxMappings.filter((item) => item.enabled).map((item) => Core.normalizeCode(item.boxCode)).filter(Boolean)).size;
        return {
            ...freshRow, row: freshRow, request, moves, products, stock, stockLocationId: locationId, tech, storedTech, sharedEvents,
            sharedEventCount: Number(tech?.eventSync?.eventCount || sharedEvents.length), systemCodes, orderProductIds,
            responsible: { name: tech.picker || "", source: tech.picker ? "script" : "none" },
            index: Core.productCodeIndex(products, state.boxMappings, systemCodes),
            codesLoadedAt: Date.now(), odooCodeCount, boxCodeCount, boxCodesLoadedAt: state.boxLoadedAt,
        };
    }

    async function discoverFields(readOptions) {
        if (state.fieldMap) return state.fieldMap;
        const defs = await fieldsOf("stock.picking", readOptions);
        const byLabel = (label, type) => Object.entries(defs).find(([, def]) => def.string === label && (!type || def.type === type))?.[0];
        const byIdType = (name, type) => defs[name]?.type === type ? name : null;
        const result = {
            exception: byIdType(LIVE_FIELDS.exception, "text") || byLabel("配货异常", "text"),
            started: byIdType(LIVE_FIELDS.started, "datetime") || byLabel("开始配货时间", "datetime"),
            ready: byIdType(LIVE_FIELDS.ready, "datetime") || byLabel("配齐时间", "datetime"),
            progress: byIdType(LIVE_FIELDS.progress, "char") || byLabel("配货进度", "char"),
            picker: byIdType(LIVE_FIELDS.picker, "char") || byLabel("配货负责人", "char"),
            status: byIdType(LIVE_FIELDS.status, "selection") || byLabel("配货状态", "selection"),
        };
        const textCandidates = Object.entries(defs).filter(([name, def]) =>
            name.startsWith("x_studio_text_field_") && def.type === "text" && name !== result.exception
        );
        const defaultTechCandidates = textCandidates.filter(([, def]) => /新建|new multiline/i.test(def.string || ""));
        result.tech = byIdType(LIVE_FIELDS.tech, "text") || byLabel("配货技术数据", "text") || (defaultTechCandidates.length === 1 ? defaultTechCandidates[0][0] : null);
        if (!result.tech && textCandidates.length === 1) result.tech = textCandidates[0][0];
        const missing = Object.entries(result).filter(([, value]) => !value).map(([key]) => key);
        if (missing.length) throw new Error(`缺少 Studio 字段：${missing.join(", ")}`);
        result.legacyPicker = defs.x_studio_picker_name ? "x_studio_picker_name" : ["配货员", "Surtidor"].map((label) => byLabel(label, "char")).find(Boolean) || null;
        const selection = defs[result.status]?.selection || [];
        result.statusValue = Object.fromEntries(Object.entries(Core.STATUS_LABELS).map(([code, label]) => {
            const pair = selection.find((item) => item[0] === code || item[1] === label);
            return [code, pair?.[0] ?? null];
        }));
        const writableStatuses = [Core.STATUS.PICKING, Core.STATUS.READY, Core.STATUS.EXCEPTION];
        const missingStatuses = writableStatuses.filter((code) => result.statusValue[code] == null).map((code) => Core.STATUS_LABELS[code]);
        if (missingStatuses.length) throw new Error(`“配货状态”缺少选项：${missingStatuses.join("、")}`);
        state.fieldMap = result;
        return result;
    }

    function m2oName(value) { return Array.isArray(value) ? String(value[1] || "").trim() : ""; }
    function effectivePicker(picking, tech) {
        const scripted = String(tech?.picker || picking?.[state.fieldMap?.picker] || "").trim();
        if (scripted) return { name: scripted, source: "script" };
        const legacy = state.fieldMap?.legacyPicker ? String(picking?.[state.fieldMap.legacyPicker] || "").trim() : "";
        if (legacy) return { name: legacy, source: "legacy" };
        const native = m2oName(picking?.user_id);
        if (native) return { name: native, source: "native" };
        return { name: "", source: "none" };
    }

    async function discoverProductCodeFields() {
        if (state.productCodeFields) return state.productCodeFields;
        const defs = await fieldsOf("product.product");
        const pattern = /(bar\s*code|barcode|条\s*码|條\s*碼|条形码|codigo\s+de\s+barras|código\s+de\s+barras|codigo\s+altern|código\s+altern|alternate\s*code|secondary\s*code|backup\s*code|备用.*码|替代.*码)/i;
        const excluded = new Set(["barcode", "default_code", "display_name", "name"]);
        const fields = Object.entries(defs).filter(([name, def]) =>
            !excluded.has(name) && ["char", "text"].includes(def.type) && pattern.test(`${name} ${def.string || ""}`)
        ).map(([name]) => name);
        state.productCodeFieldLabels = Object.fromEntries(fields.map((name) => [name, defs[name]?.string || name]));
        state.productCodeFieldDefs = Object.fromEntries(fields.map((name) => [name, defs[name]]));
        state.productCodeFields = fields;
        return fields;
    }

    function productReadFields(codeFields = state.productCodeFields || []) {
        return ["id", "display_name", "default_code", "barcode", "tracking", "product_tmpl_id", "uom_id", ...codeFields];
    }

    async function readProductsByIds(productIds, codeFields) {
        if (!productIds.length) return [];
        try {
            return await readAll("product.product", [["id", "in", productIds]], productReadFields(codeFields), 1000);
        } catch (error) {
            if (isNetworkError(error)) throw error;
            state.productCodeFields = [];
            state.productCodeFieldLabels = {};
            state.productCodeFieldDefs = {};
            return readAll("product.product", [["id", "in", productIds]], productReadFields([]), 1000);
        }
    }

    async function resolveUomBarcodes(rows, products) {
        if (!rows.length) return [];
        const baseUnits = new Map(products.map(p => [p.id,m2oId(p.uom_id)]));
        const ids = [...new Set([...rows.map(r => m2oId(r.uom_id)),...baseUnits.values()].filter(Boolean))];
        const units = await searchRead("uom.uom",[["id","in",ids]],["id","factor"],{limit:ids.length});
        const factors = new Map(units.map(u => [u.id,Number(u.factor)]));
        return rows.map(r => {
            const productId = m2oId(r.product_id);
            const ratio = factors.get(m2oId(r.uom_id))/factors.get(baseUnits.get(productId));
            const qty = Math.round(ratio);
            return { productId, code:r.barcode, source:"odoo_packaging", field:"product.uom.barcode",
                quantity:Number.isSafeInteger(qty) && qty>0 && qty<=9999 && Math.abs(ratio-qty)<1e-9 ? qty : 0 };
        });
    }

    async function lookupProductUomCodeMatches(code, operator = "=") {
        try {
            const defs = await fieldsOf("product.uom");
            if (!defs.barcode || defs.product_id?.relation !== "product.product") return [];
            const rows = await searchRead("product.uom", [["barcode", operator, code], ["product_id", "!=", false]], ["id", "barcode", "product_id", "uom_id"], { limit: 50 });
            const products = await readProductsByIds([...new Set(rows.map(r => m2oId(r.product_id)))], []);
            return await resolveUomBarcodes(rows,products);
        } catch (error) {
            if (isNetworkError(error)) throw error;
            return [];
        }
    }

    async function lookupLegacyPackagingCodeMatches(code, operator = "=") {
        try {
            const defs = await fieldsOf("product.packaging");
            if (!defs.barcode) return [];
            const linkField = defs.product_id?.relation === "product.product" ? "product_id" : defs.product_tmpl_id?.relation === "product.template" ? "product_tmpl_id" : null;
            if (!linkField) return [];
            const rows = await searchRead("product.packaging", [["barcode", operator, code]], ["id", "barcode", linkField], { limit: 20 });
            const linkedIds = [...new Set(rows.map((row) => Array.isArray(row[linkField]) ? row[linkField][0] : row[linkField]).filter(Boolean))];
            if (linkField === "product_id") return rows.map(row => ({ productId: m2oId(row.product_id), code: row.barcode })).filter(row => row.productId);
            const products = linkedIds.length ? await searchRead("product.product", [["product_tmpl_id", "in", linkedIds]], ["id", "product_tmpl_id"], { limit: 100 }) : [];
            return rows.flatMap(row => products.filter(product => m2oId(product.product_tmpl_id) === m2oId(row[linkField]))
                .map(product => ({ productId: product.id, code: row.barcode })));
        } catch (error) {
            if (isNetworkError(error)) throw error;
            return [];
        }
    }

    async function lookupPackagingCodeMatches(code, operator = "=") {
        const groups = await Promise.all([lookupProductUomCodeMatches(code, operator), lookupLegacyPackagingCodeMatches(code, operator)]);
        return groups.flat();
    }

    async function lookupPackagingProductIds(code) {
        const matches = await lookupPackagingCodeMatches(code);
        return [...new Set(matches.map(row => Number(row.productId)).filter((id) => Number.isInteger(id) && id > 0))];
    }

    async function lookupProductByCode(rawCode) {
        const code = Core.normalizeCode(rawCode);
        const codeFields = await discoverProductCodeFields();
        const sheetMatches = state.boxMappings.filter((item) => item.enabled && Core.normalizeCode(item.boxCode) === code);
        const sheetTargets = sheetMatches.map((item) => Core.normalizeCode(item.boxCodeIsProductCode ? item.boxCode : item.unitCode)).filter(Boolean);
        const searchCodes = [...new Set([code, ...sheetTargets])];
        const clauses = [];
        for (const candidate of searchCodes) {
            clauses.push(["barcode", "=", candidate], ["default_code", "=", candidate]);
            for (const field of codeFields) clauses.push([field, "ilike", candidate]);
        }
        const domain = clauses.length > 1 ? [...Array(clauses.length - 1).fill("|"), ...clauses] : clauses;
        // Product and packaging lookups are independent; check both before resolving ambiguity.
        const [rows, relatedGroups] = await Promise.all([
            (async () => {
                if (!clauses.length) return [];
                try { return await searchRead("product.product", domain, productReadFields(codeFields), { limit: 50 }); }
                catch (error) {
                    if (isNetworkError(error)) throw error;
                    const basicClauses = searchCodes.flatMap(candidate => [["barcode", "=", candidate], ["default_code", "=", candidate]]);
                    const basicDomain = basicClauses.length > 1 ? [...Array(basicClauses.length - 1).fill("|"), ...basicClauses] : basicClauses;
                    return searchRead("product.product", basicDomain, productReadFields([]), { limit: 50 });
                }
            })(),
            Promise.all(searchCodes.map(async candidate => ({ code: candidate, matches: await lookupPackagingCodeMatches(candidate) }))),
        ]);
        const relatedCodes = new Map();
        for (const group of relatedGroups) for (const {productId:id} of group.matches) {
            if (!relatedCodes.has(id)) relatedCodes.set(id, new Set());
            relatedCodes.get(id).add(group.code);
        }
        const byId = new Map(rows.map(product => [Number(product.id), product]));
        const missingIds = [...relatedCodes.keys()].filter(id => !byId.has(id));
        for (const product of await readProductsByIds(missingIds, codeFields)) byId.set(Number(product.id), product);
        const candidates = new Map();
        for (const product of byId.values()) {
            const productCodes = new Set([Core.normalizeCode(product.barcode), Core.normalizeCode(product.default_code), ...codeFields.flatMap((field) => Core.parseCodeList(product[field])), ...(relatedCodes.get(Number(product.id)) || [])].filter(Boolean));
            const direct = productCodes.has(code);
            const matchingSheetRows = sheetMatches.filter((mapping) => productCodes.has(Core.normalizeCode(mapping.boxCodeIsProductCode ? mapping.boxCode : mapping.unitCode)));
            const sheetQuantities = [...new Set(matchingSheetRows.map((mapping) => Number(mapping.quantity || 1)))];
            if (sheetQuantities.length > 1) return { ambiguous: true, productIds: [product.id], reason: "box_quantity_conflict" };
            if (matchingSheetRows.length) candidates.set(product.id, { product, source: "sheet_fallback", quantity: sheetQuantities[0] || 1 });
            else if (direct) candidates.set(product.id, { product, source: relatedCodes.get(Number(product.id))?.has(code) ? "odoo_packaging" : "odoo_product", quantity: relatedGroups.find(g => g.code===code)?.matches.find(m => m.productId===product.id)?.quantity ?? 1 });
        }
        if (candidates.size > 1) return { ambiguous: true, productIds: [...candidates.keys()] };
        return candidates.values().next().value || null;
    }

    function productSearchDomain(rawQuery, codeFields = state.productCodeFields || []) {
        const query = String(rawQuery || "").trim();
        const fields = [...new Set(["default_code", "barcode", "name", ...codeFields])];
        return [...Array(fields.length - 1).fill("|"), ...fields.map(field => [field, "ilike", query])];
    }

    async function searchAllProducts(rawQuery, requestSeq) {
        const query = String(rawQuery || "").trim();
        const pickingId = Number(state.detail?.picking?.id || 0);
        if (query.length < 2 || !pickingId || requestSeq !== state.productSearchSeq) return;
        state.productSearching = true;
        state.productSearchDone = false;
        state.productSearchError = "";
        updateProductSearchResults();
        try {
            const codeFields = await discoverProductCodeFields();
            const [basicRows, relatedCodes] = await Promise.all([
                searchRead("product.product", productSearchDomain(query, codeFields), [...productReadFields(codeFields), "name"], { limit: 50, order: "default_code,name,id" }),
                lookupPackagingCodeMatches(query, "ilike"),
            ]);
            const byId = new Map(basicRows.map(product => [Number(product.id), product]));
            const relatedIds = [...new Set(relatedCodes.map(row => Number(row.productId)).filter(id => !byId.has(id)))];
            for (const product of await readProductsByIds(relatedIds, codeFields)) byId.set(Number(product.id), product);
            const exactCode = Core.normalizeCode(query);
            const rows = [...byId.values()].map(product => {
                const codes = [product.barcode, product.default_code, ...codeFields.flatMap(field => Core.parseCodeList(product[field])),
                    ...relatedCodes.filter(row => Number(row.productId) === Number(product.id)).map(row => row.code)];
                return { ...product, _pbMatchedCode: codes.some(value => value && Core.normalizeCode(value) === exactCode) ? exactCode : "" };
            });
            if (requestSeq !== state.productSearchSeq || Number(state.detail?.picking?.id || 0) !== pickingId || String(state.productQuery || "").trim() !== query) return;
            const orderedIds = new Set((state.detail.orderProductIds || []).map(Number));
            state.productResults = rows.sort((left, right) => Number(Boolean(right._pbMatchedCode)) - Number(Boolean(left._pbMatchedCode)) ||
                Number(orderedIds.has(Number(right.id))) - Number(orderedIds.has(Number(left.id)))).slice(0, 12);
            state.productSearchDone = true;
            state.productSearchIndex = -1;
        } catch (error) {
            if (requestSeq !== state.productSearchSeq || Number(state.detail?.picking?.id || 0) !== pickingId) return;
            state.productResults = [];
            state.productSearchDone = true;
            state.productSearchError = error.message || String(error);
            state.productSearchIndex = -1;
        } finally {
            if (requestSeq === state.productSearchSeq && Number(state.detail?.picking?.id || 0) === pickingId) {
                state.productSearching = false;
                updateProductSearchResults();
            }
        }
    }

    function clearProductSearch(renderView = false) {
        clearTimeout(state.productSearchTimer);
        state.productSearchSeq += 1;
        state.productQuery = "";
        state.productResults = [];
        state.productSearching = false;
        state.productSearchDone = false;
        state.productSearchError = "";
        state.productSearchIndex = -1;
        if (renderView) updateProductSearchResults();
    }

    function scheduleProductSearch(rawQuery) {
        const query = String(rawQuery || "");
        const normalized = query.trim();
        const hadDropdown = state.productSearching || state.productSearchDone || state.productResults.length || state.productSearchError;
        clearTimeout(state.productSearchTimer);
        state.productSearchSeq += 1;
        state.productQuery = query;
        state.productResults = [];
        state.productSearching = false;
        state.productSearchError = "";
        state.productSearchIndex = -1;
        state.productSearchDone = false;
        if (normalized.length < 2) {
            if (hadDropdown) updateProductSearchResults();
            return;
        }
        if (hadDropdown) updateProductSearchResults();
        const requestSeq = state.productSearchSeq;
        state.productSearchTimer = setTimeout(() => searchAllProducts(normalized, requestSeq), 260);
    }

    async function loadProductUomCodes(products) {
        if (!products.length) return [];
        try {
            const defs = await fieldsOf("product.uom");
            if (!defs.barcode || defs.product_id?.relation !== "product.product") return [];
            const productIds = products.map((item) => item.id);
            const rows = await readAll("product.uom", [["product_id", "in", productIds], ["barcode", "!=", false]], ["id", "barcode", "product_id", "uom_id"], 1000);
            return await resolveUomBarcodes(rows,products);
        } catch (error) {
            if (isNetworkError(error)) throw error;
            return [];
        }
    }

    async function loadLegacyPackagingCodes(products) {
        if (!products.length) return [];
        try {
            const defs = await fieldsOf("product.packaging");
            if (!defs.barcode) return [];
            const productIds = products.map((item) => item.id);
            const templateIds = [...new Set(products.map((item) => Array.isArray(item.product_tmpl_id) ? item.product_tmpl_id[0] : null).filter(Boolean))];
            const linkField = defs.product_id?.relation === "product.product" ? "product_id" : defs.product_tmpl_id?.relation === "product.template" ? "product_tmpl_id" : null;
            if (!linkField) return [];
            const ids = linkField === "product_id" ? productIds : templateIds;
            if (!ids.length) return [];
            const rows = await searchRead("product.packaging", [[linkField, "in", ids], ["barcode", "!=", false]], ["id", "name", "barcode", linkField], { limit: 5000 });
            const variantsByTemplate = new Map();
            for (const product of products) {
                const templateId = Array.isArray(product.product_tmpl_id) ? product.product_tmpl_id[0] : null;
                if (!variantsByTemplate.has(templateId)) variantsByTemplate.set(templateId, []);
                variantsByTemplate.get(templateId).push(product.id);
            }
            return rows.flatMap((row) => {
                const linkedId = Array.isArray(row[linkField]) ? row[linkField][0] : row[linkField];
                const targets = linkField === "product_id" ? [linkedId] : (variantsByTemplate.get(linkedId) || []);
                return targets.map((productId) => ({ code: row.barcode, productId, source: "odoo_packaging", field: "product.packaging.barcode" }));
            });
        } catch (error) {
            if (isNetworkError(error)) throw error;
            return [];
        }
    }

    async function loadPackagingCodes(products) {
        const groups = await Promise.all([loadProductUomCodes(products), loadLegacyPackagingCodes(products)]);
        return groups.flat();
    }

    async function collectSystemCodes(products, codeFields) {
        const alternate = [];
        for (const product of products) {
            for (const field of codeFields) {
                for (const code of Core.parseCodeList(product[field])) alternate.push({ code, productId: product.id, source: "odoo_alternate", field });
            }
        }
        return [...alternate, ...(await loadPackagingCodes(products))];
    }

    // A bridge keeps the original sale picking as the immutable event/session identity.
    // Only native stock writes use the verified POS delivery. No quantities are migrated.
    const BRIDGE_STATES = ['bridge_wait', 'bridge_pending', 'bridge_picking', 'bridge_ready', 'bridge_exception', 'bridge_done', 'bridge_cancelled'];
    const bridgePayload = record => Core.safeParse(record?.x_pb_payload)?.fulfillmentBridge || null;
    const paidBridge = record => BRIDGE_STATES.includes(record?.x_pb_state) && record.x_pb_state !== 'bridge_wait';
    const bridgeError = (zh, es = zh) => Object.assign(new Error(state.lang === 'es' ? es : zh), {code: 'FULFILLMENT_BRIDGE'});
    function posPaymentConfirmed(order) {
        // Odoo 19 paid/posted; invoiced is the equivalent terminal paid state in Odoo 18.
        return Boolean(order && ['paid','done','invoiced'].includes(order.state));
    }
    function acceptancePaymentProblem(detail) {
        if (!detail) return '';
        if (detail.bridge && !detail.bridge.paid) return state.lang==='es'
            ? 'POS vinculado pendiente de pago; revise el vínculo antes de validar.'
            : '已关联 POS 尚未付款，请先核对关联再验收。';
        if (detail.request) return requestPaymentLabel(detail.request) + (state.lang === 'es' ? ' · Vincule la entrega antes de validar.' : '；须先完成交货单关联。');
        if (!isSale(detail) && !posPaymentConfirmed(detail.row?.order)) return state.lang==='es'
            ? 'El presurtido requiere pago confirmado antes de validar.'
            : '预配货须付款成功后才能验收。';
        return '';
    }
    async function assertAcceptancePayment(detail, targetId) {
        const fail=(zh,es,code='WAITING_PAYMENT')=>{throw Object.assign(new Error(state.lang==='es'?es:zh),{code});};
        if (detail.request) fail(acceptancePaymentProblem(detail), acceptancePaymentProblem(detail));
        if (isSale(detail)) {
            const record=await bridgeForSource(detail.picking.id);
            if (Boolean(record)!==Boolean(detail.bridge) || (record && Number(record.id)!==Number(detail.bridge.record.id)))
                fail('销售与 POS 的关联已变化，请同步后核对。','Cambió el vínculo con POS; sincronice y revise.','DELIVERY_LINK_CHANGED');
            if (!record) return; // Ordinary sales settlement does not require POS.
            if (!detail.bridge.paid) fail('已关联 POS 尚未付款，请先核对关联，不能重复出库。','El POS vinculado no está pagado; revise el vínculo antes de validar.');
            if (record.x_pb_order_uuid!==detail.bridge.record.x_pb_order_uuid)
                fail('付款关联已变化，请重新打开配货任务。','Cambió el vínculo de pago; vuelva a abrir el surtido.','DELIVERY_LINK_CHANGED');
        }
        const expectedOrderId=isSale(detail)?Number(detail.bridge.posOrder.id):Number(detail.row?.order?.id);
        if (!Number.isSafeInteger(expectedOrderId)||expectedOrderId<=0) fail('无法确认本单对应的付款订单。','No se pudo identificar el pedido pagado.');
        const native=await readOne('stock.picking',targetId,['id','state','pos_order_id']);
        if (!native || ['done','cancel'].includes(native.state) || m2oId(native.pos_order_id)!==expectedOrderId)
            fail('实际交货单或订单关联已变化，请同步后核对。','Cambió la entrega o su pedido; sincronice y revise.','DELIVERY_LINK_CHANGED');
        const order=await readOne('pos.order',expectedOrderId,['id','uuid','state','picking_ids']);
        if (!posPaymentConfirmed(order)) fail('服务器尚未确认付款成功，暂不能验收出库。','El servidor no confirma el pago; no se puede validar la salida.');
        if (!(order.picking_ids||[]).map(m2oId).includes(Number(targetId)) || (detail.bridge && order.uuid!==detail.bridge.record.x_pb_order_uuid))
            fail('付款订单与实际交货单不匹配。','El pedido pagado no corresponde a la entrega.','DELIVERY_LINK_CHANGED');
    }
    function bridgeMoveLines(moves) {
        return Core.normalizeDraftLines(moves.filter(m => Core.demandOf(m) > 0).map(m => ({productId: m2oId(m.product_id), quantity: Core.demandOf(m)})));
    }
    async function paidBridgeGoodsLines(lines, knownProducts = null) {
        if (lines.some(l=>!Number.isFinite(Number(l.qty)) || Number(l.qty)<0))
            throw bridgeError('付款商品含退货或无效数量，请核对原单。','El pedido pagado contiene devoluciones o cantidades no válidas.');
        const ids = [...new Set(lines.map(l=>m2oId(l.product_id)))];
        const products = knownProducts || await readAll('product.product', [['id','in',ids]], ['id','type'], 1000);
        const types = new Map(products.map(p=>[Number(p.id),p.type]));
        if (ids.some(id=>!id || !types.has(id) || !types.get(id)))
            throw bridgeError('付款已完成，但商品类型未能核实，请同步后重试，不要再次付款。','Pago completado; no se pudo verificar el tipo de producto. Sincronice, no vuelva a pagar.');
        // Service charges remain on the financial order, but never require a stock move.
        // Consumables are goods too, even when inventory tracking is disabled.
        return Core.normalizeDraftLines(lines.filter(l=>types.get(m2oId(l.product_id))!=='service').map(l=>({productId:m2oId(l.product_id),quantity:l.qty})));
    }
    function assertBridgeQuantity(lines, moves) {
        if (!moves.length || moves.some(m => !Number.isSafeInteger(Core.demandOf(m)) || Core.demandOf(m) < 0) ||
            Core.draftLineFingerprint(lines) !== Core.draftLineFingerprint(bridgeMoveLines(moves))) {
            throw bridgeError('POS 商品数量与所选销售交货单不一致。请在销售单确认修改，再重新导入 POS。', 'Los productos o cantidades no coinciden con la entrega de venta. Revise la venta y vuelva a importarla al POS.');
        }
    }
    function assertBridgeNative(source, target, sourceMoves, targetMoves) {
        if (!m2oId(source.location_id) || m2oId(source.location_id) !== m2oId(target.location_id))
            throw bridgeError('销售与 POS 发货仓库不同，已阻止自动关联。', 'Los almacenes de venta y POS son distintos.');
        assertBridgeQuantity(bridgeMoveLines(sourceMoves), targetMoves);
        const units = moves => {
            const totals = new Map();
            for (const move of moves.filter(m => Core.demandOf(m)>0)) {
                const key = [m2oId(move.product_id), m2oId(move.product_uom)].join(':');
                totals.set(key, (totals.get(key) || 0) + Core.demandOf(move));
            }
            return JSON.stringify([...totals].sort(([a],[b])=>a.localeCompare(b)));
        };
        if (units(sourceMoves) !== units(targetMoves)) throw bridgeError('销售与 POS 商品单位不一致。', 'Las unidades de medida no coinciden.');
    }
    async function bridgeForSource(id) {
        const rows = await searchRead(PREPICK_MODEL, [['x_pb_picking_id', '=', id], ['x_pb_state', 'in', BRIDGE_STATES]], PREPICK_FIELDS, {order: 'id', limit: 2});
        if (rows.length > 1) throw bridgeError('此销售配货任务存在重复付款关联，请先核对。', 'Hay vínculos de pago duplicados; revise el pedido.');
        return rows[0] || null;
    }
    function assertBridgeTargetSnapshot(detail,pickingId,moves) {
        if(!detail.bridge)return;
        if(!detail.bridge.paid || detail.bridge.target.id!==pickingId || ['done','cancel'].includes(detail.bridge.target.state) || Core.quantityBaseline(detail.bridge.nativeMoves)!==Core.quantityBaseline(moves))
            throw bridgeError('实际交货单已变化，未继续出库，请同步后核对。','Cambió la entrega real. Sincronice y revise antes de validar.');
    }
    async function sourceRowForBridge(record) {
        const data = bridgePayload(record);
        if (!data || m2oId(record.x_pb_picking_id) !== data.sourcePickingId) throw bridgeError('销售配货关联资料不完整。', 'El vínculo de surtido está incompleto.');
        const picking = await readOne('stock.picking', data.sourcePickingId, pickingIndexFields());
        const order = await readOne('sale.order', data.saleId, ['id','name','state','partner_id','user_id','date_order','amount_total','client_order_ref','warehouse_id']);
        if (!picking || !order || m2oId(picking.sale_id) !== order.id) throw bridgeError('销售单关联已变化。', 'Cambió el vínculo de la venta.');
        return pickingSummaryRow(picking, order, 'sale');
    }
    async function ensureBridgeEnrollment(record) {
        const sourceId=m2oId(record?.x_pb_picking_id),requestId=Number(record?.id);
        if(!sourceId||!Number.isSafeInteger(requestId)||requestId<=0)throw bridgeError('配货关联编号无效。','El identificador del vínculo no es válido.');
        const domain=[['x_pb_operation','=',SALES_QUEUE_OPERATION],['x_pb_picking_id','=',sourceId],['x_pb_request_id','=',requestId]];
        const exists=async()=>searchRead(SHARED_EVENT_MODEL,domain,['id'],{limit:1});
        if((await exists()).length)return;
        const id=`sales-bridge:${sourceId}:${requestId}`;
        // Audit events are append-only. Grouping by picking and inverse-relation filtering
        // make both old registration and new link one task, without rewriting history.
        const values={x_name:id,x_pb_picking_id:sourceId,x_pb_request_id:requestId,x_pb_operation:SALES_QUEUE_OPERATION,
            x_pb_status:'done',x_pb_payload:JSON.stringify({op:{id,scope:'sales_queue',type:'add',pickingId:sourceId,requestId},version:VERSION})};
        try{await rpc(SHARED_EVENT_MODEL,'create',[values]);}
        catch(error){if(!(await exists()).length)throw error;}
        if(!(await exists()).length)throw bridgeError('配货关联未保存，请重试。','No se guardó el vínculo; vuelva a intentar.');
        salesQueueEpoch++;
    }
// A refunded POS sale can have no native sale delivery. It may be prepared as
// a POS delivery only after every physical sale line and prior POS line agrees.
function pbCanUsePosPrepickForRepaidSale({snapshot, saleLines, priorLines, priorOrders, discountProductId}) {
    if (snapshot.saleIds.length !== 1 || snapshot.hasUnlinkedLines || !snapshot.linkedLines?.length) return false;
    const saleId = snapshot.saleIds[0];
    const expected = new Map();
    for (const line of saleLines) {
        const productId = Array.isArray(line.product_id) ? line.product_id[0] : line.product_id;
        if (!productId || productId === discountProductId || line.service) continue;
        const qty = Number(line.product_uom_qty);
        if (!Number.isSafeInteger(qty) || qty <= 0) return false;
        expected.set(line.id, { productId, qty });
    }
    if (!expected.size) return false;
    const current = new Map();
    for (const line of snapshot.linkedLines) {
        if (line.saleId !== saleId || !expected.has(line.saleLineId) || current.has(line.saleLineId)) return false;
        current.set(line.saleLineId, line);
    }
    if (current.size !== expected.size) return false;
    for (const [id, goods] of expected) {
        const line = current.get(id);
        if (!line || line.productId !== goods.productId || line.quantity !== goods.qty) return false;
    }
    const orders = new Map(priorOrders.map(order => [order.id, order]));
    const previous = priorLines.filter(line => {
        const productId = Array.isArray(line.product_id) ? line.product_id[0] : line.product_id;
        return productId !== discountProductId && Number(line.qty) > 0;
    });
    if (!previous.length) return false;
    for (const line of previous) {
        const orderId = Array.isArray(line.order_id) ? line.order_id[0] : line.order_id;
        const order = orders.get(orderId);
        const configId = Array.isArray(order?.config_id) ? order.config_id[0] : order?.config_id;
        const productId = Array.isArray(line.product_id) ? line.product_id[0] : line.product_id;
        const goods = expected.get(Array.isArray(line.sale_order_line_id) ? line.sale_order_line_id[0] : line.sale_order_line_id);
        if (!order || !['paid', 'done', 'invoiced'].includes(order.state) ||
            configId !== snapshot.configId || !goods || goods.productId !== productId ||
            Number(line.refunded_qty) + 1e-7 < Number(line.qty)) return false;
    }
    return true;
}

    // Financial refunds can exist before the goods arrive. Require dated native
    // move lines, in the same location pair and base unit, for each paid order.
    async function repaidStockReturned(snapshot, sale, priorLines, priorOrders, discountProductId) {
        const sold = priorLines.filter(l=>l.qty>0 && m2oId(l.product_id)!==discountProductId);
        if (!sold.length) return false;
        const refundIds = [...new Set(sold.flatMap(l=>l.refund_orderline_ids || []))];
        if (!refundIds.length) return false;
        const refunds = await readAll('pos.order.line',[['id','in',refundIds]],['order_id','product_id','qty','refunded_orderline_id']);
        const products = await readAll('product.product',[['id','in',[...new Set(sold.map(l=>m2oId(l.product_id)))]]],['uom_id','tracking']);
        const base = new Map(products.map(p=>[p.id,m2oId(p.uom_id)]));
        if (products.some(p=>p.tracking!=='none')) return false;
        for (const line of sold) {
            const linked = refunds.filter(r=>m2oId(r.refunded_orderline_id)===line.id);
            if (!linked.length || linked.some(r=>r.qty>=0 || m2oId(r.product_id)!==m2oId(line.product_id)) ||
                linked.reduce((q,r)=>q-r.qty,0)!==line.qty) return false;
        }
        const refundOrders = [...new Set(refunds.map(r=>m2oId(r.order_id)))];
        const paid = await readAll('pos.order',[['id','in',[...new Set([...priorOrders.map(o=>o.id),...refundOrders])]]],
            ['state','config_id','picking_ids','company_id']);
        const config=await readOne('pos.config',snapshot.configId,['picking_type_id']);
        const type=await readOne('stock.picking.type',m2oId(config?.picking_type_id),['warehouse_id','default_location_src_id','default_location_dest_id']);
        if (!type || m2oId(type.warehouse_id)!==m2oId(sale.warehouse_id)) return false;
        const src=m2oId(type.default_location_src_id),dst=m2oId(type.default_location_dest_id);
        if (!src || !dst || src===dst) return false;
        const expected=new Map();
        for (const l of [...sold,...refunds]) {
            const id=m2oId(l.order_id),p=m2oId(l.product_id);
            if (!expected.has(id)) expected.set(id,new Map());
            const sums=expected.get(id); sums.set(p,(sums.get(p)||0)+l.qty);
        }
        // Extra returns created from native transfers can coexist with a POS
        // refund. An additional or pending reverse move needs physical review.
        const receiptIds = [...new Set(paid.flatMap(o=>o.picking_ids))];
        if (receiptIds.length) {
            const reverse = await searchRead('stock.picking',[['return_id','in',receiptIds],['id','not in',receiptIds],['state','!=','cancel']],['id'],{limit:1});
            if (reverse.length) return false;
        }
        for (const [orderId, expectedQty] of expected) {
            const order=paid.find(o=>o.id===orderId);
            if (!order || !posPaymentConfirmed(order) || m2oId(order.config_id)!==snapshot.configId ||
                m2oId(order.company_id)!==m2oId(sale.company_id) || !order.picking_ids.length) return false;
            const picks=await readAll('stock.picking',[['id','in',order.picking_ids]],['state','pos_order_id','date_done']);
            if (picks.length!==order.picking_ids.length || picks.some(p=>m2oId(p.pos_order_id)!==orderId || !['done','cancel'].includes(p.state))) return false;
            const done=picks.filter(p=>p.state==='done' && p.date_done).map(p=>p.id);
            if (!done.length) return false;
            const rows=await readAll('stock.move.line',[['picking_id','in',done]],['product_id','product_uom_id','location_id','location_dest_id','quantity','state','owner_id','lot_id']);
            const remaining=new Map(expectedQty);
            const returning=refundOrders.includes(orderId);
            for (const row of rows) {
                const p=m2oId(row.product_id);
                if (row.state!=='done' || row.quantity<=0 || !remaining.has(p) || !base.get(p) ||
                    m2oId(row.product_uom_id)!==base.get(p) || row.lot_id || row.owner_id ||
                    m2oId(row.location_id)!==(returning?dst:src) || m2oId(row.location_dest_id)!==(returning?src:dst)) return false;
                remaining.set(p,remaining.get(p)+(returning?row.quantity:-row.quantity));
            }
            if ([...remaining.values()].some(n=>n!==0)) return false;
        }
        return true;
    }
    async function pbUsePosPrepickForRepaidSale(snapshot) {
        if(snapshot.saleIds.length!==1 || snapshot.hasUnlinkedLines) return false;
        const saleId=snapshot.saleIds[0];
        const sale=await readOne('sale.order',saleId,['id','state','company_id','warehouse_id']);
        if(sale?.state!=='sale') return false;
        const salePickings=await searchRead('stock.picking',
            [['sale_id','=',saleId],['picking_type_code','=','outgoing'],['state','!=','cancel']],['id'],{limit:1});
        if(salePickings.length) return false;
        const config=await readOne('pos.config',snapshot.configId,['discount_product_id']);
        const discountProductId=m2oId(config?.discount_product_id);
        if(!discountProductId) return false;
        const saleLines=await readAll('sale.order.line',[['order_id','=',saleId]],
            ['id','product_id','product_uom_qty'],1000);
        const productIds=[...new Set(saleLines.map(line=>m2oId(line.product_id)).filter(Boolean))];
        const products=await readAll('product.product',[['id','in',productIds]],['id','type'],1000);
        const productTypes=new Map(products.map(product=>[product.id,product.type]));
        if(productIds.some(id=>!productTypes.has(id))) return false;
        const priorLines=await readAll('pos.order.line',[['sale_order_origin_id','=',saleId]],
            ['id','order_id','product_id','sale_order_line_id','qty','refunded_qty','refund_orderline_ids'],1000);
        const orderIds=[...new Set(priorLines.map(line=>m2oId(line.order_id)).filter(Boolean))];
        const priorOrders=orderIds.length?await readAll('pos.order',[['id','in',orderIds]],
            ['id','state','config_id'],1000):[];
        return pbCanUsePosPrepickForRepaidSale({snapshot,
            saleLines:saleLines.map(line=>({...line,service:productTypes.get(m2oId(line.product_id))==='service'})),
            priorLines,priorOrders,discountProductId}) && await repaidStockReturned(snapshot,sale,priorLines,priorOrders,discountProductId);
    }
    async function prepareSaleBridge(order, snapshot = posOrderSnapshot(order)) {
        if (snapshot.saleIds.length !== 1 || snapshot.hasUnlinkedLines) throw bridgeError('配货收款只支持一张完整销售单；请分开混合商品或多张销售单。', 'Use una sola venta completa; separe las ventas o productos mezclados.');
        const sourceSale=await readOne('sale.order',snapshot.saleIds[0],['id','name','state','order_line']);
        if(!sourceSale)throw bridgeError('无法读取来源销售单，请检查权限或重新打开原单。','No se pudo leer la venta de origen; revise los permisos o vuelva a abrirla.');
        if(['draft','sent'].includes(sourceSale.state))throw bridgeError(
            `${sourceSale.name} 仍是未确认报价单，尚不能按销售交货单核对数量。请先在后台确认该报价单，再回原 POS 购物车使用配货收款。`,
            `${sourceSale.name} sigue siendo un presupuesto sin confirmar. Confírmelo antes de comparar la entrega y vuelva al mismo carrito POS.`);
        if(sourceSale.state==='cancel')throw bridgeError('来源销售单已取消，请核对原单；未继续收款。','La venta de origen está cancelada; revísela. No se continuó al cobro.');
        if(sourceSale.state!=='sale')throw bridgeError('来源销售单尚不处于可配货状态，请核对原单。','La venta de origen no está lista para el surtido; revísela.');
        // The existing paid-bridge branch below remains readable without treating it as a new payment.
        const prior = await findPrepickByUuid(snapshot.uuid);
        if (prior && !bridgePayload(prior)) throw bridgeError('此 POS 已有独立配货任务，请先核对，不能自动合并两份进度。', 'Este POS ya tiene otro surtido; no se combinarán los avances automáticamente.');
        if(prior && paidBridge(prior)){
            const saved=bridgePayload(prior);
            if(saved.saleId!==snapshot.saleIds[0])throw bridgeError('已付款 POS 的销售来源发生变化，请核对。','Cambió la venta de origen del POS pagado.');
            assertBridgeQuantity(snapshot.lines,saved.sourceMoves);
            return prior;
        }
        // Preparing a picking task never guards or submits native payment.
        rememberPrepickMarker(snapshot.uuid, { paymentRequired: true });
        const saleId = snapshot.saleIds[0];
        await discoverFields();
        const rows = await loadSalesRows(saleId);
        if(!rows.some(row=>!['done','cancel'].includes(row.picking.state)))throw bridgeError(
            '来源销售单没有可用的待发交货单。请核对交货单是否已完成、取消或不可读取；未将此情况当作商品数量差异。',
            'La venta no tiene una entrega pendiente disponible. Revise si está completada, cancelada o no es accesible; no se trata como una diferencia de cantidades.');
        const candidates = [];
        for (const row of rows.filter(r => !['done','cancel'].includes(r.picking.state))) {
            await assertTaskListed(row);
            const detail = await readDeliveryTaskSnapshot(row);
            await publishLoadedTaskStatus(detail);
            try { assertBridgeQuantity(snapshot.lines, detail.moves); candidates.push(detail); } catch (error) { if (error.code !== 'FULFILLMENT_BRIDGE') throw error; }
        }
        if (candidates.length !== 1) throw bridgeError(candidates.length > 1
            ? '有多张交货单与 POS 实物商品相符，无法自动确定，请核对所选交货单。'
            : 'POS 实物商品与待发交货单的应配数量不一致。未配齐不影响付款；请核对销售单修改后是否已重新导入 POS。',
            candidates.length > 1 ? 'Varias entregas coinciden con los productos del POS; revise la entrega seleccionada.'
            : 'Los productos físicos del POS no coinciden con las cantidades solicitadas de la entrega. No es necesario terminar el surtido para pagar; revise los cambios y vuelva a importar la venta.');
        const detail = candidates[0], sourceId = detail.picking.id;
        if(prior && bridgePayload(prior)?.sourcePickingId!==sourceId)throw bridgeError('此 POS 已关联另一张销售交货单，请打开原配货任务核对。','Este POS ya está vinculado a otra entrega; revise el surtido original.');
        if (saleChanged(detail) || detail.tech.validation)
            throw bridgeError('配货任务有待确认变更或验收问题，请先处理后收款。', 'Resuelva los cambios o problemas pendientes del surtido antes de cobrar.');
        const existing = await bridgeForSource(sourceId);
        if (existing && existing.x_pb_order_uuid !== snapshot.uuid) throw bridgeError('这张销售单已关联另一张 POS 单，请打开原 POS 单继续。', 'Esta venta ya está vinculada a otro POS; continúe en el original.');
        if (existing && paidBridge(existing)) return existing;
        const config = await readOne('pos.config', snapshot.configId, ['picking_type_id']);
        const types=await searchRead('stock.picking.type',[['id','in',[m2oId(config?.picking_type_id),m2oId(detail.picking.picking_type_id)]]],['id','warehouse_id','default_location_src_id'],{limit:2});
        const posType=types.find(t=>t.id===m2oId(config?.picking_type_id)),saleType=types.find(t=>t.id===m2oId(detail.picking.picking_type_id));
        if(!posType||!saleType||!m2oId(posType.warehouse_id)||m2oId(posType.warehouse_id)!==m2oId(saleType.warehouse_id)||m2oId(posType.default_location_src_id)!==m2oId(detail.picking.location_id))throw bridgeError('此 POS 发货仓库与销售交货单不同。', 'Este POS utiliza otro almacén de entrega.');
        const enrollment = await searchRead(SHARED_EVENT_MODEL, [['x_pb_operation','=',SALES_QUEUE_OPERATION],['x_pb_picking_id','=',sourceId]], ['id'], {limit:2});
        if (!enrollment.length) await rpc(SHARED_EVENT_MODEL, 'create', [{x_name:`sales-register:${sourceId}`,x_pb_picking_id:sourceId,x_pb_operation:SALES_QUEUE_OPERATION,x_pb_status:'done',x_pb_payload:JSON.stringify({op:{scope:'sales_queue',type:'add',id:`sales-register:${sourceId}`},version:VERSION})}]);
        const data = {schema:1,saleId,sourcePickingId:sourceId,sourceName:detail.picking.name,sourceMoves:detail.moves,saleProof:await bridgeSaleProof(saleId),sourceBaseline:Core.quantityBaseline(detail.moves),posFingerprint:snapshot.fingerprint,preparedAt:new Date().toISOString()};
        const values = {x_name:detail.row.order.name,x_pb_order_uuid:snapshot.uuid,x_pb_picking_id:sourceId,x_pb_state:'bridge_wait',x_pb_lines:JSON.stringify(snapshot.lines),x_pb_payload:JSON.stringify({fulfillmentBridge:data}),x_pb_config_id:snapshot.configId,x_pb_session_id:snapshot.sessionId,x_pb_customer:snapshot.customer,x_pb_amount:snapshot.amount,x_pb_requested_by:snapshot.requestedBy,x_pb_requested_at:Core.odooDateTime(data.preparedAt),x_pb_version:Number(existing?.x_pb_version||0)+1};
        let record;
        if (existing) { await rpc(PREPICK_MODEL,'write',[[existing.id],values]); record={...existing,...values}; }
        else {
            try { const id=await rpc(PREPICK_MODEL,'create',[values]);record=await readOne(PREPICK_MODEL,Number(id),PREPICK_FIELDS); }
            catch (error) { record=await findPrepickByUuid(snapshot.uuid);if(!record||!bridgePayload(record))throw error; }
        }
        // The second read detects simultaneous creation instead of silently choosing a task.
        await bridgeForSource(sourceId);
        await ensureBridgeEnrollment(record);
        rememberPrepickMarker(snapshot.uuid,{requestId:record.id,state:record.x_pb_state,fingerprint:snapshot.fingerprint,sourcePickingId:sourceId});
        prepickSaved();
        return record;
    }
    // A paid POS may cancel its sale delivery. That historical move stops
    // changing, while the sale line can still be edited on another terminal.
    async function bridgeSaleProof(saleId) {
        const sale = await readOne('sale.order',saleId,['state','warehouse_id','company_id','partner_id']);
        if (!sale) throw bridgeError('无法读取来源销售单。','No se pudo leer la venta de origen.');
        const lines = await readAll('sale.order.line',[['order_id','=',saleId],['display_type','=',false]],
            ['product_id','product_uom_qty','product_uom_id']);
        const ids = [...new Set(lines.map(l=>m2oId(l.product_id)).filter(Boolean))];
        const products = ids.length ? await readAll('product.product',[['id','in',ids]],['type']) : [];
        const types = new Map(products.map(p=>[p.id,p.type]));
        if (ids.some(id=>!types.has(id))) throw bridgeError('部分来源商品无法读取。','Faltan productos de la venta de origen.');
        const goods = lines.filter(l=>types.has(m2oId(l.product_id)) && types.get(m2oId(l.product_id))!=='service')
            .map(l=>[l.id,m2oId(l.product_id),m2oId(l.product_uom_id),Number(l.product_uom_qty)]).sort((a,b)=>a[0]-b[0]);
        return {state:sale.state,warehouse:m2oId(sale.warehouse_id),company:m2oId(sale.company_id),customer:m2oId(sale.partner_id),goods};
    }
    async function assertPaidSaleProof(data, sourcePicking, currentMoves, posLines) {
        const proof = await bridgeSaleProof(data.saleId);
        const stale = () => bridgeError('付款已完成，来源销售单与配货记录不再一致。请比较销售单、已付款 POS 和原生交货单，按实物处理；请勿再次收款。',
            'Pago completado. Cambió la venta de origen. Compare la venta, el POS pagado y la entrega en Odoo antes de continuar. No vuelva a cobrar.');
        if (proof.state!=='sale') throw stale();
        if (data.saleProof) {
            if (JSON.stringify(data.saleProof)!==JSON.stringify(proof)) throw stale();
            return;
        }
        // A legacy bridge has no frozen sale. Accept only a fully provable,
        // single-sale match in native sale-line units; ambiguous splits need review.
        const original = new Map(data.sourceMoves.map(m=>[m.id,m]));
        const paidLines = new Set(posLines.map(l=>m2oId(l.sale_order_line_id)).filter(Boolean));
        const sums = new Map();
        for (const live of currentMoves) {
            const old = original.get(live.id), line = m2oId(live.sale_line_id);
            if (!old || !line || !paidLines.has(line)) throw stale();
            const key = [line,m2oId(old.product_id),m2oId(old.product_uom)].join(':');
            sums.set(key,(sums.get(key)||0)+Core.demandOf(old));
        }
        if (sums.size!==proof.goods.length || proof.goods.some(([line,p,u,n])=>sums.get([line,p,u].join(':'))!==n)) throw stale();
        const type=await readOne('stock.picking.type',m2oId(sourcePicking.picking_type_id),['warehouse_id']);
        if (!type || m2oId(type.warehouse_id)!==proof.warehouse ||
            currentMoves.some(m=>m2oId(m.company_id)!==proof.company) || m2oId(sourcePicking.partner_id)!==proof.customer) throw stale();
    }
    async function resolveSaleBridge(record, sourcePicking, currentMoves) {
        const data = bridgePayload(record);
        if (!data || data.sourcePickingId !== sourcePicking.id) throw bridgeError('销售配货关联校验失败。', 'No se pudo verificar el vínculo de surtido.');
        const orders = await searchRead('pos.order', [['uuid','=',record.x_pb_order_uuid]], ['id','uuid','name','pos_reference','state','shipping_date','picking_ids'], {limit:2});
        if (orders.length > 1) throw bridgeError('发现重复 POS 编号，请核对。', 'Se encontró un identificador POS duplicado.');
        const posOrder = orders[0];
        if (!posPaymentConfirmed(posOrder)) {
            if (paidBridge(record)) throw bridgeError('已关联的付款状态发生变化，请核对原单。', 'Cambió el estado del pago vinculado.');
            return {record,data,paid:false};
        }
        if (!posOrder.shipping_date) throw bridgeError('POS 未使用稍后发运，请核对实际库存，不自动再次出库。', 'El POS no tiene envío posterior; revise el inventario antes de continuar.');
        const liveById = new Map(currentMoves.map(m => [m.id, m]));
        if (m2oId(sourcePicking.sale_id) !== data.saleId ||
            !Array.isArray(data.sourceMoves) || data.sourceMoves.length !== liveById.size ||
            data.sourceMoves.some(saved => {
                const live = liveById.get(saved.id);
                return !live || m2oId(saved.product_id) !== m2oId(live.product_id) ||
                    Core.demandOf(saved) !== Core.demandOf(live) ||
                    !Core.compatibleProvenance(Core.moveProvenance(saved),Core.moveProvenance(live));
            })) {
            throw bridgeError('付款已完成，来源交货明细已变。请打开销售单和已付款 POS 的交货记录逐行核对，再到原生交货单处理。',
                'Pago completado. Cambiaron las líneas de origen. Compare las entregas de la venta y del POS pagado y continúe en la entrega original de Odoo.');
        }
        const lines = await readAll('pos.order.line', [['order_id','=',posOrder.id]], ['product_id','qty','sale_order_origin_id','sale_order_line_id'],1000);
        if (lines.some(l=>m2oId(l.sale_order_origin_id)!==data.saleId)) throw bridgeError('POS 来源销售单不一致。', 'No coincide la venta de origen del POS.');
        await assertPaidSaleProof(data,sourcePicking,currentMoves,lines);
        assertBridgeQuantity(await paidBridgeGoodsLines(lines),data.sourceMoves);
        const picks = await searchRead('stock.picking',[['pos_order_id','=',posOrder.id],['picking_type_code','=','outgoing'],['state','!=','cancel']],['id','name','state','date_done','location_id','picking_type_id'],{limit:100});
        if (picks.length !== 1) throw bridgeError('付款已完成，但交货单尚未唯一确定，请同步后核对。不要再次付款。', 'Pago completado; la entrega aún no es única. Sincronice y revise. No vuelva a pagar.');
        const target=picks[0];
        const nativeMoves=await readAll('stock.move',[['picking_id','=',target.id],['state','!=','cancel']],['id','product_id','product_uom_qty','quantity','picked','product_uom','has_tracking','state'],1000);
        assertBridgeNative(sourcePicking,target,data.sourceMoves,nativeMoves);
        const originalState=sourcePicking.state;
        if (originalState === 'done' && target.state !== 'done') throw bridgeError('原销售交货单已经出库，已阻止再次出库。请核对库存记录。', 'La entrega original ya salió; se bloqueó una segunda salida.');
        return {record,data,paid:true,posOrder,target,nativeMoves,moves:data.sourceMoves.map(m=>({...m})),originalState};
    }
    async function publishBridgeStatus(bridge, tech, moves) {
        if (!bridge?.paid) return;
        const status=bridge.target.state==='done'?'done':bridge.target.state==='cancel'?'cancelled':Core.statusFor(tech,moves,'assigned','paid');
        const next=`bridge_${status}`;
        if (bridge.record.x_pb_state!==next || m2oId(bridge.record.x_pb_pos_order_id)!==bridge.posOrder.id) {
            await rpc(PREPICK_MODEL,'write',[[bridge.record.id],{x_pb_state:next,x_pb_pos_order_id:bridge.posOrder.id}]);
            bridge.record={...bridge.record,x_pb_state:next,x_pb_pos_order_id:bridge.posOrder.id};salesQueueEpoch++;
        }
    }
    async function openSharedPosTask(order=currentPosOrder()) {
        const snapshot=posOrderSnapshot(order);
        const saved=snapshot.saleIds.length?await findPrepickByUuid(snapshot.uuid):null;
        const record=snapshot.saleIds.length && (bridgePayload(saved) ||
            (!saved && !(await pbUsePosPrepickForRepaidSale(snapshot)))) ?
            await prepareSaleBridge(order,snapshot) : saved;
        if (!record) return sendPrepickFromButton();
        const row=bridgePayload(record)?await sourceRowForBridge(record):prepickRow(record);
        state.open=true;state.orderSource=isSale(row)?'sale':'pos';state.rows=[...state.rows.filter(r=>r.key!==row.key),row];
        await openOrder(row.key);
    }
    function packingConfirmed(detail=state.detail) {
        const value=detail?.tech?.packingConfirmation;
        return Boolean(value && !detail.tech.unknownScans?.length && value.revision===Core.quantityRevision(detail.tech) && value.baseline===Core.quantityBaseline(detail.moves) && Core.canFinalize(detail.tech,detail.moves));
    }
    async function confirmPacked() {
        const prior=state.detail;
        if(!prior||!state.session)return toast(t('bulkStartFirst'),'warn');
        await state.mutationQueue;
        await withDeviceMutationLock(prior.picking.id,async()=>{
            const fresh=await loadDetail(prior.row);
            if(state.detail?.picking.id!==prior.picking.id)throw bridgeError('页面已切换，请重试。','Cambió la página; inténtelo de nuevo.');
            assertWritableDetail(fresh);
            if(fresh.request?.x_pb_change_pending||saleChanged(fresh)||fresh.tech.unknownScans?.length||!Core.canFinalize(fresh.tech,fresh.moves))throw bridgeError('请先处理数量差异和异常，再确认配齐。','Resuelva las diferencias y excepciones antes de confirmar.');
            if(packingConfirmed(fresh))return;
            const op={id:Core.makeId('packed'),scope:'packing_confirm',type:'confirm',pickingId:fresh.picking.id,revision:Core.quantityRevision(fresh.tech),baseline:Core.quantityBaseline(fresh.moves)};
            await createSharedEvent(op,fresh,state.session);state.detail=fresh;
            await syncSharedState({expectedEventId:op.id,writeAggregate:true});render();
            toast(state.lang==='es'?'Surtido confirmado. Valide la salida al entregar la mercancía.':'已确认配齐。实际交货时再验收出库。','ok');
        });
    }

    const CUSTOMER_ADDRESS_FIELDS=['street','street2','city','zip','state_id','country_id'];
    const addressComplete=p=>Boolean(p?.street && p?.city && m2oId(p?.country_id));
    const addressEmpty=p=>CUSTOMER_ADDRESS_FIELDS.every(f=>!p?.[f] || typeof p[f]==='string'&&!p[f].trim());
    const localShipDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
    function validShipDate(value) {
        if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;
        const d=new Date(value+'T12:00:00');return !isNaN(d)&&`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`===value;
    }


    // Sales use the native delivery identity. No quotation or internal transfer is created.
    const isSale = detail => taskSource(detail) === 'sale';
    // Sales share the canonical lock and native target proof at both entrances.
    // Both entrances use the same stock-out guard; the task source decides payment rules.
    const canValidateHere = (detail = state.detail) => Boolean(detail);
    function baselineMoves(tech) {
        return Object.entries(tech?.baseline || {}).map(([id, b]) => ({...b.identity,id:Number(id), product_id:Number(b.productId), product_uom_qty:Number(b.demand)}));
    }
    function saleChanged(detail) {
        return isSale(detail) && !Core.assertBaseline(detail.tech, detail.moves).ok;
    }
    function salesTech(picking, moves) {
        const raw = Core.safeParse(picking?.[state.fieldMap.tech]);
        const tech = Core.hydrateTech(raw, raw?.schema === 1 ? baselineMoves(raw) : moves);
        tech.salesReview = true;
        if (tech.eventSync?.baseTech) tech.eventSync.baseTech.salesReview = true;
        return tech;
    }
    async function readAll(model, domain, fields, pageSize=500, readOptions) {
        const rows = [];
        let after = 0;
        for (;;) {
            throwIfReadCancelled(readOptions);
            const batch = await searchRead(model, [...domain, ['id','>',after]], fields, {order:'id',limit:pageSize}, readOptions);
            rows.push(...batch);
            if (batch.length < pageSize) return rows;
            const next = batch[batch.length-1].id;
            if (next <= after) throw new Error('Pagination did not advance');
            after = next;
        }
    }
    // Bound concurrency; never truncate older unfinished deliveries.
    async function readSalesBatches(model, ids, field, fields, extraDomain=[]) {
        const chunks=[];
        for(let i=0;i<ids.length;i+=1000)chunks.push(ids.slice(i,i+1000));
        const result=new Array(chunks.length);let next=0;
        await Promise.all(Array.from({length:Math.min(4,chunks.length)},async()=>{
            for(;;){const index=next++;if(index>=chunks.length)return;
                result[index]=await readAll(model,[[field,'in',chunks[index]],...extraDomain],fields,2000);
            }
        }));
        return result.flat();
    }


    function salesTechFingerprint(tech) {
        // Replaying immutable events creates fresh audit IDs. Those IDs are not
        // a quantity or workflow change and must not cause writes/repaints.
        return JSON.stringify([sharedStateFingerprint(tech),tech?.baseline,
            tech?.packingConfirmation,tech?.salesReview,tech?.eventSync?.baseEventId]);
    }
    function salesViewFingerprint(detail) {
        return JSON.stringify([salesTechFingerprint(detail.tech),detail.moves,
            detail.picking.state,detail.salesCancelAck,detail.products,[...(detail.stock || [])],
            detail.bridge?.paid,detail.bridge?.record?.id,detail.bridge?.record?.x_pb_state,
            detail.bridge?.posOrder?.id,detail.bridge?.posOrder?.state,detail.bridge?.target?.id,detail.bridge?.target?.state,
            detail.request?.x_pb_change_pending,detail.request?.x_pb_state]);
    }
    async function syncSalesDetail(options={}) {
        const prior=state.detail;
        const fresh=await loadDetail(prior.row, { catalog: options.manual ? null : prior });
        if(state.detail?.picking.id!==prior.picking.id)return {stale:true};
        if(options.expectedEventId && (!fresh.sharedEvents.some(e=>Core.normalizeSharedEvent(e).name===options.expectedEventId) || fresh.tech.eventSync?.rejectedEvents?.some(e=>e.id===options.expectedEventId))) throw Object.assign(new Error(t('saleStale')), {code:'ORDER_CHANGED'});
        if(options.writeAggregate!==false && salesTechFingerprint(fresh.tech)!==salesTechFingerprint(fresh.storedTech) && !['done','cancel'].includes(fresh.picking.state) && !saleChanged(fresh) && Core.isSharedMode(fresh.tech)) await writeTech(fresh,fresh.tech,fresh.moves);
        if(state.detail?.picking.id!==prior.picking.id)return {stale:true};
        state.detail=fresh;
        if(isReadOnlyDetail(fresh)) enterReadOnlyDetail(fresh);
        state.lastSharedPullAt=Date.now();
        state.saveError='';
        const changed=salesViewFingerprint(prior)!==salesViewFingerprint(fresh);
        if(options.renderView!==false && (changed||options.manual)) {
            if (options.manual) render(); else renderQuantityFeedback();
        }
        return {changed,tech:fresh.tech,events:fresh.sharedEvents};
    }
    async function confirmSalesChange(confirmed=false, expectedMoves=null) {
        const prior=state.detail;
        if(!isSale(prior)||!state.session)return toast(t('bulkStartFirst'),'warn');
        const target=Core.saleRevision(prior.moves);
        const token=state.session.token;
        if(expectedMoves && expectedMoves!==target)throw Object.assign(new Error(t('saleStale')),{code:'ORDER_CHANGED'});
        if(!confirmed && !await showPrompt(t('changedHelp'),'confirm',{title:t('orderChanged'),confirmLabel:t('confirmChange')}))return;
        await withDeviceMutationLock(prior.picking.id,async()=>{
            const fresh=await loadDetail(prior.row);
            if(state.detail?.picking.id!==prior.picking.id || state.session?.token!==token)throw Object.assign(new Error(t('saleStale')),{code:'ORDER_CHANGED'});
            if(Core.saleRevision(fresh.moves)!==target || isReadOnlyDetail(fresh)){state.detail=fresh;render();throw Object.assign(new Error(t('saleStale')),{code:'ORDER_CHANGED'});}
            if(!saleChanged(fresh)) {state.detail=fresh;render();return;}
            const op={id:Core.makeId('review'),scope:'sales_review',type:'confirm',allocation:'move-v1',pickingId:fresh.picking.id,expectedBaseline:Core.quantityBaseline(baselineMoves(fresh.tech)),moves:fresh.moves.map(m=>({...Core.moveProvenance(m),id:m.id,product_id:m2oId(m.product_id),product_uom_qty:Core.demandOf(m)}))};
            await createSharedEvent(op,fresh,state.session);
            state.detail=fresh;
            await syncSharedState({expectedEventId:op.id,writeAggregate:true});
            state.quantityDraftBases.clear(); state.quantityDrafts.clear();state.lastAction=null;saveUndoRecord(fresh.picking.id,null);render();
        });
    }
    async function acknowledgeSalesCancellation() {
        const prior=state.detail;
        if(!isSale(prior)||prior.picking.state!=='cancel')return;
        const op={id:Core.makeId('cancel_ack'),scope:'sales_cancel_ack',type:'ack',pickingId:prior.picking.id};
        await createSharedEvent(op,prior,{picker:currentPicker(),deviceId});
        const fresh=await loadDetail(prior.row);
        if(state.detail?.picking.id!==prior.picking.id)return;
        state.detail=fresh;state.saveError="";state.lastSharedPullAt=Date.now();render();
    }
    function salesFilters() {
        if(state.orderSource!=='sale')return '';
        const people=new Map([...(state.salesFacets?.people || []), ...state.rows.filter(isSale).map(r=>[String(m2oId(r.order.user_id)||0),r.order.user_id?.[1]||t('unassigned')])]);
        return `<label><span>${t('salesperson')}</span><select id="pbful-salesperson"><option value="all">${t('allSalespeople')}</option>${[...people].sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>`<option value="${id}" ${state.salesperson===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
    }

    function salesChangeSummary(d) {
        const before = new Map(baselineMoves(d.tech).map(m => [m.id,m])), after = new Map(d.moves.map(m => [m.id,m]));
        const label = move => {
            const id = m2oId(move?.product_id), p = d.products.find(p => p.id === id);
            return p ? [p.default_code, p.display_name].filter(Boolean).join(' · ') : String(id);
        };
        return [...new Set([...before.keys(), ...after.keys()])].filter(id => !before.has(id) || !after.has(id) || m2oId(before.get(id).product_id) !== m2oId(after.get(id).product_id) || Core.demandOf(before.get(id)) !== Core.demandOf(after.get(id))).map(id => {
            const a = before.get(id), b = after.get(id);
            if (a && b && m2oId(a.product_id) !== m2oId(b.product_id)) return `${label(a)}: ${Core.demandOf(a)} → 0\n${label(b)}: 0 → ${Core.demandOf(b)}`;
            return `${label(b || a)}: ${a ? Core.demandOf(a) : 0} → ${b ? Core.demandOf(b) : 0}`;
        }).join('\n');
    }
    function noticeKey(d, act) { return `${d.picking.id}:${act}`; }
    function noticeButton(d, act, label, attributes = '') {
        return `<button data-act="${act}" data-notice-picking="${d.picking.id}" ${attributes} ${state.noticePending?.has(noticeKey(d,act)) || (act === 'confirm-change' && state.confirmingRequestId) ? 'disabled' : ''}>${esc(label)}</button>`;
    }
    function noticeError(d, act) {
        const error = state.noticeErrors?.get(noticeKey(d,act));
        return error ? `<p class="pbful-notice-error" role="alert">${esc(error)}</p>` : '';
    }
    function cancellationBanner(d, act) {
        const acknowledged = d.request ? d.request.x_pb_cancel_ack : d.salesCancelAck;
        const label = state.lang === 'es' ? 'Canasta retirada' : '已处理配货篮';
        return `<section class="pbful-critical-banner cancelled" role="status"><div><strong>${acknowledged ? t('cancelled') + ' · ' + t('readOnly') : t('orderCancelledNotice')}</strong>${acknowledged ? '' : `<p>${t('readOnly')}</p>`}${noticeError(d,act)}</div>${acknowledged ? '' : noticeButton(d,act,label)}${!d.request ? `<button data-native="${d.picking.id}">${t('native')}</button>` : ''}</section>`;
    }
    async function runNoticeAction(button, action) {
        const detail = state.detail;
        if (!detail || Number(button.dataset.noticePicking) !== detail.picking.id) return;
        const key = noticeKey(detail, button.dataset.act);
        state.noticePending ||= new Set(); state.noticeErrors ||= new Map();
        if (state.noticePending.has(key)) return;
        state.noticePending.add(key); state.noticeErrors.delete(key); button.disabled = true;
        render();
        try { await action(); }
        catch (error) { state.noticeErrors.set(key, error.message || String(error)); }
        finally { state.noticePending.delete(key); if (state.detail?.picking.id === detail.picking.id) render(); }
    }

    function saleBanner(d) {
        if(!isSale(d))return '';
        const meta=`<div class="pbful-sale-meta">${t('salesOrders')} · ${esc(d.row.order.name)} · ${t('salesperson')}：${esc(d.row.order.user_id?.[1]||t('unassigned'))}</div>`;
        if(d.picking.state==='cancel')return meta+(d.salesCancelAck?'':cancellationBanner(d,'sale-cancel-ack'));
        if(saleChanged(d)&&d.picking.state!=='done')return meta+`<section class="pbful-critical-banner changed" role="status"><div><strong>${t('orderChanged')}</strong><p>${t('saleStale')}</p><pre>${esc(salesChangeSummary(d))}</pre>${noticeError(d,'sale-confirm')}</div>${noticeButton(d,'sale-confirm',t('confirmChange'),`data-sales-baseline="${esc(Core.saleRevision(d.moves))}"`)}</section>`;
        return meta;
    }

    // Explicit enrollment lives in the existing shared event model, on the server.
    // Grouping by native picking makes concurrent registrations one visible task.
    const SALES_QUEUE_OPERATION = 'sales_queue:add';
    const salesEnrollmentLocks = new Map();
    let salesQueueEpoch = 0;

    function salesQueryKey() {
        return JSON.stringify([state.tab, state.salesperson, state.warehouse,
            String(state.search || '').trim(), Number(state.days), state.sort]);
    }
    function salesRequestKey() {
        const query = salesQueryKey();
        if (state.salesPageQuery !== query) {
            state.salesPageQuery = query; state.dashboardPageNumber = 1;
        }
        return `${query}:${Math.max(1, Number(state.dashboardPageNumber) || 1)}:${salesQueueEpoch}`;
    }
    function nativeSalesQueueDomain(status = null) {
        const p = 'x_pb_picking_id.';
        const domain = [['x_pb_operation', '=', SALES_QUEUE_OPERATION], ['x_pb_picking_id', '!=', false],
            [p + 'sale_id.state', 'in', ['sale', 'cancel']], [p + 'pos_order_id', '=', false],
            [p + 'picking_type_code', '=', 'outgoing']];
        const hidden=hiddenSalePickingIds();if(hidden.length)domain.push(['x_pb_picking_id','not in',hidden]);
        if (state.salesperson !== 'all') domain.push([p + 'sale_id.user_id', '=', Number(state.salesperson) || false]);
        if (state.warehouse && state.warehouse !== '__all__') domain.push([p + 'picking_type_id', '=', Number(state.warehouse)]);
        const q = String(state.search || '').trim();
        if (q) {
            const fields = ['sale_id.name', 'sale_id.client_order_ref', 'sale_id.user_id.name', 'name', 'sale_id.partner_id.name', state.fieldMap.picker].filter(Boolean);
            domain.push(...Array(fields.length - 1).fill('|'), ...fields.map(field => [p + field, 'ilike', q]));
        }
        const active = [[p + 'state', 'not in', ['done', 'cancel']], [p + 'sale_id.state', '=', 'sale']];
        const cancelled = ['|', [p + 'state', '=', 'cancel'], [p + 'sale_id.state', '=', 'cancel']];
        const done = [[p + 'state', '=', 'done'], [p + 'sale_id.state', '!=', 'cancel']];
        if (Number(state.days) > 0) {
            const cutoff = Core.odooDateTime(new Date(Date.now() - Number(state.days) * 86400000).toISOString());
            domain.push('|', '|', '&', ...active, '&', '&', ...done, [p + 'date_done', '>=', cutoff], '&', ...cancelled, [p + 'write_date', '>=', cutoff]);
        }
        if (status === 'cancelled') domain.push(...cancelled);
        else if (status === 'done') domain.push(...done);
        else if (status) {
            domain.push(...active);
            const f = state.fieldMap;
            if (status === 'pending') domain.push([p + f.status, 'not in', ['picking', 'ready', 'exception'].map(s => f.statusValue[s]).filter(v => v != null)]);
            else domain.push([p + f.status, '=', f.statusValue[status]]);
        }
        return domain;
    }
    function andDomain(...domains) {
        const tokens=domains.flat(), expressions=[];let i=0;
        const take=()=>{const t=tokens[i++];if(t==='|'||t==='&')return [t,...take(),...take()];if(t==='!')return [t,...take()];return [t];};
        while(i<tokens.length)expressions.push(take());
        return [...Array(Math.max(0,expressions.length-1)).fill('&'),...expressions.flat()];
    }
    function salesQueueDomain(status=null) {
        const p='x_pb_picking_id.';
        return andDomain(nativeSalesQueueDomain(status), [[p+'state','!=','cancel'],[p+'sale_id.state','!=','cancel']]);
    }

    async function salesGrouped(domain, groupby, aggregates, options = {}, readOptions) {
        return rpc(SHARED_EVENT_MODEL, 'formatted_read_group', [], {domain, groupby, aggregates, ...options}, readOptions);
    }
    async function salesQueueCount(domain, readOptions) {
        const groups = await salesGrouped(domain, [], ['x_pb_picking_id:count_distinct'], {}, readOptions);
        return Number(groups[0]?.['x_pb_picking_id:count_distinct'] || 0);
    }
    async function loadSalesFacets(readOptions) {
        if (state.salesFacets && Date.now() - state.salesFacets.at < 300000) return;
        // Small master-data lists; never discover filter choices by fetching order history.
        const [users, types] = await Promise.all([
            searchRead('res.users', [['share', '=', false]], ['id', 'name'], {limit: 500, order: 'name', context: {active_test: false}}, readOptions),
            searchRead('stock.picking.type', [['code', '=', 'outgoing']], ['id', 'display_name'], {limit: 500, order: 'id', context: {active_test: false}}, readOptions),
        ]);
        state.salesFacets = {at: Date.now(), people: [['0', t('unassigned')], ...users.map(u => [String(u.id), u.name])],
            warehouses: types.map(p => [String(p.id), p.display_name])};
    }
    async function saleRowsForPickings(ids, readOptions) {
        if (!ids.length) return [];
        const picks = await searchRead('stock.picking', [['id', 'in', ids], ['pos_order_id', '=', false], ['picking_type_code', '=', 'outgoing']], pickingIndexFields(), {limit: ids.length}, readOptions);
        const saleIds = [...new Set(picks.map(p => m2oId(p.sale_id)).filter(Boolean))];
        const orders = saleIds.length ? await searchRead('sale.order', [['id', 'in', saleIds]],
            ['id', 'name', 'state', 'partner_id', 'user_id', 'date_order', 'amount_total', 'client_order_ref', 'warehouse_id'], {limit: saleIds.length}, readOptions) : [];
        const byOrder = new Map(orders.filter(o => ['sale', 'cancel'].includes(o.state)).map(o => [o.id, o]));
        const byPicking = new Map(picks.filter(p => byOrder.has(m2oId(p.sale_id))).map(p => [p.id, pickingSummaryRow(p, byOrder.get(m2oId(p.sale_id)), 'sale')]));
        const visible=ids.map(id=>byPicking.get(id)).filter(row=>row&&row.picking.state!=='cancel'&&row.order.state!=='cancel');
        const summaries = visible.filter(row => row.picking.state === 'done' || m2oId(row.picking.backorder_id));
        const splitIds = summaries.filter(row => row.picking.state !== 'done').map(row => row.picking.id);
        const [moves, techs] = await Promise.all([
            summaries.length ? readAll('stock.move', [['picking_id','in',summaries.map(row => row.picking.id)],['state','!=','cancel']],
                ['id','picking_id','product_id','product_uom_qty','quantity','state'], 1000, readOptions) : [],
            splitIds.length ? searchRead('stock.picking', [['id','in',splitIds]], ['id',state.fieldMap.tech], {limit:splitIds.length}, readOptions) : [],
        ]);
        const byPickingId = new Map();
        for (const move of moves) {
            const id = m2oId(move.picking_id);
            if (!byPickingId.has(id)) byPickingId.set(id, []);
            byPickingId.get(id).push(move);
        }
        const techById = new Map(techs.map(picking => [picking.id, picking[state.fieldMap.tech]]));
        for (const row of summaries) {
            const lines = byPickingId.get(row.picking.id) || [];
            if (row.picking.state === 'done') applyDeliverySummary(row, lines);
            else applyDeliverySummary(row, lines, Core.safeParse(techById.get(row.picking.id)));
        }
        return visible;
    }


    async function loadSalesRows(onlySaleId = 0, readOptions) {
        if (onlySaleId) {
            // This query is scoped to one native sales order and is only used by its button.
            const picks = await readAll('stock.picking', [['sale_id', '=', onlySaleId], ['pos_order_id', '=', false], ['picking_type_code', '=', 'outgoing']], ['id'], 100, readOptions);
            return saleRowsForPickings(picks.map(p => p.id), readOptions);
        }
        const key = salesRequestKey(), requestedPage = state.dashboardPageNumber;
        const selected = String(state.search || '').trim() ? null : state.tab;
        const statuses = ['pending', 'picking', 'ready', 'exception', 'done', 'cancelled'];
        const domains = new Map(statuses.map(s => [s, salesQueueDomain(s)]));
        const domain = salesQueueDomain(selected);
        const [counts] = await Promise.all([
            Promise.all(statuses.map(async s => [s, await salesQueueCount(domains.get(s), readOptions)])), loadSalesFacets(readOptions),
        ]);
        const totals = Object.fromEntries(counts);
        const total = selected ? totals[selected] : Object.values(totals).reduce((a, b) => a + b, 0);
        const page = Math.min(Math.max(1, requestedPage), Math.max(1, Math.ceil(total / 10)));
        const groups = total ? await salesGrouped(domain, ['x_pb_picking_id'], ['id:min'],
            {offset: (page - 1) * 10, limit: 10, order: `id:min ${state.sort === 'oldest' ? 'ASC' : 'DESC'}`}, readOptions) : [];
        const rows = await saleRowsForPickings(groups.map(g => m2oId(g.x_pb_picking_id)).filter(Boolean), readOptions);
        // Notes are loaded only for the returned page; they are not a full-history search index.
        await refreshOrderNotes(rows, readOptions);
        if (state.orderSource !== 'sale' || key !== salesRequestKey()) return null;
        state.dashboardPageNumber = page;
        state.salesPage = {key: salesRequestKey(), page, total, counts: totals};
        return rows;
    }
    async function registerSalePicking(row) {
        const id = row.picking.id;
        if (salesEnrollmentLocks.has(id)) return salesEnrollmentLocks.get(id);
        const task = withDeviceMutationLock(id, async () => {
            const picking = await readOne('stock.picking', id, ['id', 'sale_id', 'pos_order_id', 'picking_type_code', 'state']);
            const sale = picking && await readOne('sale.order', m2oId(picking.sale_id), ['id', 'state']);
            if (!picking || sale?.id !== row.order.id || m2oId(picking.pos_order_id) || picking.picking_type_code !== 'outgoing') throw new Error(t('saleNoDelivery'));
            const domain = [['x_pb_operation', '=', SALES_QUEUE_OPERATION], ['x_pb_picking_id', '=', id]];
            const existing = await searchRead(SHARED_EVENT_MODEL, domain, ['id'], {limit: 1});
            if (!existing.length) {
                if (sale.state !== 'sale' || ['done', 'cancel'].includes(picking.state)) throw new Error(t('saleCannotEnroll'));
                const values = {x_name: `sales-register:${id}`, x_pb_picking_id: id, x_pb_operation: SALES_QUEUE_OPERATION,
                    x_pb_status: 'done', x_pb_payload: JSON.stringify({op: {id: `sales-register:${id}`, scope: 'sales_queue', type: 'add', pickingId: id}, version: VERSION})};
                try { await rpc(SHARED_EVENT_MODEL, 'create', [values]); }
                catch (error) {
                    // A lost response must not turn a successful registration into a duplicate retry.
                    if (!(await searchRead(SHARED_EVENT_MODEL, domain, ['id'], {limit: 1})).length) throw error;
                }
            }
            salesQueueEpoch++;
            const fresh = (await saleRowsForPickings([id]))[0];
            if (!fresh) throw new Error(t('saleNoDelivery'));
            state.rows = [...state.rows.filter(r => r.key !== fresh.key), fresh];
            return fresh;
        });
        salesEnrollmentLocks.set(id, task);
        try { const fresh=await task; await openOrder(fresh.key); return fresh; } finally { salesEnrollmentLocks.delete(id); }
    }
    async function jumpToSale(id) {
        if (state.saleShortcutBusy) return;
        state.saleShortcutBusy = true;
        const button = document.getElementById('pbful-open-sale'); if (button) button.disabled = true;
        try {
            const sale = await readOne('sale.order', id, ['id', 'state', 'name']);
            if (!sale || !['sale', 'cancel'].includes(sale.state)) return showPrompt(t('saleConfirmFirst'), 'info', {title: t('openSalePicking')});
            cancelDetailRead();cancelDashboardRead();
            state.open = true; state.view = 'dashboard'; state.detail=null;state.session=null;state.postpaidMode=false;state.workspacePage='orders';state.orderSource = 'sale';
            state.salesperson = 'all'; state.warehouse = '__all__'; state.search = ''; render();
            await discoverFields();
            const rows = await loadSalesRows(id);
            const enrolled = await searchRead(SHARED_EVENT_MODEL,
                [['x_pb_operation', '=', SALES_QUEUE_OPERATION], ['x_pb_picking_id', 'in', rows.map(r => r.picking.id)]], ['x_pb_picking_id'], {limit: 1000});
            const registered = new Set(enrolled.map(r => m2oId(r.x_pb_picking_id)));
            const choices = rows.filter(r => registered.has(r.picking.id) || (sale.state === 'sale' && !['done', 'cancel'].includes(r.picking.state)));
            if (!choices.length) { state.view = 'dashboard'; render(); return showPrompt(t('saleNoDelivery'), 'warn'); }
            if (choices.length === 1) {
                const row = choices[0];
                if (!registered.has(row.picking.id)) return await registerSalePicking(row);
                // This shortcut just read the source order, outgoing picking and enrollment.
                // openOrder still checks withdrawal and loads the current native documents.
                state.rows = [...state.rows.filter(item => item.key !== row.key), row];
                return await openOrder(row.key);
            }
            state.view = 'dashboard'; render();
            await showPrompt(sale.name, 'info', {title: t('chooseDelivery'), actions: choices.map(row => ({
                label: `${row.picking.name} · ${m2oName(row.picking.picking_type_id)} · ${statusLabel(row.status)} · ${t(registered.has(row.picking.id) ? 'saleOpenExisting' : 'openSalePicking')}`,
                onClick: () => registerSalePicking(row),
            }))});
        } finally {
            state.saleShortcutBusy = false;
            if (button?.isConnected) button.disabled = false;
        }
    }


    function currentSaleId() {
        // Odoo 19 named routes and explicit model routes; never infer IDs from text.
        const path=location.pathname;
        const match=path.match(/\/(?:sales|orders|sale\.order)\/(\d+)(?:\/|$)/);
        if(match)return Number(match[1]);
        const hash=new URLSearchParams(location.hash.replace(/^#/,''));
        return hash.get('model')==='sale.order'?Number(hash.get('id'))||0:0;
    }
    function installSaleShortcut() {
        if(!IS_WORKSPACE)return;
        const update=()=>{
            const id=currentSaleId(), header=document.querySelector('.o_form_view .o_statusbar_buttons');
            let button=document.getElementById('pbful-open-sale');
            if(!id||!header){button?.remove();return;}
            if(!button){button=document.createElement('button');button.id='pbful-open-sale';button.type='button';button.className='btn btn-secondary';button.addEventListener('click',()=>jumpToSale(currentSaleId()).catch(e=>toast(e.message,'error')));header.appendChild(button);}
            if(button.textContent!==t('openSalePicking'))button.textContent=t('openSalePicking');
            button.disabled=Boolean(state.saleShortcutBusy || salesEnrollmentLocks.size);
        };
        let timer;
        new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(update,200);}).observe(document.body,{childList:true,subtree:true});
        window.addEventListener('popstate',update);window.addEventListener('hashchange',update);update();
    }
    // Fulfillment summaries are separate from native quantities/validation.
    // The review path does not receive this repository.
    class FulfillmentMetadataWriter {
        constructor(callRpc, requestModel, summarize) {
            this.callRpc = callRpc; this.requestModel = requestModel; this.summarize = summarize;
        }

        writeRequestTech(requestId, tech) {
            return this.callRpc(this.requestModel, 'write', [[requestId], {x_pb_tech: JSON.stringify(tech)}]);
        }

        writePickingSummary(pickingId, tech, moves) {
            return this.callRpc('stock.picking', 'write', [[Number(pickingId)], this.summarize({...tech, taskPickingId:Number(pickingId)}, moves)]);
        }

        writeCompletionStatus(pickingId, statusField, doneValue) {
            return this.callRpc('stock.picking', 'write', [[pickingId], {[statusField]: doneValue}]);
        }
    }

    const fulfillmentMetadataWriter = new FulfillmentMetadataWriter(rpc, PREPICK_MODEL, summaryValues);

    function techFromPicking(picking, moves) {
        const raw=Core.safeParse(picking?.[state.fieldMap.tech]);
        return Core.hydrateTech(isolateBackorderTech(picking,moves||[],raw), moves || []);
    }
    function summaryValues(tech, moves) {
        const f = state.fieldMap;
        const p = Core.progress(tech, moves);
        const effectiveStatus = tech.exception?.active || Core.extraTotal(tech) > 0 || p.excess > 0 ? Core.STATUS.EXCEPTION : tech.status;
        const statusValue = f.statusValue[effectiveStatus];
        if (statusValue == null) throw new Error(`“配货状态”没有可写入的“${Core.STATUS_LABELS[effectiveStatus] || effectiveStatus}”选项`);
        const values = {
            [f.tech]: JSON.stringify(tech),
            [f.status]: statusValue,
            [f.picker]: tech.picker || false,
            [f.progress]: `${p.scanned}/${p.demand}`,
            [f.started]: Core.odooDateTime(tech.startedAt),
            [f.ready]: Core.odooDateTime(tech.readyAt),
            [f.exception]: tech.exception?.active ? `${tech.exception.reason}${tech.exception.note ? `：${tech.exception.note}` : ""}` : false,
        };
        return values;
    }
    async function writeTech(target, tech, moves) {
        const id = typeof target === 'object' ? target?.picking?.id : target;
        if (target?.review || isReviewId(id)) return; // Event log only. Never write a completed stock transfer.
        if (target?.request) {
            const fresh = await readOne(PREPICK_MODEL, Number(target.request.id), ["id", "x_pb_version", "x_pb_lines", "x_pb_change_pending", "x_pb_state"]);
            if (!fresh || Number(fresh.x_pb_version) !== Number(target.request.x_pb_version) || fresh.x_pb_change_pending || fresh.x_pb_state !== "draft" || Core.draftLineFingerprint(prepickLines(fresh)) !== Core.draftLineFingerprint(prepickLines(target.request))) {
                throw Object.assign(new Error("订单已变更，本次汇总未覆盖新订单；请同步后检查数量"), { code: "REQUEST_CHANGED" });
            }
            await fulfillmentMetadataWriter.writeRequestTech(Number(target.request.id), tech);
            return;
        }
        const pickingId = typeof target === "object" ? target?.picking?.id : target;
        await fulfillmentMetadataWriter.writePickingSummary(pickingId, tech, moves);
        if(target?.bridge?.paid)await publishBridgeStatus(target.bridge,tech,moves);
    }

    function invalidateDashboardIndex() { salesQueueEpoch++; state.posListLoadedAt = 0; state.posListEpoch = Number(state.posListEpoch || 0) + 1; }
    function dashboardRequestScope() {
        return state.orderSource === 'sale' ? salesRequestKey()
            : `pos:${Number(state.days) === 0}:${state.postpaidMode ? 'review' : 'delivery'}${state.postpaidMode ? ':'+JSON.stringify(String(state.search||'').trim()) : ''}`;
    }
    function cancelDashboardRead() {
        const request = state.dashboardRequest;
        if (!request) return;
        request.cancelled = true;
        request.controller?.abort();
        clearTimeout(request.timer);
        state.dashboardRequest = null;
        state.dashboardRefreshing = false; state.loading = false; state.syncing = false;
        invalidateDashboardIndex();
    }
    function throwIfReadCancelled(options) {
        if (options?.cancelled || options?.signal?.aborted) throw Object.assign(new Error('Dashboard read cancelled'), {code:'RPC_READ_CANCELLED'});
    }
    async function readIndexBatches(model, ids, field, fields, domain = [], readOptions) {
        const unique = [...new Set(ids)].filter(Boolean);
        if (!unique.length) return [];
        return readAll(model, [[field, 'in', unique], ...domain], fields, 1000, readOptions);
    }

    function indexHistoryDomain() {
        if (Number(state.days) === 0) return [];
        // Stable day boundary keeps incremental cache keys stable while the UI applies exact dates.
        const cutoff = new Date(); cutoff.setUTCDate(cutoff.getUTCDate() - 31); cutoff.setUTCHours(0, 0, 0, 0);
        return ['|', ['state', 'not in', ['done', 'cancel']], ['write_date', '>=', Core.odooDateTime(cutoff.toISOString())]];
    }

    function pickingIndexFields() {
        const f = state.fieldMap;
        return ['id', 'name', 'state', 'backorder_id', 'sale_id', 'pos_order_id', 'scheduled_date', 'write_date', 'date_done', 'partner_id', 'picking_type_id', 'user_id',
            f.status, f.picker, f.progress, f.started, f.ready, f.legacyPicker].filter(Boolean);
    }

    function isolateBackorderTech(picking,moves,raw) {
        if(!raw || !m2oId(picking.backorder_id))return raw;
        // The replay seed owns the baseline. A copied aggregate can acquire the
        // current outer id during an earlier sync without changing that seed.
        const owner=raw.eventSync?.baseTech ? raw.eventSync.baseTech.taskPickingId : raw.taskPickingId;
        if(owner===picking.id)return raw;
        const baseline=raw.eventSync?.baseTech?.baseline||raw.baseline||{};
        const ids=new Set(moves.map(m=>String(m.id)));
        const copied=owner ? owner!==picking.id : Object.keys(baseline).length>0&&!Object.keys(baseline).some(id=>ids.has(id));
        if(!copied)return raw;
        const seed=Core.createTech(moves);seed.taskPickingId=picking.id;
        seed.audit.push({id:Core.makeId('split'),event:'backorder_task_isolated',sourcePickingId:m2oId(picking.backorder_id),at:new Date().toISOString()});
        return Core.enableSharedMode(seed,moves);
    }
    // Both sales and POS lists project the same actual-delivery rules. Native
    // reserved quantities never become scan counts for an unfinished delivery.
    function applyDeliverySummary(row, moves, rawTech) {
        if (row.picking.state === 'done') {
            const delivered = moves.reduce((sum, move) => sum + Number(move.quantity || 0), 0);
            row.progress = { scanned: delivered, demand: delivered, excess: 0 };
        } else if (m2oId(row.picking.backorder_id)) {
            const isolated = isolateBackorderTech(row.picking, moves, rawTech);
            if (!rawTech || isolated !== rawTech) {
                row.progress = Core.progress(isolated || Core.createTech(moves), moves);
                row.status = Core.STATUS.PENDING;
                row.responsible = { name: '', source: 'none' };
            }
        }
        return row;
    }

    function pickingSummaryRow(picking, order, kind) {
        const f = state.fieldMap;
        const savedStatus = Object.entries(f.statusValue || {}).find(([, value]) => value != null && value === picking?.[f.status])?.[0];
        const status = picking?.state === 'cancel' || order.state === 'cancel' ? Core.STATUS.CANCELLED
            : picking?.state === 'done' ? Core.STATUS.DONE : !picking ? Core.STATUS.EXCEPTION
            : [Core.STATUS.PICKING, Core.STATUS.READY, Core.STATUS.EXCEPTION].includes(savedStatus) ? savedStatus : Core.STATUS.PENDING;
        const match = String(picking?.[f.progress] || '').match(/^(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)$/);
        // Missing aggregates are unknown, not zero quantities. Native reservations are never scan counts.
        const progress = { scanned: match ? Number(match[1]) : null, demand: match ? Number(match[2]) : null, excess: 0 };
        return { key: deliveryTaskKey(kind, kind === 'sale' ? picking.id : picking?.id, order.id), kind, picking, order,
            moves: [], tech: {}, progress, status, responsible: picking ? effectivePicker(picking, null) : { name: '', source: 'none' },
            paymentNames: [], summaryOnly: true };
    }



    async function readCompletedDeliveryTotals(ids,readOptions) {
        if(!ids.length)return [];
        const groups=await rpc('stock.move','formatted_read_group',[],{
            domain:[['picking_id','in',ids],['state','=','done']],groupby:['picking_id'],aggregates:['quantity:sum'],limit:ids.length+1},readOptions);
        const seen=new Set(),allowed=new Set(ids);
        return groups.map(group=>{
            const id=m2oId(group.picking_id),quantity=Number(group['quantity:sum']??group.quantity);
            if(!allowed.has(id)||seen.has(id)||!Number.isFinite(quantity))throw new Error('DELIVERY_TOTAL_UNVERIFIED');
            seen.add(id);return {picking_id:id,quantity};
        });
    }
    async function loadPosIndexRows(orderUuids=null, readOptions) {
        const postpaidMode = readOptions?.postpaidMode ?? Boolean(state.postpaidMode);
        const reviewIds=postpaidMode?await reviewTaskPickingIds(readOptions):[];
        const registrations=postpaidMode?[]:await searchRead(PREPICK_MODEL,[['x_pb_state','not in',['cancelled','bridge_detached']]],
            ['id','x_pb_pos_order_id','x_pb_picking_id','x_pb_order_uuid','x_pb_state'],{limit:600,order:'id desc'}, readOptions);
        const registeredIds=[...new Set(registrations.map(r=>m2oId(r.x_pb_pos_order_id)).filter(Boolean))];
        const knownUuids=[...new Set(registrations.map(r=>r.x_pb_order_uuid).filter(Boolean))];
        const domain=postpaidMode ? [['state','in',['paid','done','invoiced']]] :
            ['|','|','|',['shipping_date','!=',false],['id','in',registeredIds],['uuid','in',knownUuids],['lines.sale_order_origin_id','!=',false]];
        if(orderUuids)domain.push(['uuid','in',orderUuids]);
        const query=postpaidMode ? await reviewOrderQuery(readOptions) : {domain,fields:['id','uuid','name','pos_reference','date_order','shipping_date','partner_id','amount_total','state','config_id','picking_ids','company_id']};
        if(postpaidMode&&orderUuids)query.domain.push(['uuid','in',orderUuids]);
        const orders=await searchRead('pos.order',query.domain,query.fields,{order:'date_order desc,id desc',limit:600}, readOptions);
        const ids=orders.map(o=>o.id);
        const picks=ids.length?await readAll('stock.picking',[
            '|',['pos_order_id','in',ids],['id','in',orders.flatMap(o=>(o.picking_ids||[]).map(m2oId))],
            ['picking_type_code','=','outgoing'],['state','!=','cancel']],pickingIndexFields(),1000, readOptions):[];
        const completedIds=postpaidMode?[]:picks.filter(p=>p.state==='done').map(p=>p.id);
        const completedMoves=postpaidMode?[]:await readCompletedDeliveryTotals(completedIds,readOptions);
        // Odoo copies aggregate fields to backorders; verify their own move identity
        // before trusting the copied count, demand, status or picker in the list.
        const backorderIds=picks.filter(p=>p.state!=='done'&&m2oId(p.backorder_id)).map(p=>p.id);
        const backorderMoves=backorderIds.length?await readAll('stock.move',[['picking_id','in',backorderIds],['state','!=','cancel']],['id','picking_id','product_id','product_uom_qty','quantity','state'],1000, readOptions):[];
        const backorderTechs=backorderIds.length?await searchRead('stock.picking',[['id','in',backorderIds]],['id',state.fieldMap.tech],{limit:backorderIds.length}, readOptions):[];
        const byOrder=new Map(orders.map(o=>[o.id,o]));
        const registeredReview=new Set(reviewIds);
        const visiblePickingIds=new Set(picks.map(p=>p.id));
        const listedReviewIds=reviewIds.filter(id=>visiblePickingIds.has(id));
        const reviewMoves=listedReviewIds.length?await readAll('stock.move',[['picking_id','in',listedReviewIds],['state','=','done']],['id','picking_id','product_id','product_uom','product_uom_qty','quantity','state'],1000, readOptions):[];
        const legacyOperations=(reviewIds.legacyOperations||[]).filter(r=>visiblePickingIds.has(r.id));
        const operations=[...new Set([...listedReviewIds.map(id=>reviewOperation(reviewId(id))),...legacyOperations.map(r=>r.operation)])];
        const reviewEvents=listedReviewIds.length?await readAll(SHARED_EVENT_MODEL,[['x_pb_operation','in',operations]],['id','x_name','x_pb_operation','x_pb_payload','x_pb_status','x_pb_picker','x_pb_device_id','x_pb_client_time'],1000, readOptions):[];
        // Group once, preserving each filter's original item order and first-match rules.
        let sliceStarted = performance.now();
        const yieldListWork = async () => {
            if (readOptions) throwIfReadCancelled(readOptions);
            if (performance.now() - sliceStarted < 8) return;
            await new Promise(resolve => setTimeout(resolve, 0));
            sliceStarted = performance.now();
            if (readOptions) throwIfReadCancelled(readOptions);
        };
        const group = async (rows, key) => {
            const index = new Map();
            let processed = 0;
            for (const row of rows) {
                if (processed && processed % 250 === 0) await yieldListWork();
                processed++;
                const value = key(row); if (Number.isNaN(value)) continue;
                if (!index.has(value)) index.set(value, []);
                index.get(value).push(row);
            }
            return index;
        };
        const completedByPicking=await group(completedMoves,m=>m2oId(m.picking_id));
        const backordersByPicking=await group(backorderMoves,m=>m2oId(m.picking_id));
        const techByPicking=await group(backorderTechs,p=>p.id);
        const reviewsByPicking=await group(reviewMoves,m=>m2oId(m.picking_id));
        const eventsByOperation=await group(reviewEvents,e=>e.x_pb_operation);
        const legacyByPicking=await group(legacyOperations,r=>r.id);
        const fallbackOrderByPicking=new Map();
        for(const order of orders)for(const id of order.picking_ids||[]){const key=m2oId(id);if(!fallbackOrderByPicking.has(key))fallbackOrderByPicking.set(key,order);}
        const result=[];
        let projected = 0;
        for(const picking of picks){
            if (projected && projected % 10 === 0) await yieldListWork();
            projected++;
            const order=byOrder.get(m2oId(picking.pos_order_id))||fallbackOrderByPicking.get(picking.id);
            if(!order||order.state==='cancel')continue;
            const row=pickingSummaryRow(picking,order,'order');
            if(picking.state==='done')applyDeliverySummary(row,(completedByPicking.get(picking.id)||[]));
            else if(m2oId(picking.backorder_id)){
                const moves=(backordersByPicking.get(picking.id)||[]);
                const raw=Core.safeParse(techByPicking.get(picking.id)?.[0]?.[state.fieldMap.tech]);
                applyDeliverySummary(row,moves,raw);
            }
            if(picking.state==='done'&&postpaidMode){
                const review={...row,key:reviewTaskKey(picking.id),review:true,picking:{...picking,id:reviewId(picking.id),state:'assigned'},summaryOnly:true,status:'pending',progress:{scanned:null,demand:null}};
                if(registeredReview.has(picking.id)){
                    const log=(eventsByOperation.get(reviewOperation(review.picking.id))||[]);
                    try {
                        const legacy=legacyByPicking.get(picking.id)||[];
                        const legacyEvents=legacy.flatMap(r=>eventsByOperation.get(r.operation)||[]);
                        const revision=legacyEvents.length?await legacyReviewRevision(legacyEvents):'';
                        const snap=reviewSnapshot(picking.id,order.id,(reviewsByPicking.get(picking.id)||[]),log,{order,events:legacyEvents,revision});
                        review.status=snap.tech.reviewCompleted?'done':Core.statusFor(snap.tech,snap.moves,'assigned','paid');
                        review.progress=Core.progress(snap.tech,snap.moves);review.tech=snap.tech;review.responsible={name:snap.tech.picker||'',source:snap.tech.picker?'script':'none'};
                        review.picking.state=snap.tech.reviewCompleted?'done':'assigned';
                    } catch(error) {review.status=Core.STATUS.EXCEPTION;review.legacyError=error.message;}
                }
                result.push(review);
            } else result.push(row);
        }
        if(!orderUuids)state.posNativeLimitReached=orders.length===600;
        return result;
    }

    // Allocate an existing pre-pick once across all real deliveries by product.
    // Completed deliveries consume their share but are never written again.
    function splitFulfillmentCounts(sourceMoves,sourceTech,targetMoves) {
        const pool=new Map();
        for(const m of sourceMoves){const p=m2oId(m.product_id);pool.set(p,(pool.get(p)||0)+Number(sourceTech.counts?.[String(m.id)]||0));}
        const counts=new Map();
        const sorted=[...targetMoves].sort((a,b)=>(a.state==='done'?0:1)-(b.state==='done'?0:1)||Number(a.picking_id?.[0]||a.picking_id)-Number(b.picking_id?.[0]||b.picking_id)||a.id-b.id);
        for(const move of sorted){const p=m2oId(move.product_id),demand=move.state==='done'?Number(move.quantity):Core.demandOf(move);const amount=Math.min(Math.max(0,pool.get(p)||0),demand);pool.set(p,Math.max(0,(pool.get(p)||0)-amount));counts.set(move.id,amount);}
        if([...pool.values()].some(n=>n>0))throw Object.assign(new Error('原扫码数量超过实际交货需求，请在配货内核对。'),{code:'MIGRATION_EXCESS'});
        return counts;
    }
    async function reconcileSplitRequest(request,order,pickings,sourceOverride=null) {
        if(!posPaymentConfirmed(order))return {pending:true,reason:'payment_unconfirmed'};
        const ids=pickings.filter(p=>p.state!=='cancel').map(p=>p.id);
        const moves=await readAll('stock.move',[['picking_id','in',ids],['state','!=','cancel']],
            ['id','picking_id','product_id','product_uom_qty','quantity','state'],1000);
        const requestMoves=sourceOverride?.moves||prepickMoves(request);
        let sourceTech=sourceOverride?.tech||prepickTech(request,requestMoves);
        if(!sourceOverride&&Core.isSharedMode(sourceTech))sourceTech=Core.replaySharedEvents(sourceTech,requestMoves,await loadSharedEvents(null,request.id));
        // Demand must match; no guessing when order contents changed after pre-picking.
        const requested=bridgeMoveLines(requestMoves),actual=bridgeMoveLines(moves);
        assertBridgeQuantity(requested,moves);
        const allocated=splitFulfillmentCounts(requestMoves,sourceTech,moves);
        if(Core.extraTotal(sourceTech)>0||sourceTech.unknownScans?.length||sourceTech.exception?.active)throw new Error('配货存在错配或异常，请先在配货内处理；付款结果不受影响。');
        await discoverFields();
        for(const picking of pickings.filter(p=>!['done','cancel'].includes(p.state))){
            await withDeviceMutationLock(picking.id,async()=>{
                const native=await readOne('stock.picking',picking.id,['id','state',state.fieldMap.tech]);
                if(!native||['done','cancel'].includes(native.state))throw new Error('DELIVERY_CHANGED');
                const part=moves.filter(m=>m2oId(m.picking_id)===picking.id);
                const prior=techFromPicking(native,part),events=await loadSharedEvents(picking.id);
                if(Number(prior.prepickSourceRequestId)===Number(request.id))return;
                if(events.length||Object.values(prior.counts||{}).some(n=>Number(n)>0)||prior.picker)throw new Error('目标交货单已有配货记录，未覆盖；请在配货内核对。');
                const seed=Core.createTech(part);seed.counts=Object.fromEntries(part.map(m=>[String(m.id),allocated.get(m.id)||0]));seed.picker=sourceTech.picker;seed.startedAt=sourceTech.startedAt;seed.prepickSourceRequestId=request.id;
                const tech=Core.enableSharedMode(seed,part);await writeTech({picking:native},tech,part);
            });
        }
        await rpc(PREPICK_MODEL,'write',[[request.id],{x_pb_pos_order_id:order.id,x_pb_picking_id:ids[0]||false,x_pb_state:sourceOverride?'bridge_done':'linked',x_pb_change_pending:false,x_pb_synced_at:Core.odooDateTime(new Date().toISOString())}]);
        rememberPrepickMarker(order.uuid,{requestId:request.id,state:sourceOverride?'bridge_done':'linked',posOrderId:order.id,pickingIds:ids});
        return {linked:true,pickingIds:ids};
    }
    function cancelledUnpaidCart(orders) {
        if (orders.length !== 1) return false;
        const order = orders[0];
        return order.state === 'cancel' && Array.isArray(order.payment_ids) && !order.payment_ids.length &&
            Array.isArray(order.picking_ids) && !order.picking_ids.length;
    }
    async function reconcilePaidBridge(request) {
        if (request.x_pb_state === 'bridge_detached') return {skipped:true};
        const orders=await searchRead('pos.order',[['uuid','=',request.x_pb_order_uuid]],['id','uuid','state','picking_ids','payment_ids'],{limit:2});
        if (request.x_pb_state === 'bridge_wait' && cancelledUnpaidCart(orders)) {
            await cancelPrepickForOrder({uuid:request.x_pb_order_uuid}, 'cancelled_bridge_reconcile', {
                uuid:request.x_pb_order_uuid, requestId:request.id,
            });
            return {cancelled:true};
        }
        if(orders.length!==1||!posPaymentConfirmed(orders[0]))return {pending:true};
        const order=orders[0],picks=await searchRead('stock.picking',[
            '|',['pos_order_id','=',order.id],['id','in',(order.picking_ids||[]).map(m2oId)],
            ['picking_type_code','=','outgoing'],['state','!=','cancel']],['id','state'],{limit:100});
        if(!picks.length)return {pending:true};
        if(picks.every(p=>p.state==='done')){
            await rpc(PREPICK_MODEL,'write',[[request.id],{x_pb_state:'bridge_done',x_pb_pos_order_id:order.id}]);
            rememberPrepickMarker(order.uuid,{requestId:request.id,state:'bridge_done',posOrderId:order.id,pickingIds:picks.map(p=>p.id)});
            return {linked:true,completed:true};
        }
        const data=bridgePayload(request),source=await readOne('stock.picking',data.sourcePickingId,pickingIndexFields());
        if(!source)throw new Error('SOURCE_DELIVERY_MISSING');
        const moves=data.sourceMoves,seed=salesTech(source,moves),events=await loadSharedEvents(source.id);
        const tech=Core.isSharedMode(seed)?Core.replaySharedEvents(seed,moves,events):seed;
        return reconcileSplitRequest(request,order,picks,{moves,tech});
    }


    async function loadPrepickIndexRows(orderUuids = null, readOptions) {
        const fields = PREPICK_FIELDS.filter(f => !['x_pb_lines', 'x_pb_previous_lines', 'x_pb_payload', 'x_pb_change_summary'].includes(f));
        const history = Number(readOptions?.days ?? state.days) === 0 ? [] : ['|', ['x_pb_state', '!=', 'cancelled'], ['write_date', '>=', indexHistoryDomain().at(-1)[2]]];
        let requests;
        const base = [['x_pb_state', 'in', ['draft', 'cancelled', 'linked']], ...(orderUuids ? [['x_pb_order_uuid', 'in', orderUuids]] : [])];
        const visibleDomain = ['|', '|', ['x_pb_picking_id', '=', false], ['x_pb_change_pending', '=', true], ['x_pb_state', '=', 'cancelled']];
        try { requests = await searchRead(PREPICK_MODEL, [...base, ...visibleDomain, ...(orderUuids ? [] : history)], fields, {order: 'id desc', limit: 600}, readOptions); if (!orderUuids) state.posRequestLimitReached = requests.length === 600; }
        catch (error) { if (/does not exist|unknown model/i.test(String(error?.message || error))) return []; throw error; }
        await refreshRequestPayments(requests, true, readOptions);
        const visible = requests.filter(r => !m2oId(r.x_pb_picking_id) || r.x_pb_change_pending || r.x_pb_state === 'cancelled');
        const configs = await readIndexBatches('pos.config', visible.map(r => m2oId(r.x_pb_config_id)).filter(Boolean), 'id', ['id', 'picking_type_id'], [], readOptions);
        const byConfig = new Map(configs.map(c => [c.id, c]));
        return visible.filter(request => request.x_pb_state !== 'cancelled').map(request => {
            const raw = Core.safeParse(request.x_pb_tech), known = raw?.schema === 1;
            const moves = known ? baselineMoves(raw) : [], tech = known ? Core.hydrateTech(raw, moves) : Core.createTech([]);
            const cancelled = request.x_pb_state === 'cancelled';
            const status = cancelled ? Core.STATUS.CANCELLED : request.x_pb_change_pending ? Core.STATUS.EXCEPTION : Core.statusFor(tech, moves, 'assigned', 'draft');
            const linked = m2oId(request.x_pb_picking_id), sessions = getSessions(), oldSession = sessions[String(-request.id)];
            if (linked && oldSession && !sessions[String(linked)]) { setSession(linked, { ...oldSession, shared: true }); setSession(-request.id, null); }
            // Strip historical event/audit blobs after extracting summary values.
            const summaryRequest = { ...request }; delete summaryRequest.x_pb_tech;
            return { key: prepickTaskKey(request.id), kind: 'request', request: summaryRequest, summaryOnly: true,
                order: { id: -request.id, uuid: request.x_pb_order_uuid, name: request.x_name || `PRE-${request.id}`, pos_reference: request.x_name || `PRE-${request.id}`,
                    date_order: request.x_pb_requested_at || request.create_date, partner_id: request.x_pb_customer ? [0, request.x_pb_customer] : false,
                    amount_total: Number(request.x_pb_amount || 0), state: cancelled ? 'cancel' : 'draft', config_id: request.x_pb_config_id },
                picking: { id: -request.id, name: `${request._posPayment === 'paid' ? (state.lang === 'es' ? 'Entrega por vincular' : '交货单待关联') : t('draftOrder')} · ${m2oName(request.x_pb_config_id)}`, state: cancelled ? 'cancel' : 'assigned',
                    scheduled_date: request.x_pb_requested_at || request.create_date, date_done: cancelled ? request.x_pb_cancelled_at || request.write_date : false,
                    write_date: request.write_date, picking_type_id: byConfig.get(m2oId(request.x_pb_config_id))?.picking_type_id || false },
                moves: [], tech: {}, status, progress: known ? Core.progress(tech, moves) : { scanned: null, demand: null, excess: 0 },
                paymentNames: [], responsible: { name: tech.picker || '', source: tech.picker ? 'script' : 'none' },
            };
        });
    }

    async function loadRows(readOptions) {
        const source = state.orderSource, scope = dashboardRequestScope(), epoch = Number(state.posListEpoch || 0);
        const current = () => scope === dashboardRequestScope() && epoch === Number(state.posListEpoch || 0) && (!readOptions || state.dashboardRequest === readOptions && !readOptions.cancelled && !readOptions.signal?.aborted);
        await discoverFields(readOptions);
        if (!current()) return state.rows;
        if (source === 'pos' && state.posListScope === scope && Date.now() - Number(state.posListLoadedAt || 0) < 15000) return state.rows;
        const membership=await loadTaskMembershipIndex(readOptions);
        if(!current())return state.rows;
        state.taskMembership=membership;
        const rows = source === 'sale' ? await loadSalesRows(0, readOptions) : state.postpaidMode ? await loadPosIndexRows(null,readOptions) : (await Promise.all([loadPosIndexRows(null, readOptions), loadPrepickIndexRows(null, readOptions)])).flat();
        // A send may finish while an older list read is in flight. Never cache that stale response.
        if (!rows || !current()) return state.rows;
        state.salesError = '';
        state.rows = [...state.rows.filter(r => (isSale(r) ? 'sale' : 'pos') !== source), ...rows.filter(r=>membership.get(r.key)?.action!=='withdraw')];
        state.indexLoadedScopes?.add(scope);
        if (source === 'pos') {
            state.posListScope = scope; state.posListLoadedAt = Date.now();
            try { await refreshOrderNotes(rows, readOptions); } catch(error) { if (current()) state.error = error.message || String(error); }
            if (current()&&!state.postpaidMode) scheduleIndexedPrepickReconcile();
        }
        return state.rows;
    }
    function dashboardFilterChanged() {
        const scope = dashboardRequestScope();
        const request = state.dashboardRequest;
        // A receipt lookup owns an unscoped request until the user types another search.
        const superseded = request && (request.scope ? request.scope !== scope : Boolean(state.search.trim()));
        if (superseded) cancelDashboardRead();
        updateDashboardSearchResults();
        if (state.orderSource === 'sale' || (state.postpaidMode && state.posListScope !== scope)) {
            if (!state.dashboardRequest) refresh(true);
        }
    }

    function scheduleIndexedPrepickReconcile() {
        if (state.orderSource !== 'pos' || state.prepickReconciling || Date.now() - Number(state.lastPrepickReconcileAt || 0) < 15000) return;
        clearTimeout(state.indexReconcileTimer);
        state.indexReconcileTimer = setTimeout(async () => {
            if (!state.open || state.view !== 'dashboard' || state.orderSource !== 'pos' || state.prepickReconciling || document.visibilityState !== 'visible') return;
            // Preserve existing native POS payment/link reconciliation, outside the list's critical path.
            const attempts = state.prepickReconcileAttempts ||= new Map();
            const requests = dashboardPage().rows.filter(row => row.request?.x_pb_state === 'draft' && !m2oId(row.request.x_pb_picking_id))
                .sort((a, b) => Number(attempts.get(a.request.id) || 0) - Number(attempts.get(b.request.id) || 0) ||
                    Number(b.request._posPayment === 'paid') - Number(a.request._posPayment === 'paid')).slice(0, 2);
            for (const row of requests) attempts.set(row.request.id, Date.now());
            while (attempts.size > 1200) attempts.delete(attempts.keys().next().value);
            if (!requests.length) return;
            state.prepickReconciling = true; state.lastPrepickReconcileAt = Date.now();
            try {
                const results = await Promise.allSettled(requests.map(row => reconcilePrepickOrder(row.request.x_pb_order_uuid)));
                if (results.some(r => r.status === 'fulfilled' && (r.value?.linked || r.value?.needsConfirmation || r.value?.cancelled))) {
                    invalidateDashboardIndex();
                    await refresh(true);
                }
            } finally { state.prepickReconciling = false; }
        }, 1000);
    }

    const orderKeyCollator = new Intl.Collator(undefined, { numeric: true });
    function filteredRows(counts) {
        if (state.orderSource === 'sale') return state.salesPage?.key === salesRequestKey() ? state.rows.filter(r => isSale(r) && r.picking?.state !== 'cancel' && r.order.state !== 'cancel') : [];
        const q = String(state.search || '').trim().toLowerCase();
        let rows = state.rows.filter(row => (isSale(row) ? 'sale' : 'pos') === state.orderSource && row.picking?.state !== 'cancel' && row.order.state !== 'cancel' && row.request?.x_pb_state !== 'cancelled');
        rows=rows.filter(row=>state.taskMembership?.get(row.key)?.action!=='withdraw'&&(state.postpaidMode?!row.request:!row.review));
        if (state.orderSource === 'sale' && state.salesperson !== 'all') rows = rows.filter(r => String(m2oId(r.order.user_id) || 0) === state.salesperson);
        if (state.warehouse && state.warehouse !== '__all__') rows = rows.filter(row => String(row.picking?.picking_type_id?.[0] || '') === state.warehouse);
        if (q) rows = rows.filter(row => [orderNote(row), row.order.name, row.order.client_order_ref, row.order.user_id?.[1], row.order.pos_reference,
            row.picking?.name, row.order.partner_id?.[1], row.responsible?.name, ...(state.postpaidMode ? [row.order.id,row.order.tracking_number] : [])].some(value => String(value || '').toLowerCase().includes(q)));
        if (Number(state.days) > 0) {
            const cutoff = Date.now() - Number(state.days) * 86400000;
            rows = rows.filter(row => {
                if (![Core.STATUS.DONE, Core.STATUS.CANCELLED].includes(row.status)) return true;
                const date = row.status === Core.STATUS.CANCELLED ? row.request?.x_pb_cancelled_at || row.picking?.write_date || row.order.write_date || row.order.date_order
                    : row.picking?.date_done || row.order.date_order;
                return Date.parse(String(date || '').replace(' ', 'T') + 'Z') >= cutoff;
            });
        }
        if (counts) for (const row of rows) counts[row.status] = (counts[row.status] || 0) + 1;
        if (!q) rows = rows.filter(row => row.status === state.tab);
        rows.sort((a, b) => (String(a.order.date_order).localeCompare(String(b.order.date_order)) || orderKeyCollator.compare(String(a.key), String(b.key))) * (state.sort === 'oldest' ? 1 : -1));
        return rows;
    }

    function dashboardSummaryHint() {
        if (state.orderSource === 'sale') return state.lang === 'es' ? 'Solo entregas agregadas · 10 por página · Buscar por pedido, entrega, cliente o vendedor; notas solo al abrir o en esta página' : '仅显示主动加入的交货单 · 每页 10 单 · 搜索单号、交货单、客户、参考号、销售人员或配货员；备注随当前页显示';
        return state.lang === 'es' ? 'Resumen guardado · Hasta 600 pedidos POS recientes y 600 solicitudes · Se verifica al abrir' : '已保存摘要 · 最多加载最近 600 张 POS 单及 600 张预配货单 · 打开时核对最新数据';
    }

    function dashboardIndexPending() {
        if (state.orderSource === 'sale') return state.salesPage?.key !== salesRequestKey();
        return state.posListScope !== dashboardRequestScope();
    }

    function dashboardScrollOffsets() {
        return ['.pbful-shell', '.pbful-content', '#pbful-order-list'].map(selector => ({ selector, top: root.querySelector(selector)?.scrollTop || 0 }));
    }

    function restoreDashboardScroll(offsets) {
        for (const { selector, top } of offsets || []) { const element = root.querySelector(selector); if (element) element.scrollTop = top; }
    }

    function dashboardHistoryPicker() {
        const es = state.lang === 'es';
        return `<label><span>${es ? 'Completados / cancelados' : '完成／取消范围'}</span><select id="pbful-history-days">${[[1, es ? 'Últimas 24 horas' : '最近 24 小时'], [7, t('days7')], [30, t('days30')], [0, state.orderSource === 'sale' ? (es ? 'Todo el historial' : '全部历史') : (es ? 'Sin límite de fecha (pedidos cargados)' : '不限日期（当前加载范围）')]].map(([days, label]) => `<option value="${days}" ${Number(state.days) === days ? 'selected' : ''}>${label}</option>`).join('')}</select></label>`;
    }


    // Remote reads and local projections only. The compatibility facade owns
    // bridge status publication; this reader never writes an Odoo record.
    async function readDeliveryTaskSnapshot(row,readOptions) {
        const pf = state.fieldMap;
        const readPicking = () => readOne("stock.picking", row.picking.id, [
            "id", "name", "state", "backorder_id", "scheduled_date", "date_done", "partner_id", "pos_order_id", "picking_type_id", "location_id", "move_ids", "write_date", "user_id", ...(isSale(row) ? ["sale_id", "picking_type_code"] : []),
            ...Object.values(pf).filter((v) => typeof v === "string"),
        ],readOptions);
        const readMoves = includeCancelled => readAll("stock.move", [["picking_id", "=", row.picking.id], ...(includeCancelled ? [] : [["state", "!=", "cancel"]])], [
            "id", "picking_id", "product_id", "product_uom_qty", "quantity", "product_uom", "has_tracking", "picked", "state", "write_date", "company_id", "location_id", "location_dest_id", ...(isSale(row) ? ["sale_line_id"] : []),
        ], 1000,readOptions);
        const saleTask = isSale(row);
        const [picking, posMoves] = await Promise.all([readPicking(), saleTask ? null : readMoves(false)]);
        if (!picking) throw new Error(state.lang === "es" ? "La entrega ya no existe o no está disponible" : "交货单已不存在或无法访问");
        let moves = saleTask ? await readMoves(picking.state === "cancel") : posMoves;
        if (isSale(row)) {
            if (m2oId(picking.sale_id) !== row.order.id || m2oId(picking.pos_order_id) || picking.picking_type_code !== "outgoing")
                throw new Error(t("saleNoDelivery"));
            const sale = await readOne("sale.order", row.order.id, ["id","name","state","user_id","partner_id","client_order_ref"], readOptions);
            if (!sale) throw new Error(t("saleNoDelivery"));
            row = {...row, order: {...row.order, ...sale}};
            if (sale.state !== "sale" && picking.state !== "done") picking.state = "cancel";
        }
        let bridge=null;
        if(isSale(row)) {
            const record=await bridgeForSource(picking.id);
            if(record) {
                bridge=await resolveSaleBridge(record,picking,moves);
                if(bridge.paid) {
                    if(row.order.state==='cancel')throw bridgeError('销售单已取消，请核对已付款 POS 和实际交货单；未自动修改库存。','La venta está cancelada. Revise el POS pagado y su entrega.');
                    moves=bridge.moves;
                    picking.state=bridge.target.state; picking.date_done=bridge.target.date_done;
                    picking.nativePickingId=bridge.target.id; picking.nativeName=bridge.target.name;
                }
            }
        }
        const originalTech=Core.safeParse(picking[pf.tech]);
        const isolated=isolateBackorderTech(picking,moves,originalTech);
        if(isolated!==originalTech)picking[pf.tech]=JSON.stringify(isolated);
        const storedTech = isSale(row) ? salesTech(picking, moves) : techFromPicking(picking, moves);
        const sharedEvents = Core.isSharedMode(storedTech) || isSale(row) ? await loadSharedEvents(picking.id) : [];
        const tech = Core.isSharedMode(storedTech) ? Core.replaySharedEvents(storedTech, moves, sharedEvents) : storedTech;
        return {row,picking,moves,bridge,storedTech,sharedEvents,tech};
    }

    async function readDeliveryTaskCatalog(snapshot, options = {}) {
        const {row,picking,moves,bridge,storedTech,sharedEvents,tech} = snapshot;
        let completedPrepickArchive = [], completedArchiveError = "";
        if (!options.reviewCatalog && !snapshot.review && !isSale(row) && picking.state === "done") {
            try { completedPrepickArchive = await loadCompletedPrepickArchive(picking, row.order); }
            catch (_error) { completedArchiveError = state.lang === "es" ? "Registro de presurtido no disponible; sincronice para reintentar." : "原预配货记录暂未加载，请同步重试。"; }
        }
        const orderProductIds = [...new Set(moves.map((move) => Array.isArray(move.product_id) ? move.product_id[0] : move.product_id))];
        const extraProductIds = Object.entries(tech.extraCounts || {}).filter(([, count]) => Number(count) > 0).map(([id]) => Number(id));
        const baselineProductIds = isSale(row) ? baselineMoves(tech).map(move => m2oId(move.product_id)) : [];
        const productIds = [...new Set([...orderProductIds, ...extraProductIds, ...baselineProductIds].filter(Boolean))];
        const locationId = m2oId(picking.location_id);
        const cached = options.catalog;
        const requestedIds = new Set(productIds.map(Number));
        const recent = cached && Number(cached.picking.id) === Number(picking.id) &&
            m2oId(cached.picking.location_id) === locationId && Date.now() - cached.codesLoadedAt < 15000 &&
            cached.boxCodesLoadedAt === state.boxLoadedAt;
        const loadedIds = cached?.catalogProductIds;
        const useCatalog = recent && loadedIds?.length === requestedIds.size &&
            loadedIds.every(id => requestedIds.has(id));
        let products, stock, systemCodes;
        if (useCatalog) {
            products = cached.products.filter(p => requestedIds.has(Number(p.id)));
            stock = cached.stock;
            systemCodes = cached.systemCodes;
        } else {
            const [catalog, quants] = await Promise.all([
                readScanCatalog(productIds),
                productIds.length && locationId ? readAll("stock.quant", [
                    ["product_id", "in", productIds], ["location_id", "child_of", locationId],
                ], ["id", "product_id", "quantity", "reserved_quantity"], 1000) : [],
            ]);
            products = catalog.products;
            systemCodes = catalog.systemCodes;
            stock = new Map();
            for (const quant of quants) {
                const id = m2oId(quant.product_id);
                stock.set(id, (stock.get(id) || 0) + Number(quant.quantity || 0));
            }
        }
        const odooCodeCount = new Set(systemCodes.flatMap((item) => Core.parseCodeList(item.code))).size;
        const boxCodeCount = new Set(state.boxMappings.filter((item) => item.enabled).map((item) => Core.normalizeCode(item.boxCode)).filter(Boolean)).size;
        return {
            bridge, completedPrepickArchive, completedArchiveError,
            salesCancelAck: sharedEvents.some(e=>Core.normalizeSharedEvent(e).op.scope==="sales_cancel_ack"),
            row, picking, moves, products, stock, tech, storedTech, sharedEvents, sharedEventCount: sharedEvents.length, systemCodes, orderProductIds,
            catalogProductIds: products.map(product => Number(product.id)),
            responsible: effectivePicker(picking, tech),
            index: Core.productCodeIndex(products, state.boxMappings, systemCodes),
            codesLoadedAt: useCatalog ? cached.codesLoadedAt : Date.now(), odooCodeCount, boxCodeCount, boxCodesLoadedAt: state.boxLoadedAt,
        };
    }

    async function readDeliveryTaskDetail(row, options = {}) {
        return readDeliveryTaskCatalog(await readDeliveryTaskSnapshot(row,options.readOptions), options);
    }

    // Preserve the legacy bridge publication point: after event replay and
    // before catalog/archive reads. Failure still stops the existing load.
    async function publishLoadedTaskStatus(snapshot) {
        if (snapshot.bridge?.paid)
            await publishBridgeStatus(snapshot.bridge, snapshot.tech, snapshot.moves);
    }

    // Existing callers keep their behavior and side-effect order. Use
    // readTaskDetail for a query that must not publish a bridge status.
    async function loadDetail(row, options = {}) {
        await assertTaskListed(row,options.readOptions);
        const {type} = taskIdentity(row);
        if (type === 'review') return loadReviewDetail(row, options);
        if (type === 'prepick') return loadPrepickDetail(row);
        const snapshot = await readDeliveryTaskSnapshot(row,options.readOptions);
        throwIfReadCancelled(options.readOptions);
        await publishLoadedTaskStatus(snapshot);
        throwIfReadCancelled(options.readOptions);
        return readDeliveryTaskCatalog(snapshot, options);
    }

    async function readTaskDetail(row, options = {}) {
        const {type} = taskIdentity(row);
        if (type === 'review') return readReviewTaskDetail(row, options);
        if (type === 'prepick') return readPrepickTaskDetail(row);
        return readDeliveryTaskDetail(row, options);
    }

    async function ensureSharedMode(detail) {
        if (Core.isSharedMode(detail?.tech)) return detail;
        const enabled = Core.enableSharedMode(detail.tech, isSale(detail) ? baselineMoves(detail.tech) : detail.moves);
        await writeTech(detail, enabled, detail.moves);
        const refreshed = await loadDetail(detail.row);
        if (!Core.isSharedMode(refreshed.tech)) throw Object.assign(new Error("多设备模式初始化失败，请重试"), { code: "SHARED_INIT_FAILED" });
        return refreshed;
    }

    async function syncSharedState(options = {}) {
        if (isReadOnlyDetail()) return { changed: false, skipped: true, readOnly: true };
        if (!canPullDetail()) return { changed: false, skipped: true };
        if (state.sharedPulling || state.confirmingRequestId) return { changed: false, busy: true };
        if (state.detail?.review) return syncReviewState(options);
        if(isSale(state.detail)) {state.sharedPulling=true;try{return await syncSalesDetail(options);}finally{state.sharedPulling=false;updateSyncIndicator();}}
        const isRequest = Boolean(state.detail.request);
        const context = { pickingId: Number(state.detail.picking.id), requestId: Number(state.detail.request?.id || 0), row: state.detail.row, token: state.session?.token || null };
        const contextActive = () => Boolean(state.detail && Number(state.detail.picking.id) === context.pickingId &&
            Number(state.detail.request?.id || 0) === context.requestId && (state.session?.token || null) === context.token);
        state.sharedPulling = true;
        if (options.manual) updateSyncIndicator();
        try {
            if (options.reconcile !== false && isRequest && !m2oId(state.detail.request?.x_pb_picking_id)) {
                try {
                    const result = await reconcilePrepickOrder(state.detail.request.x_pb_order_uuid);
                    if (options.manual && result?.pending) {
                        const es = state.lang === 'es';
                        const message = result.reason === 'shipping_date_missing'
                            ? (es ? 'Falta la fecha de envío en el pedido POS.' : 'POS 订单尚未设置发货日期。')
                            : result.reason === 'payment_unconfirmed'
                                ? (es ? 'El servidor aún no confirma el pago.' : '服务器尚未确认付款状态。')
                                : (es ? 'No hay una entrega única para vincular; revise las entregas del pedido.' : '未找到唯一可关联的交货单，请核对订单的交货记录。');
                        throw new Error(message);
                    }
                } catch (error) { if (options.manual) throw error; }
            }
            if (!contextActive()) return { changed: false, stale: true };
            const [record, events] = await Promise.all([
                isRequest ? readOne(PREPICK_MODEL, context.requestId, PREPICK_FIELDS) : readOne("stock.picking", context.pickingId, ["id", "state", "backorder_id", "write_date", state.fieldMap.tech]),
                loadSharedEvents(isRequest ? null : context.pickingId, isRequest ? context.requestId : null),
            ]);
            if (!contextActive()) return { changed: false, stale: true };
            if (!record) throw Object.assign(new Error(isRequest ? "预配货任务不存在" : "交货单不存在"), { code: "TERMINAL" });
            if (isRequest) {
                await refreshRequestPayments([record], Boolean(options.manual));
                if (!contextActive()) return { changed: false, stale: true };
                const requestChanged = prepickStateFingerprint(record) !== prepickStateFingerprint(state.detail.request);
                if (m2oId(record.x_pb_picking_id) && !record.x_pb_change_pending) {
                    invalidateDashboardIndex();
                    state.view = "dashboard"; state.detail = null; state.session = null; state.pickerDraft = null; state.quantityDraftBases.clear(); state.quantityDrafts.clear();
                    if (options.renderView !== false) render();
                    setTimeout(() => refresh(true), 0);
                    toast(t("paidLinked"), "ok", 2600);
                    return { changed: true, reloaded: true, linkedPickingId: m2oId(record.x_pb_picking_id) };
                }
                if (requestChanged || record.x_pb_state === "cancelled" || record.x_pb_change_pending || !Core.isSharedMode(state.detail.tech)) {
                    const stored = prepickTech(record, prepickMoves(record));
                    const techChanged = sharedStateFingerprint(stored) !== sharedStateFingerprint(state.detail.storedTech || state.detail.tech) ||
                        Core.isSharedMode(stored) !== Core.isSharedMode(state.detail.tech);
                    const changed = requestChanged || techChanged;
                    // Unclaimed requests have no scan events to aggregate. Unchanged
                    // warnings must not reload products and warehouse stock every 2s.
                    if (changed || options.manual) {
                        const refreshed = await loadPrepickDetail(prepickRow(record));
                        if (!contextActive()) return { changed: false, stale: true };
                        state.detail = refreshed;
                        if (options.renderView !== false) {
                            if (options.manual) render(); else renderQuantityFeedback();
                        }
                    }
                    state.lastSharedPullAt = Date.now();
                    state.saveError = "";
                    return { changed, reloaded: changed || Boolean(options.manual), cancelled: record.x_pb_state === "cancelled", linkedPickingId: m2oId(record.x_pb_picking_id) };
                }
            } else if (["done", "cancel"].includes(record.state)) {
                enterReadOnlyDetail({ ...state.detail, picking: { ...state.detail.picking, ...record } });
                if (options.renderView !== false) render();
                await reloadReadOnlyDetail();
                return { changed: true, readOnly: true };
            }
            const storedTech = isRequest ? prepickTech(record, state.detail.moves) : techFromPicking(record, state.detail.moves);
            if (!Core.isSharedMode(storedTech)) throw Object.assign(new Error("多设备同步状态丢失，请重新打开订单"), { code: "SHARED_STATE_LOST" });
            const next = Core.replaySharedEvents(storedTech, state.detail.moves, events);
            const rejected = next.eventSync?.rejectedEvents || [];
            if (options.expectedEventId && !events.some(event => {
                const normalized = Core.normalizeSharedEvent(event);
                return normalized.name === String(options.expectedEventId) && ["done", "applied", "ok"].includes(normalized.status);
            })) throw Object.assign(new Error("扫码记录尚未通过服务器回读校验，请重新同步"), { code: "VERIFY_FAILED" });
            if (options.expectedEventId && rejected.some((item) => item.id === options.expectedEventId)) {
                const item = rejected.find((entry) => entry.id === options.expectedEventId);
                throw Object.assign(new Error(`并发操作未应用：${item.code}`), { code: "EVENT_REJECTED", eventError: item });
            }
            const changed = sharedStateFingerprint(next) !== sharedStateFingerprint(state.detail.tech);
            const aggregateDirty = sharedStateFingerprint(next) !== sharedStateFingerprint(storedTech);
            if (aggregateDirty && options.writeAggregate !== false) await writeTech(isRequest ? { ...state.detail, request: record } : context.pickingId, next, state.detail.moves);
            if (!contextActive()) {
                return { changed: false, stale: true, events, tech: next };
            }
            const missingExtraProduct = Object.entries(next.extraCounts || {}).some(([id, count]) => Number(count) > 0 && !state.detail.products.some((product) => Number(product.id) === Number(id)));
            if (missingExtraProduct) {
                const refreshed = await loadDetail(context.row);
                if (!contextActive()) return { changed: false, stale: true };
                state.detail = refreshed;
            }
            else {
                state.detail = {
                    ...state.detail,
                    request: isRequest ? record : state.detail.request,
                    picking: { ...state.detail.picking, state: isRequest ? state.detail.picking.state : record.state, write_date: record.write_date },
                    tech: next,
                    storedTech,
                    sharedEvents: events,
                    sharedEventCount: events.length,
                    responsible: isRequest ? { name: next.picker || "", source: next.picker ? "script" : "none" } : effectivePicker(state.detail.picking, next),
                };
            }
            state.lastSharedPullAt = Date.now();
            if (changed || aggregateDirty) state.lastSavedAt = Date.now();
            state.saveError = "";
            if ((changed || options.manual) && options.renderView !== false) {
                if (options.manual) render(); else renderQuantityFeedback();
            }

            return { changed, aggregateDirty, events, tech: state.detail.tech };
        } finally {
            state.sharedPulling = false;
            updateSyncIndicator();
        }
    }

    const stockRefreshTimes = new WeakMap();
    const stockReads = new WeakMap();
    function refreshVisibleDetailStock(manual = false) {
        const detail = state.detail;
        if (!state.open || state.view !== 'detail' || !detail || detail.review || isSale(detail) || isReadOnlyDetail(detail)) return;
        const stock = detail.stock, locationId = detail.stockLocationId || m2oId(detail.picking.location_id);
        const ids = [...new Set(detail.products.map(p => Number(p.id)).filter(Boolean))];
        if (!stock || !locationId || !ids.length) return;
        if (stockReads.has(stock)) return stockReads.get(stock);
        if (!manual && Date.now() - (stockRefreshTimes.get(stock) || detail.codesLoadedAt || 0) < 60000) return;
        stockRefreshTimes.set(stock, Date.now());
        const pending = readAll('stock.quant', [['location_id','child_of',locationId],['product_id','in',ids]], ['id','product_id','quantity'], 1000).then(rows => {
            if (!state.open || state.view !== 'detail' || state.detail?.stock !== stock || isReadOnlyDetail()) return;
            const fresh = new Map();
            for (const row of rows) {
                if (!Number.isFinite(row.quantity)) throw Error(state.lang === 'es' ? 'Existencias no válidas' : '库存返回异常');
                const id = m2oId(row.product_id);
                fresh.set(id, (fresh.get(id) || 0) + row.quantity);
            }
            if (!ids.some(id => (fresh.get(id) || 0) !== (stock.get(id) || 0))) return;
            state.detail.stock = fresh;
            stockRefreshTimes.set(fresh, Date.now());
            renderQuantityFeedback();
        }).finally(() => stockReads.delete(stock));
        stockReads.set(stock, pending);
        return pending;
    }

    async function autoPullSharedState() {
        if (!state.open || state.view !== "detail" || document.visibilityState !== "visible" || !navigator.onLine) return;
        if (!canPullDetail() || state.confirmingRequestId || state.mutationSyncing || state.offlineFlushing || state.scanProcessing || state.scanQueue.length) return;
        // Completed detail is retained for viewing and must never write aggregate state.
        if (["done", "cancel"].includes(state.detail.picking.state)) return;
        const context = { pickingId: Number(state.detail.picking.id), token: state.session?.token || null };
        try {
            await syncSharedState({ writeAggregate: true });
            if (Number(state.detail?.picking.id) === context.pickingId && !state.scanProcessing && !state.scanQueue.length)
                Promise.resolve(refreshVisibleDetailStock()).catch(error => console.warn("配货库存刷新", error));
        } catch (error) {
            if (!state.detail || Number(state.detail.picking.id) !== context.pickingId ||
                (state.session?.token || null) !== context.token || ["done", "cancel"].includes(state.detail.picking.state)) return;
            if (!isNetworkError(error)) {
                state.saveError = error.message || String(error);
                updateSyncIndicator();
            }
        }
    }

    function getSessions() { return loadJson(LS.sessions, {}); }
    function setSession(pickingId, value) { const all = getSessions(); if (value) all[pickingId] = value; else delete all[pickingId]; saveJson(LS.sessions, all); }
    function pickerNeedsConfirmation() {
        return Boolean(state.pickerEditing || !currentPicker());
    }

    function renderPickerControl(detail, readOnly, sourceOwner) {
        if(readOnly)return `<span>${t('picker')}：<strong>${esc(detail.tech.picker || sourceOwner)}</strong></span>`;
        if(pickerNeedsConfirmation())return `<label><span>${t('picker')}</span><slot name="pbful-picker-input"></slot></label><button data-act="claim">${state.lang==='es'?'Confirmar':'确认姓名'}</button>${currentPicker()?`<button data-act="picker-cancel">${state.lang==='es'?'Cancelar':'取消'}</button>`:''}`;
        return `<span class="pbful-picker-current">${t('picker')}：<strong>${esc(state.session?.picker || currentPicker())}</strong></span><button data-act="picker-edit">${state.lang==='es'?'Cambiar':'更改'}</button>${!state.session?`<button data-act="claim" ${state.mutationSyncing?'disabled':''}>${state.lang==='es'?'Conectar':'重试连接'}</button>`:''}`;
    }

    async function ensureRememberedPickerSession() {
        const detail=state.detail, picker=currentPicker();
        if(!detail || !picker || state.pickerEditing || isReadOnlyDetail(detail) || detail.request?.x_pb_state==='cancelled' || validationBusy(detail))return false;
        if(state.session?.picker===picker && Core.verifyLock(detail.tech,state.session))return true;
        if(!navigator.onLine)return false;
        state.pickerDraft=picker;
        try {await claim(false,picker);return true;}
        catch(error){toast(error.message||String(error),'error');return false;}
    }

    async function cancelPickerChange() {
        const picker=currentPicker();
        // A failed readback can follow a successfully appended name event. Restore
        // that session as well before displaying the old confirmed identity again.
        if(state.session && state.session.picker!==picker)await claim(false,picker);
        state.pickerEditing=false;state.pickerDraft=picker;render();focusScan();
    }

    function currentPicker() {
        const value = String(localStorage.getItem(LS.picker) || "").trim();
        return /^配货员[123]$/.test(value) ? "" : value;
    }

    async function claim(force = false, pickerOverride = null) {
        if (!state.detail) return;
        if(isReadOnlyDetail())throw Object.assign(new Error(t("readOnly")),{code:"TERMINAL"});
        const pickingId = state.detail.picking.id;
        state.mutationSyncing = true; state.saveError = ""; updateSyncIndicator();
        try {
            return await withDeviceMutationLock(pickingId, () => claimUnlocked(force, pickingId, pickerOverride));
        } catch (error) {
            state.saveError = error.message || String(error);
            throw error;
        } finally {
            state.mutationSyncing = false; render(); focusScan();
        }
    }

    async function claimUnlocked(force, pickingId, pickerOverride = null) {
        if (!state.detail || Number(state.detail.picking.id) !== Number(pickingId)) throw Object.assign(new Error("配货页面已经切换，本次接管未提交"), { code: "STALE_CONTEXT" });
        const previousToken = state.session?.token || null;
        const contextActive = () => Boolean(state.detail && Number(state.detail.picking.id) === Number(pickingId) && (state.session?.token || null) === previousToken);
        const requireContext = () => { if (!contextActive()) throw Object.assign(new Error("配货页面已经切换，本次接管未提交"), { code: "STALE_CONTEXT" }); };
        const pickerSelect = pickerNameInputElement();
        const picker = String(pickerOverride ?? (pickerSelect && pickerNeedsConfirmation() ? pickerSelect.value : currentPicker())).trim();
        if (!picker) throw Object.assign(new Error(pbUiText("请先填写真实的配货员姓名","Escribe el nombre real del surtidor.")), { code: "INVALID_PICKER" });
        if(state.session?.picker===picker && currentPicker()===picker && Core.verifyLock(state.detail.tech,state.session)) {state.pickerEditing=false;state.pickerDraft=picker;return {unchanged:true};}
        let detail = await loadDetail(state.detail.row,state.detail.review?{catalog:state.detail}:{});
        requireContext();
        if(isReadOnlyDetail(detail))throw Object.assign(new Error(t("readOnly")),{code:"TERMINAL"});
        detail = await ensureSharedMode(detail);
        requireContext();
        if(isReadOnlyDetail(detail))throw Object.assign(new Error(t("readOnly")),{code:"TERMINAL"});
        const previous = getSessions()[detail.picking.id];
        const session = previous?.shared && previous.deviceId === deviceId
            ? { ...previous, picker, deviceType: currentDeviceType() }
            : { shared: true, deviceId, token: Core.makeId("session"), picker, deviceType: currentDeviceType() };
        const op = {
            id: Core.makeId("session"), scope: "session", type: previous?.shared ? "update" : "start",
            source: force ? "shared_force_compat" : "shared_join", pickingId: detail.picking.id,
        };
        await createSharedEvent(op, detail, session);
        setSession(detail.picking.id, session);
        if (!contextActive()) return { stale: true };
        state.detail = detail; state.session = session; state.pickerDraft = picker;
        await syncSharedState({ expectedEventId: op.id, writeAggregate: true, renderView: false });
        if(Number(state.detail?.picking.id)!==Number(pickingId)||state.session?.token!==session.token)return {stale:true};
        localStorage.setItem(LS.picker,picker);state.pickerEditing=false;
        state.lastSavedAt = Date.now(); state.saveError = "";
        render(); focusScan();
    }

    // The acceptance service receives only these two inventory operations.
    // These are synchronous delegates returning the original RPC promise;
    // no retry, extra await point, payment hook or general-purpose write API.
    class NativeStockWriter {
        constructor(callRpc) { this.callRpc = callRpc; }

        writeMoveQuantity(moveId, quantity, picked) {
            return this.callRpc('stock.move', 'write', [[moveId], {quantity, picked}]);
        }

        validateTransfer(pickingId) {
            return this.callRpc('stock.picking', 'button_validate', [[pickingId]]);
        }
    }

    const nativeStockWriter = new NativeStockWriter(rpc);

    // Native acceptance owns its original guard, rollback and uncertain-result
    // state machine. Only synchronous checks and writers are extracted: await
    // positions and the order of external calls stay unchanged.
    class NativeAcceptanceService {
        constructor(runtime, stockWriter, metadataWriter, dependencies) {
            this.runtime = runtime; this.stockWriter = stockWriter;
            this.metadataWriter = metadataWriter; this.dependencies = dependencies;
        }

        assertReady(detail, context) {
            const {
                Core
            } = this.dependencies;
            if (!Core.verifyLock(detail.tech, context.session)) throw Object.assign(new Error("配货已被其他设备接管，未填写原生数量"), { code: "LOCK_LOST" });
            if (Core.extraTotal(detail.tech) > 0) throw Object.assign(new Error("仍有错配商品，请先全部减到 0"), { code: "WRONG_ITEMS_REMAIN" });
            if (!Core.canFinalize(detail.tech, detail.moves)) throw Object.assign(new Error("商品尚未配齐或仍有异常，未填写原生数量"), { code: "NOT_READY" });
            const tracked = detail.moves.find((move) => move.has_tracking && move.has_tracking !== "none") || detail.products.find((p) => p.tracking && p.tracking !== "none");
            if (tracked) throw Object.assign(new Error("订单含批次/序列号商品，请在原生交货单中逐个填写，脚本未改动实际数量。"), { code: "TRACKING" });
            const base = Core.assertBaseline(detail.tech, detail.moves);
            if (!base.ok) throw Object.assign(new Error("订单需求已变化，已暂停，请重新载入。"), { code: "DEMAND_CHANGED" });

        }

        async verifyCompletedMoves(pickingId, expectedMoves) {
            const moves = await readAll("stock.move", [["picking_id","=",pickingId],["state","!=","cancel"]],
                ["id","product_id","product_uom","state","quantity"]);
            const lines = await readAll("stock.move.line", [["picking_id","=",pickingId],["state","=","done"]],
                ["id","move_id","product_id","product_uom_id","quantity"]);
            const unitIds = [...new Set([...moves.map(m => m2oId(m.product_uom)), ...lines.map(l => m2oId(l.product_uom_id))])];
            const units = await searchRead("uom.uom", [["id","in",unitIds]], ["id","factor"], {limit:unitIds.length});
            const factors = new Map(units.map(u => [u.id, Number(u.factor)]));
            const byId = new Map(moves.map(m => [m.id,m])), totals = new Map();
            const close = (a,b) => Number.isFinite(a) && Number.isFinite(b) && Math.abs(a-b) < 1e-7;
            const mismatch = () => Object.assign(new Error(pbUiText("交货状态与商品明细尚未核对一致，请打开原生交货单核对。","Revise la entrega en Odoo. El estado y las líneas aún no concuerdan.")),{code:"NATIVE_READBACK_MISMATCH"});
            for (const line of lines) {
                const move = byId.get(m2oId(line.move_id));
                if (!move || m2oId(line.product_id)!==m2oId(move.product_id)) throw mismatch();
                const quantity = Number(line.quantity)*factors.get(m2oId(line.product_uom_id))/factors.get(m2oId(move.product_uom));
                totals.set(move.id, (totals.get(move.id) ?? 0)+quantity);
            }
            if (moves.length!==expectedMoves.length) throw mismatch();
            for (const expected of expectedMoves) {
                const move = byId.get(expected.id), demand = Core.demandOf(expected);
                if (!move || move.state!=="done" || m2oId(move.product_id)!==m2oId(expected.product_id) ||
                    m2oId(move.product_uom)!==m2oId(expected.product_uom) ||
                    !close(Number(move.quantity),demand) || !close(totals.get(move.id) ?? 0,demand)) throw mismatch();
            }
        }

        assertNativeActionAccepted(validationResult) {

            if (validationResult && typeof validationResult === "object") {
                const model = validationResult.res_model || validationResult.name || "Odoo";
                throw Object.assign(new Error(`Odoo 验收还需要额外操作（${model}），请打开原生交货单检查`), { code: "VALIDATION_WIZARD", action: validationResult });
            }

        }

        assertNativeCompleted(finalPicking) {

            if (finalPicking?.state !== "done") throw Object.assign(new Error("Odoo 未完成交货验证，请打开原生交货单检查"), { code: "VALIDATION_NOT_DONE" });

        }

        async accept() {
            const state = this.runtime, stockWriter = this.stockWriter, metadataWriter = this.metadataWriter;
            const {
                Core,
                assertAcceptancePayment,
                assertBridgeTargetSnapshot,
                assertWritableDetail,
                bridgeError,
                canValidateHere,
                createSharedEvent,
                enterReadOnlyDetail,
                isNetworkError,
                isReadOnlyDetail,
                isSale,
                loadDetail,
                loadSharedEvents,
                packingConfirmed,
                pbUiText,
                publishBridgeStatus,
                readOne,
                reloadReadOnlyDetail,
                render,
                saveUndoRecord,
                showPrompt,
                t,
                toast,
                validationControl,
                writeTech
            } = this.dependencies;

            if (state.detail?.review) throw new Error('REVIEW_STOCK_WRITE_BLOCKED');
            if (state.bulkAction) throw Object.assign(new Error(t("bulkBusy")), { code: "BULK_BUSY" });
            if (!canValidateHere()) throw Object.assign(new Error(t(isSale(state.detail)?"scannerOnlyValidate":"posOnlyValidate")), { code: "POS_ONLY_VALIDATE" });
            assertWritableDetail();
            if (!state.detail || !state.session) throw Object.assign(new Error("配货页面已经切换，未执行验收"), { code: "STALE_CONTEXT" });
            if (state.detail.request) throw Object.assign(new Error(t("waitingFormal")), { code: "WAITING_PAYMENT" });
            const context = { pickingId: Number(state.detail.picking.id), row: state.detail.row, session: { ...state.session } };
            if (!await showPrompt(t("validateConfirm"), "confirm", { title: t("validate"), confirmLabel: t("validate") })) return { cancelled: true };
            if (!state.detail || Number(state.detail.picking.id) !== context.pickingId || state.session?.token !== context.session.token) throw Object.assign(new Error("配货页面已经切换，未执行验收"), { code: "STALE_CONTEXT" });
            let detail = await loadDetail(context.row);
            assertWritableDetail(detail);
            if (Number(detail.picking.id) !== context.pickingId) throw Object.assign(new Error("交货单上下文已经变化，未填写原生数量"), { code: "STALE_CONTEXT" });
            this.assertReady(detail, context);
            if(!packingConfirmed(detail))throw bridgeError('请先确认配齐，再验收出库。','Confirme el surtido antes de validar la salida.');
            const nativePickingId=detail.bridge?.paid?detail.bridge.target.id:detail.picking.id;
            const nativeMoves=detail.bridge?.paid?detail.bridge.nativeMoves:detail.moves;
            await assertAcceptancePayment(detail,nativePickingId);
            if(detail.tech.unknownScans?.length)throw Object.assign(new Error(state.lang==='es'?'Resuelva los códigos no reconocidos.':'请先处理未识别条码记录。'),{code:'UNKNOWN_SCANS_REMAIN'});
            const validationToken = Core.makeId("validation");
            const guardDetail = detail;
            let guardAcquired = false, retainGuard = false, nativeCommitStarted = false, validationCompleted = false;
            try {
            detail = await validationControl(detail, context.session, "validation_begin", validationToken);
            guardAcquired = true;
            assertBridgeTargetSnapshot(detail,nativePickingId,nativeMoves);
            await assertAcceptancePayment(detail,nativePickingId);
            if (!Core.canFinalize(detail.tech, detail.moves) || !Core.assertBaseline(detail.tech, detail.moves).ok) throw Object.assign(new Error(t("cannotValidate")), { code: "NOT_READY" });
            saveUndoRecord(context.pickingId, null);
            render();
            const attempted = [];
            try {
                for (const move of nativeMoves) {
                    if(detail.bridge?.paid){
                        const nativeState=await readOne('stock.picking',nativePickingId,['id','state']);
                        if(!nativeState||['done','cancel'].includes(nativeState.state))throw bridgeError('实际交货单已完成或取消，停止填写数量。','La entrega ya está terminada o cancelada.');
                    }
                    const lockCheck = await readOne("stock.picking", detail.picking.id, [state.fieldMap.tech]);
                    if (!Core.verifyLock(Core.safeParse(lockCheck[state.fieldMap.tech]), context.session)) {
                        throw Object.assign(new Error("配货期间发生设备接管"), { code: "LOCK_LOST" });
                    }
                    attempted.push(move.id);
                    await stockWriter.writeMoveQuantity(move.id, Core.demandOf(move), true);
                }
                const finalLockCheck = await readOne("stock.picking", detail.picking.id, [state.fieldMap.tech]);
                if (!Core.verifyLock(Core.safeParse(finalLockCheck[state.fieldMap.tech]), context.session)) {
                    throw Object.assign(new Error("配货期间发生设备接管"), { code: "LOCK_LOST" });
                }
            } catch (error) {
                if (!attempted.length) throw error;
                retainGuard = true;
                let observation;
                try {
                    const rows = await searchRead("stock.move", [["id","in",attempted],["picking_id","=",nativePickingId]],
                        ["id","quantity","picked","state"], {limit:attempted.length});
                    observation = rows.map(m => m.id+"="+m.quantity+" ("+m.state+", picked="+m.picked+")").join(", ");
                } catch (readError) { observation = readError.message; }
                throw Object.assign(new Error(pbUiText("已停止填写。请核对交货单","Escritura detenida. Revise la entrega")+
                    " #"+nativePickingId+" ["+attempted.join(", ")+"] · "+(observation||"?")+" · "+error.message),
                    {code:"NATIVE_FILL_UNCERTAIN",cause:error});
            }
            retainGuard = true;
            detail = await loadDetail(context.row);
            assertWritableDetail(detail);
            assertBridgeTargetSnapshot(detail,nativePickingId,nativeMoves);
            if (!Core.verifyLock(detail.tech, context.session)) throw Object.assign(new Error("原生数量已填写，但配货已被其他设备接管；请由当前设备重新打开并核对"), { code: "LOCK_LOST" });
            const nativeOp = { id: Core.makeId("native"), scope: "native", type: "filled", validationToken, source: "manual_validate", pickingId: detail.picking.id };
            await createSharedEvent(nativeOp, detail, context.session);
            const events = await loadSharedEvents(detail.picking.id);
            const nativeTech = Core.replaySharedEvents(detail.tech, detail.moves, events);
            await writeTech(detail, nativeTech, detail.moves);
            const readback = await readOne("stock.picking", detail.picking.id, [state.fieldMap.tech]);
            const verified = Core.safeParse(readback[state.fieldMap.tech]);
            if (!verified || !Core.verifyLock(verified, context.session) || !verified.audit?.some((item) => item.event === "native_quantities_filled") || verified.eventSync?.rejectedEvents?.some((item) => item.id === nativeOp.id)) {
                throw Object.assign(new Error("原生数量已填写，但最终同步校验失败；请重新打开订单核对"), { code: "VERIFY_FAILED" });
            }
            detail = await validationControl(detail, context.session, "validation_commit", validationToken);
            assertWritableDetail(detail);
            assertBridgeTargetSnapshot(detail,nativePickingId,nativeMoves);
            await assertAcceptancePayment(detail,nativePickingId);
            nativeCommitStarted = true;
            const validationResult = await stockWriter.validateTransfer(nativePickingId);
            this.assertNativeActionAccepted(validationResult);
            const finalPicking = await readOne("stock.picking", nativePickingId, ["id", "state", "date_done"]);
            this.assertNativeCompleted(finalPicking);
            await this.verifyCompletedMoves(nativePickingId, nativeMoves);
            // Only publish the custom completion label after Odoo has confirmed
            // the stock transfer. Failure here must never invite another delivery.
            let completionStatusError = null;
            try {
                const statusField = state.fieldMap.status;
                const doneValue = state.fieldMap.statusValue?.[Core.STATUS.DONE];
                if (!statusField || doneValue == null) throw new Error(pbUiText("配货状态缺少“已完成”选项","Falta la opción «Terminado» en el estado de surtido."));
                await metadataWriter.writeCompletionStatus(nativePickingId, statusField, doneValue);
                finalPicking[statusField] = doneValue;
            } catch (error) {
                completionStatusError = error;
                console.warn("[PBFUL] Delivery completed; custom status update failed", error);
            }
            if(detail.bridge?.paid){
                detail.bridge.target=finalPicking;
                try {await publishBridgeStatus(detail.bridge,verified,detail.moves);}
                catch(error){completionStatusError ||= error;console.warn('[PBFUL] Stock completed; bridge summary update pending',error);}
            }
            state.lastSavedAt = Date.now(); state.saveError = "";
            const contextActive = state.detail && Number(state.detail.picking.id) === context.pickingId && state.session?.token === context.session.token;
            if (contextActive) {
                enterReadOnlyDetail({ ...detail, picking: { ...detail.picking, ...finalPicking, id:context.pickingId }, tech: verified, sharedEvents: events, sharedEventCount: events.length, stockNeedsRefresh: true });
                toast(t("validated"), "ok", 3000);
                render();
                // Completion is already confirmed. A display refresh failure must
                // never be reported as a failed stock validation or enable retry.
                try { await reloadReadOnlyDetail(); }
                catch (error) { console.warn("[PBFUL] Completed detail refresh failed", error); }
                if (completionStatusError && Number(state.detail?.picking?.id) === context.pickingId) {
                    toast(state.lang === "es"
                        ? "La salida ya está completada, pero no se actualizó la etiqueta de surtido. No vuelva a validar; revise el estado de surtido en la entrega Odoo."
                        : "库存已完成出库，但“配货状态”标签未更新。请勿重复验收；请在系统交货单检查配货状态。", "warn");
                }
            }
            validationCompleted = true;
            return { verified, contextActive, validated: true, completionStatusSynced: !completionStatusError };
            } catch (error) {
                // A lost response is NOT proof that the transfer failed. Never retry
                // button_validate or clear its guard based on a network error.
                retainGuard = retainGuard || isNetworkError(error);
                if (nativeCommitStarted && isNetworkError(error)) {
                    try {
                        const native = await readOne("stock.picking",nativePickingId,["id","state"]);
                        this.assertNativeCompleted(native);
                        await this.verifyCompletedMoves(nativePickingId,nativeMoves);
                        const fresh = await readTaskDetail(context.row);
                        if (isReadOnlyDetail(fresh)) {
                            if (Number(state.detail?.picking.id) === context.pickingId) { enterReadOnlyDetail(fresh); render(); }
                            return { validated: true, recovered: true };
                        }
                    } catch (_checkError) { /* the durable guard remains */ }
                    throw Object.assign(new Error(t("validationUncertain")), { code: "VALIDATION_UNCERTAIN" });
                }
                throw error;
            } finally {
                if (guardAcquired && !retainGuard && !validationCompleted) {
                    try { await validationControl(guardDetail, context.session, "validation_end", validationToken); }
                    catch (error) { console.warn("[PBFUL] Validation guard retained; check native delivery", error); }
                }
            }

        }
    }

    const nativeAcceptanceService = new NativeAcceptanceService(state, nativeStockWriter, fulfillmentMetadataWriter, {
        Core,
        assertAcceptancePayment,
        assertBridgeTargetSnapshot,
        assertWritableDetail,
        bridgeError,
        canValidateHere,
        createSharedEvent,
        enterReadOnlyDetail,
        isNetworkError,
        isReadOnlyDetail,
        isSale,
        loadDetail,
        loadSharedEvents,
        packingConfirmed,
        pbUiText,
        publishBridgeStatus,
        readOne,
        reloadReadOnlyDetail,
        render,
        saveUndoRecord,
        showPrompt,
        t,
        toast,
        validationControl,
        writeTech
    });

    function finalizeNative() {
        if (state.detail?.review) return completeUnifiedReview();
        return nativeAcceptanceService.accept();
    }

    // Batch actions reuse the existing revision-checked snapshot event understood by v0.13.25+.
    // One event changes the whole batch; concurrent quantity changes reject it as a whole.
    function validationBusy(detail = state.detail) {
        return Boolean(detail && (detail.tech?.validation || Number(state.validationAction?.pickingId) === Number(detail.picking.id)));
    }

    function validationBusyMessage() {
        return state.lang === 'es' ? 'Este pedido se está validando. Espere; no modifique las cantidades.' : '本单正在验收，暂不能修改数量，请稍候。';
    }

    function assertNotValidating(detail = state.detail) {
        if (validationBusy(detail)) throw Object.assign(new Error(validationBusyMessage()), { code: 'VALIDATION_BUSY' });
    }

    function undoStore() { return loadJson('pbful_bulk_undo_v1', {}); }
    function saveUndoRecord(id, record) {
        const store = undoStore();
        if (record) store[String(id)] = record; else delete store[String(id)];
        const entries = Object.entries(store).sort((a, b) => Number(b[1]?.at || 0) - Number(a[1]?.at || 0)).slice(0, 100);
        try { saveJson('pbful_bulk_undo_v1', Object.fromEntries(entries)); }
        catch (error) { if (record) throw error; /* Deleting an optional undo cache cannot block a quantity operation. */ }
    }

    function bulkUndoRecord(detail = state.detail) {
        if (!detail) return null;
        const record = undoStore()[String(detail.picking.id)];
        if (!record) return null;
        if (isReadOnlyDetail(detail) || detail.request?.x_pb_state === 'cancelled' || detail.request?.x_pb_change_pending || record.fingerprint !== bulkFingerprint(detail) || record.revision !== Core.quantityRevision(detail.tech)) {
            saveUndoRecord(detail.picking.id, null); return null;
        }
        return record;
    }

    function rememberBulkUndo(detail, before, kind, batchId, startEventId) {
        // Do not hide an intervening edit made by another device inside a batch.
        const intervened = (detail.sharedEvents || []).map(Core.normalizeSharedEvent).some(e => e.serverId > startEventId && (!e.op.scope || ['order', 'extra', 'bulk_restore'].includes(e.op.scope)) && e.op.bulkId !== batchId);
        if (intervened) { saveUndoRecord(detail.picking.id, null); return; }
        saveUndoRecord(detail.picking.id, { at: Date.now(), kind, batchId, snapshot: before, fingerprint: bulkFingerprint(detail), baseline: Core.quantityBaseline(detail.moves), revision: Core.quantityRevision(detail.tech) });
    }

    async function undoBulkQuantities() {
        if(state.scanOnly || state.scanAlert)return;
        if (state.bulkAction || state.mutationSyncing || state.offlineFlushing || state.scanProcessing || state.scanQueue.length) return toast(t('bulkBusy'), 'warn');
        assertBulkWritable(); assertNotValidating();
        const record = bulkUndoRecord();
        if (!record) return showPrompt(t('undoExpired'), 'warn');
        const context = { id: Core.makeId('undo-batch'), pickingId: Number(state.detail.picking.id), token: state.session.token, kind: 'undo' };
        state.bulkAction = context; render();
        try {
            if (state.quantityDrafts.size || !navigator.onLine || offlineQueue().some(op => Number(op.pickingId) === context.pickingId)) throw new Error(t('bulkNeedSync'));
            if (!await showPrompt(t('bulkUndoConfirm'), 'confirm', { title: t('bulkUndo'), confirmLabel: t('bulkUndo') })) return { cancelled: true };
            while (state.sharedPulling) await sleep(25);
            await syncSharedState({ writeAggregate: false, renderView: false });
            if (Number(state.detail?.picking.id) !== context.pickingId || state.session?.token !== context.token) throw Object.assign(new Error(t('bulkChanged')), { code: 'STALE_CONTEXT' });
            assertBulkWritable(); assertNotValidating();
            if (bulkUndoRecord()?.batchId !== record.batchId) throw Object.assign(new Error(t('undoExpired')), { code: 'UNDO_STALE' });
            const result = await queueOperation({ id: Core.makeId('restore'), scope: 'bulk_restore', type: 'restore', pickingId: context.pickingId, bulkId: context.id, bulkBaseline: record.fingerprint, baseline: record.baseline, expectedRevision: record.revision, snapshot: record.snapshot, batchId: record.batchId, source: 'bulk_undo', at: new Date().toISOString(), quiet: true });
            if (result.ok && !result.offline) { saveUndoRecord(context.pickingId, null); state.lastAction = null; toast(t('bulkUndoSaved'), 'ok'); }
            return result;
        } finally { if (state.bulkAction === context) state.bulkAction = null; render(); focusScan(); }
    }

    function validationProblems(detail = state.detail) {
        if (!detail) return [];
        const es = state.lang === 'es', problems = [], add = (text, selector) => problems.push({ text, selector });
        if (!state.session) add(es ? 'Ingrese el nombre e inicie el surtido.' : '请先填写配货员并开始配货。', '[data-act="claim"]');
        if (state.quantityDrafts.size) add(es ? 'Hay cantidades sin guardar o no válidas.' : '还有未保存或无效的数量，请检查数量框。', 'input[data-qty-for],input[data-extra-qty-for]');
        if (state.queuedMutations || state.offlineFlushing || offlineQueue().some(op => Number(op.pickingId) === Number(detail.picking.id))) add(es ? 'Hay cantidades pendientes de subir al servidor.' : '本单有数量尚未上传服务器，请先同步。', '[data-act="sync-offline"]');
        const paymentProblem=acceptancePaymentProblem(detail);
        if (paymentProblem) add(paymentProblem, '.pbful-status-badge');
        if (detail.request?.x_pb_change_pending || !Core.assertBaseline(detail.tech, detail.moves).ok) add(t('orderChanged'), '.pbful-critical-banner');
        if (detail.request?.x_pb_state === 'cancelled') add(t('orderCancelledNotice'), '.pbful-critical-banner');
        const products = new Map(detail.products.map(p => [Number(p.id), p]));
        for (const move of detail.moves) {
            const delta = Core.demandOf(move) - Number(detail.tech.counts?.[move.id] || 0);
            if (!delta) continue;
            const product = products.get(m2oId(move.product_id));
            const label = product?.default_code || product?.display_name || move.product_id?.[1] || `#${move.id}`;
            add(`${label}：${delta > 0 ? (es ? 'Faltan' : '欠配') : (es ? 'Sobran' : '超量')} ${Math.abs(delta)}`, `[data-move-id="${Number(move.id)}"]`);
        }
        if (Core.extraTotal(detail.tech)) add(`${es ? 'Productos fuera del pedido' : '错配商品'}：${Core.extraTotal(detail.tech)}`, '.pbful-wrong-panel');
        if (detail.tech.unknownScans?.length) add(`${t('unknownHistory')}：${detail.tech.unknownScans.length}`, '.pbful-unknown-log');
        if (detail.tech.exception?.active) add(`${es ? 'Incidencia pendiente' : '异常未处理'}：${detail.tech.exception.reason || ''} ${detail.tech.exception.note || ''}`, '.pbful-issue-panel');
        if (!detail.moves.length) add(es ? 'El pedido no tiene productos.' : '本单没有可配商品。', '.pbful-lines');
        return problems;
    }

    async function explainValidationProblems() {
        const problems=validationProblems();if(!problems.length)return false;
        state.validationIssues={pickingId:state.detail?.picking.id};
        state.messageDrawerOpen=true;render();setMessageDrawer(true);return true;
    }

    async function validationControl(detail, session, type, token) {
        const op = { id: Core.makeId(type), scope: 'safety', type, token, baseline: Core.quantityBaseline(detail.moves), pickingId: detail.picking.id, source: 'pos_validation' };
        await createSharedEvent(op, detail, session);
        const refreshed = await loadDetail(detail.row);
        if (refreshed.tech.eventSync?.rejectedEvents?.some(e => e.id === op.id)) throw Object.assign(new Error(validationBusyMessage()), { code: 'VALIDATION_BUSY' });
        if (type !== 'validation_end' && refreshed.tech.validation?.token !== token) throw Object.assign(new Error(validationBusyMessage()), { code: 'VALIDATION_BUSY' });
        if (Number(state.detail?.picking.id) === Number(detail.picking.id)) state.detail = refreshed;
        return refreshed;
    }

    async function checkValidationResult() {
        const old = state.detail;
        if (!old || state.validationAction) return;
        const fresh = await readTaskDetail(old.row);
        if (Number(state.detail?.picking.id) !== Number(old.picking.id)) return;
        if (isReadOnlyDetail(fresh)) { enterReadOnlyDetail(fresh); render(); return; }
        state.detail = fresh; render();
        if (fresh.tech.validation) await showPrompt(t('validationUncertain'), 'warn');
    }

    async function requestValidation() {
        if (!canValidateHere()) return toast(t(isSale(state.detail)?'scannerOnlyValidate':'posOnlyValidate'), 'warn');
        if (validationBusy()) return checkValidationResult();
        if (state.bulkAction) return toast(t('bulkBusy'), 'warn');
        const id = state.detail?.picking.id;
        await state.mutationQueue;
        if (!id || state.detail?.picking.id !== id || state.validationAction) return;
        if (await explainValidationProblems()) return;
        if(!packingConfirmed())return toast(state.lang==='es'?'Confirme primero el surtido.':'请先确认配齐，再实际交货出库。','warn');
        if (state.detail?.picking.id !== id || state.validationAction || validationBusy()) return;
        // The guard is acquired inside finalizeNative, after the normal confirmation.
        const action = { pickingId: id };
        state.validationAction = action; render();
        try { return await withDeviceMutationLock(id, () => finalizeNative()); }
        finally { if (state.validationAction === action) state.validationAction = null; if (state.detail) render(); }
    }

    function bulkFingerprint(detail, counts = false) {
        const moves = detail.moves.map(move => [Number(move.id), m2oId(move.product_id), Number(move.product_uom_qty)]).sort((a, b) => a[0] - b[0]);
        const values = counts ? [moves.map(([id]) => Number(detail.tech.counts?.[id] || 0)), Object.entries(detail.tech.extraCounts || {}).filter(([, n]) => Number(n) > 0).sort(([a], [b]) => Number(a) - Number(b))] : [];
        return JSON.stringify([moves, detail.request?.id || 0, detail.request?.x_pb_version || 0, detail.request?.x_pb_state || '', ...values]);
    }

    function assertBulkWritable() {
        assertWritableDetail(); assertNotValidating();
        if (state.detail?.request?.x_pb_state === 'cancelled' || ['done', 'cancel'].includes(state.detail?.picking?.state)) throw Object.assign(new Error(t('readOnly')), { code: 'TERMINAL' });
        if (!state.detail || !state.session || !Core.verifyLock(state.detail.tech, state.session)) throw Object.assign(new Error(t('bulkStartFirst')), { code: 'LOCK_LOST' });
        if (state.detail.request?.x_pb_change_pending) throw Object.assign(new Error(t('orderChanged')), { code: 'ORDER_CHANGED' });
        if (state.detail.tech.audit?.some(item => item.event === 'native_quantities_filled')) throw Object.assign(new Error(t('bulkNativeFilled')), { code: 'NATIVE_FILLED' });
    }

    function makeBulkOperations(detail, kind, batchId) {
        if (!['clear', 'fill'].includes(kind)) throw new Error('Unknown bulk action');
        const baseline = bulkFingerprint(detail);
        const operations = [];
        for (const move of detail.moves) {
            const value = kind === 'clear' ? 0 : Number(move.product_uom_qty);
            if (!Number.isSafeInteger(value) || value < 0) throw Object.assign(new Error(t('invalidQuantity')), { code: 'INVALID_QUANTITY' });
            if (Number(detail.tech.counts?.[move.id] || 0) !== value) operations.push({ type: 'set', moveId: move.id, value, allowOverScan: true });
        }
        if (kind === 'clear') for (const [id, count] of Object.entries(detail.tech.extraCounts || {})) {
            if (Number(count) > 0) operations.push({ scope: 'extra', type: 'set', productId: Number(id), value: 0 });
        }
        return operations.map(op => ({ ...op, id: Core.makeId('op'), pickingId: detail.picking.id, source: `bulk_${kind}`, code: `BULK_${kind.toUpperCase()}`, bulkId: batchId, bulkBaseline: baseline, quiet: true }));
    }

    function makeBulkSnapshotOperation(detail, kind, batchId, operations) {
        const snapshot = {
            counts: Object.fromEntries(detail.moves.map(move => [String(move.id), Number(detail.tech.counts?.[move.id] || 0)])),
            extraCounts: { ...detail.tech.extraCounts }
        };
        for (const operation of operations) {
            if (operation.scope === 'extra') {
                if (operation.value > 0) snapshot.extraCounts[String(operation.productId)] = operation.value;
                else delete snapshot.extraCounts[String(operation.productId)];
            } else snapshot.counts[String(operation.moveId)] = operation.value;
        }
        return {
            id: Core.makeId('batch-snapshot'), scope: 'bulk_restore', type: 'restore',
            pickingId: detail.picking.id, bulkId: batchId, batchId,
            bulkBaseline: bulkFingerprint(detail), baseline: Core.quantityBaseline(detail.moves),
            expectedRevision: Core.quantityRevision(detail.tech), snapshot,
            source: `bulk_${kind}`, code: `BULK_${kind.toUpperCase()}`, at: new Date().toISOString(), quiet: true
        };
    }

    async function runBulkQuantities(kind) {
        if(state.scanOnly || state.scanAlert)return;
        if (!['clear', 'fill'].includes(kind)) throw new Error('Unknown bulk action');
        if (state.bulkAction || state.mutationSyncing || state.offlineFlushing || state.scanProcessing || state.scanQueue.length) return toast(t('bulkBusy'), 'warn');
        assertBulkWritable();
        const context = { id: Core.makeId('batch'), pickingId: Number(state.detail.picking.id), token: state.session.token, kind };
        const contextActive = () => state.detail && Number(state.detail.picking.id) === context.pickingId && state.session?.token === context.token;
        state.bulkAction = context;
        render();
        try {
            await state.mutationQueue;
            if (!contextActive()) throw Object.assign(new Error(t('bulkChanged')), { code: 'STALE_CONTEXT' });
            assertBulkWritable();
            if (state.quantityDrafts.size) throw new Error(t('bulkDrafts'));
            if (!navigator.onLine || offlineQueue().some(op => Number(op.pickingId) === context.pickingId)) throw new Error(t('bulkNeedSync'));
            const before = bulkFingerprint(state.detail, true);
            const title = t(kind === 'clear' ? 'bulkClear' : 'bulkFill');
            const order = state.detail.row.order.pos_reference || state.detail.row.order.name || state.detail.picking.name;
            if (!await showPrompt(`${order}\n\n${t(kind === 'clear' ? 'bulkClearConfirm' : 'bulkFillConfirm')}`, 'confirm', { title, confirmLabel: title })) return { cancelled: true };
            if (!contextActive()) throw Object.assign(new Error(t('bulkChanged')), { code: 'STALE_CONTEXT' });
            while (state.sharedPulling) await sleep(25);
            await syncSharedState({ writeAggregate: false, renderView: false });
            if (!contextActive()) throw Object.assign(new Error(t('bulkChanged')), { code: 'STALE_CONTEXT' });
            assertBulkWritable();
            if (before !== bulkFingerprint(state.detail, true)) throw Object.assign(new Error(t('bulkChanged')), { code: 'ORDER_CHANGED' });
            const undoBefore = { counts: Object.fromEntries(state.detail.moves.map(m => [m.id, Number(state.detail.tech.counts?.[m.id] || 0)])), extraCounts: { ...state.detail.tech.extraCounts } };
            const undoStartEventId = Number(state.detail.tech.eventSync?.lastEventId || 0);
            const operations = makeBulkOperations(state.detail, kind, context.id);
            if (!operations.length) { toast(t('bulkNoChange'), 'info'); return { ok: true, completed: 0, total: 0 }; }
            saveUndoRecord(context.pickingId, null);
            const operation = makeBulkSnapshotOperation(state.detail, kind, context.id, operations);
            // Show the requested quantities immediately; this preview is never used as saved state.
            context.previewOp = operation;
            render();
            const result = await queueOperation(operation);
            if (!result.ok || result.offline) {
                toast(result.offline
                    ? (state.lang === 'es' ? 'Cambio en lote pendiente de sincronizar.' : '批量操作待同步。')
                    : t('bulkChanged'), 'warn');
                return { ok: false, completed: 0, total: operations.length, offline: Boolean(result.offline), error: result.error };
            }
            if (!contextActive()) throw Object.assign(new Error(t('bulkChanged')), { code: 'STALE_CONTEXT' });
            const completed = operations.length;
            rememberBulkUndo(state.detail, undoBefore, kind, context.id, undoStartEventId);
            state.lastAction = null;
            toast(`${title} · ${t('bulkSaved')} ${completed}/${operations.length}`, 'ok', 3500);
            return { ok: true, completed, total: operations.length };
        } finally {
            if (state.bulkAction === context) state.bulkAction = null;
            render(); focusScan();
        }
    }
