        operations: [...pending.values()].sort((a,b) => Number(a.queuedAt || 0) - Number(b.queuedAt || 0) ||
            String(a.queuedOrigin || "").localeCompare(String(b.queuedOrigin || "")) || Number(a.queuedOrder || 0) - Number(b.queuedOrder || 0)),
        errors
