            if(saleChanged(task.detail))return Promise.resolve({ok:false,error:Object.assign(new Error(t("saleStale")),{code:"ORDER_CHANGED"})});
            if(isSale(task.detail))op={...op,salesBaseline:op.salesBaseline || Core.quantityBaseline(task.detail.moves)};
