        closeImagePreview(false);
        if (state.view !== "detail") return true;
        const pickingId = state.detail?.picking?.id;
        const token = state.session?.token;
        const sameDetail = () => state.view === "detail" && state.detail?.picking?.id === pickingId && state.session?.token === token;
        const initialAlert = state.scanAlert;
