        stopCamera(); resetScanInputCandidate(false); resetExternalScanBuffer(false); cancelScanFinalization(); clearProductSearch(false); productSearchInputElement()?.blur(); pickerNameInputElement()?.blur(); state.productInputFocused = false; state.messageDrawerOpen = false; state.messageDrawerDismissed = false; state.messagePaneTyped = false; state.open = false; state.view = "dashboard"; state.detail = null; state.session = null; state.pickerDraft = null; state.lastAction = null; state.lastMoveId = null; render();
