            if (isReadOnlyDetail() && (["claim", "force", "camera", "manual-scan", "undo", "exception", "resolve", "validate", "bulk-clear", "bulk-fill"].includes(act) || ["setQty", "extraSet", "extraClear", "extraInc", "extraDec", "unknownDelete", "productAdd", "inc", "dec"].some(key => el.dataset[key]))) return;
